import { DurableObject } from "cloudflare:workers";

const DIA = 24 * 60 * 60 * 1000;
/* versão do site: muda sozinha a cada publicação; os aparelhos abertos percebem e se atualizam */
const VERSAO = "92d38f1e24";
/* Código secreto do dono do site. Fica só no servidor. Mantenha o repositório do GitHub como PRIVADO. */
const DONO_CODE = "DONO-4SWN-XYD4";

/* Roteador: /ws/CODIGO abre a sala em tempo real; qualquer outro endereço mostra o site. */
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) return rotaConta(request, env, url);
    if (url.pathname === "/ws-online") {
      if (request.headers.get("Upgrade") !== "websocket") return new Response("Esta rota aceita apenas WebSocket.", { status: 426 });
      return env.SALAS.get(env.SALAS.idFromName("__online__")).fetch(request);
    }
    const m = url.pathname.match(/^\/ws\/([A-Z0-9]{4})$/);
    if (m) {
      if (request.headers.get("Upgrade") !== "websocket") {
        return new Response("Esta rota aceita apenas WebSocket.", { status: 426 });
      }
      const sala = env.SALAS.get(env.SALAS.idFromName(m[1]));
      return sala.fetch(request);
    }
    return new Response(SITE, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
  }
};

/* ---------- Contas: cada usuário tem seu próprio cofre (Durable Object "conta:usuario") ---------- */
const ROTAS = ["/api/criar", "/api/entrar", "/api/sair", "/api/progresso", "/api/eu", "/api/dono"];
const jsonResp = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });

async function rotaConta(request, env, url) {
  if (!ROTAS.includes(url.pathname)) return jsonResp({ erro: "Rota desconhecida." }, 404);
  const len = +(request.headers.get("content-length") || 0);
  if (len > 150000) return jsonResp({ erro: "Dados grandes demais." }, 413);
  let user = "", corpo = null;
  if (url.pathname === "/api/criar" || url.pathname === "/api/entrar") {
    if (request.method !== "POST") return jsonResp({ erro: "Método inválido." }, 405);
    corpo = await request.text();
    try { user = String(JSON.parse(corpo).user || ""); } catch { return jsonResp({ erro: "Dados inválidos." }, 400); }
  } else {
    user = request.headers.get("x-user") || "";
    if (request.method !== "GET") corpo = await request.text();
  }
  user = user.trim().toLowerCase();
  if (!/^[a-z0-9._]{3,20}$/.test(user)) return jsonResp({ erro: "Usuário inválido: use de 3 a 20 letras sem acento, números, ponto ou _." }, 400);
  const cofre = env.SALAS.get(env.SALAS.idFromName("conta:" + user));
  const headers = new Headers({ "content-type": "application/json", "x-user": user });
  const auth = request.headers.get("authorization");
  if (auth) headers.set("authorization", auth);
  return cofre.fetch(new Request(url.toString(), { method: request.method, headers, body: corpo }));
}

const hex = buf => Array.from(new Uint8Array(buf), b => b.toString(16).padStart(2, "0")).join("");
const aleatorio = n => hex(crypto.getRandomValues(new Uint8Array(n)));
async function hashSenha(senha, saltHex) {
  const salt = new Uint8Array(saltHex.match(/../g).map(h => parseInt(h, 16)));
  const chave = await crypto.subtle.importKey("raw", new TextEncoder().encode(senha), "PBKDF2", false, ["deriveBits"]);
  return hex(await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt, iterations: 100000 }, chave, 256));
}
function iguais(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
const NUMS = ["r", "e", "i", "d", "l", "n", "a", "k", "t"];
function limparProgresso(p) {
  const srs = {}, hist = {};
  if (p && p.srs && typeof p.srs === "object") {
    for (const id of Object.keys(p.srs).slice(0, 300)) {
      if (!okId(id) || !p.srs[id] || typeof p.srs[id] !== "object") continue;
      const o = {};
      for (const k of NUMS) { const v = p.srs[id][k]; if (typeof v === "number" && isFinite(v)) o[k] = v; }
      srs[id] = o;
    }
  }
  if (p && p.hist && typeof p.hist === "object") {
    for (const d of Object.keys(p.hist).slice(-800)) {
      const v = p.hist[d];
      if (/^\d{4}-\d{2}-\d{2}$/.test(d) && Array.isArray(v)) hist[d] = [Math.max(0, v[0] | 0), Math.max(0, v[1] | 0)];
    }
  }
  return { srs, hist };
}

const agoraMs = () => Date.now();
const okPid = x => typeof x === "string" && /^[0-9a-f]{12}$/.test(x);
async function pidDe(segredo) {
  const h = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("pato-n1:" + segredo));
  return Array.from(new Uint8Array(h).slice(0, 6), b => b.toString(16).padStart(2, "0")).join("");
}
function limparAjudantes(l) {
  if (!Array.isArray(l)) return [];
  const out = [], vistos = new Set();
  for (const x of l.slice(0, 30)) {
    if (!Array.isArray(x) || !okPid(x[0]) || vistos.has(x[0])) continue;
    vistos.add(x[0]);
    out.push([x[0], typeof x[1] === "string" ? x[1].slice(0, 24) : ""]);
  }
  return out;
}
/* grava na conexão lendo o dado mais recente (mensagens podem chegar quase juntas) */
function anotar(ws, mudancas) {
  const x = ws.deserializeAttachment() || {};
  Object.assign(x, mudancas);
  ws.serializeAttachment(x);
  return x;
}
const okTopic = t => typeof t === "string" && t.length <= 80 && /^(all|[a-z]+(,[a-z]+)*)$/.test(t);
const okId = s => typeof s === "string" && /^[a-z]\d{2}$/.test(s);
const okOrder = o => Array.isArray(o) && o.length >= 2 && o.length <= 6 && o.every(n => Number.isInteger(n) && n >= 0 && n < 6);

/* O que cada pessoa mostra de si: nome e a resposta marcada. */
function limparPresenca(p) {
  const out = {};
  if (p && typeof p.name === "string" && p.name.trim()) out.name = p.name.trim().slice(0, 24);
  if (p && p.ans && okId(p.ans.q) && Number.isInteger(p.ans.c) && p.ans.c >= 0 && p.ans.c < 6) out.ans = { q: p.ans.q, c: p.ans.c };
  if (p && p.voice === true) { out.voice = true; if (p.muted === true) out.muted = true; }
  return out;
}

/* Agenda de revisão da sala: { questão: [quando volta, acertos seguidos] } */
function limparAgenda(d) {
  const out = {};
  if (!d || typeof d !== "object") return out;
  for (const id of Object.keys(d).slice(0, 400)) {
    const v = d[id];
    if (okId(id) && Array.isArray(v) && typeof v[0] === "number" && isFinite(v[0])) out[id] = [Math.round(v[0]), Math.max(0, Math.min(20, v[1] | 0))];
  }
  return out;
}

/* Estado da sala sem a chave secreta do dono. */
function publico(st) {
  if (!st) return null;
  const { key, hist, ...resto } = st;
  resto.histLen = Array.isArray(hist) ? hist.length : 0;
  return resto;
}

/* guarda a questão atual no histórico antes de trocar (para o botão "questão anterior") */
function empilhar(st, due0) {
  const agora = Date.now();
  const dur = Math.max(0, (st.revAt || agora) - (st.qStart || agora));
  st.hist = (Array.isArray(st.hist) ? st.hist : []).concat([{ qid: st.qid, order: st.order, idx: st.idx, dur, due0: due0 || null }]).slice(-30);
}

/*
  Uma Sala por código. O estado fica guardado no servidor, então a sala continua
  mesmo que todos fechem a página. Ela só acaba quando o dono encerra
  (ou depois de 24 horas sem nenhum uso). Usa hibernação: não gasta nada parada.
*/
export class Sala extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong"));
  }

  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/ws-online") {
      const par = new WebSocketPair();
      const [cli, srv] = Object.values(par);
      const peer = crypto.randomUUID().replace(/-/g, "").slice(0, 10);
      this.ctx.acceptWebSocket(srv);
      srv.serializeAttachment({ online: true, peer, desde: Date.now() });
      srv.send(JSON.stringify({ t: "hi", peer, v: VERSAO }));
      return new Response(null, { status: 101, webSocket: cli });
    }
    if (url.pathname.startsWith("/api/")) return this.conta(request, url);
    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    const peer = crypto.randomUUID().replace(/-/g, "").slice(0, 10);
    this.ctx.acceptWebSocket(server);
    server.serializeAttachment({ peer, presence: {} });
    const [state, chat] = await Promise.all([this.ctx.storage.get("state"), this.ctx.storage.get("chat")]);
    if (state) await this.renovar();
    server.send(JSON.stringify({ t: "hello", peer, peers: this.lista(), chat: chat || [], state: publico(state), now: Date.now() }));
    return new Response(null, { status: 101, webSocket: client });
  }

  /* ---------- Quem está online no site (só o dono recebe a lista) ---------- */
  async onlineMsg(ws, m) {
    if (m.t === "here") {
      const i = m.info && typeof m.info === "object" ? m.info : {};
      const info = {
        name: typeof i.name === "string" && i.name.trim() ? i.name.trim().slice(0, 24) : "Visitante",
        user: typeof i.user === "string" && /^[a-z0-9._]{3,20}$/.test(i.user) ? i.user : null,
        where: typeof i.where === "string" ? i.where.slice(0, 90) : "",
        dev: ["celular", "tablet", "computador"].includes(i.dev) ? i.dev : ""
      };
      anotar(ws, { info });
      this.avisarAdmins();
      return;
    }
    if (m.t === "admin") {
      const user = typeof m.user === "string" ? m.user.trim().toLowerCase() : "";
      if (!/^[a-z0-9._]{3,20}$/.test(user) || typeof m.token !== "string") return;
      let ok = false;
      try {
        const cofre = this.env.SALAS.get(this.env.SALAS.idFromName("conta:" + user));
        const r = await cofre.fetch(new Request("https://interno/api/_verify", { headers: { "x-user": user, "authorization": "Bearer " + m.token } }));
        const d = await r.json();
        ok = r.status === 200 && d && d.admin === true;
      } catch (e) { ok = false; }
      if (ok) {
        anotar(ws, { admin: true });
        ws.send(JSON.stringify({ t: "online", list: this.listaOnline(), now: Date.now() }));
      } else {
        anotar(ws, { admin: false });
        ws.send(JSON.stringify({ t: "notadmin" }));
      }
    }
  }

  listaOnline(excluir) {
    return this.ctx.getWebSockets()
      .filter(s => s !== excluir && s.readyState === 1)
      .map(s => s.deserializeAttachment())
      .filter(x => x && x.online && x.info)
      .map(x => ({ peer: x.peer, info: x.info, desde: x.desde }));
  }

  avisarAdmins(excluir) {
    const msg = JSON.stringify({ t: "online", list: this.listaOnline(excluir), now: Date.now() });
    for (const s of this.ctx.getWebSockets()) {
      if (s === excluir) continue;
      const x = s.deserializeAttachment();
      if (x && x.admin) { try { s.send(msg); } catch (e) {} }
    }
  }

  /* ---------- Cofre de uma conta ---------- */
  async conta(request, url) {
    const st = this.ctx.storage;
    const agora = Date.now();
    const acct = await st.get("acct");
    const lerCorpo = async () => { try { return await request.json(); } catch { return null; } };

    if (url.pathname === "/api/criar") {
      const b = await lerCorpo();
      const senha = b && typeof b.senha === "string" ? b.senha : "";
      if (senha.length < 4 || senha.length > 64) return jsonResp({ erro: "A senha precisa ter de 4 a 64 caracteres." }, 400);
      if (acct) return jsonResp({ erro: "Esse usuário já existe. Escolha outro nome ou entre na conta." }, 409);
      const salt = aleatorio(16);
      const token = aleatorio(24);
      await st.put("acct", { salt, hash: await hashSenha(senha, salt), criado: agora, falhas: 0, bloqueio: 0 });
      await st.put("tokens", [{ token, t: agora }]);
      return jsonResp({ ok: true, token });
    }

    if (url.pathname === "/api/entrar") {
      const b = await lerCorpo();
      const senha = b && typeof b.senha === "string" ? b.senha : "";
      if (!acct) return jsonResp({ erro: "Usuário ou senha incorretos." }, 401);
      if (acct.bloqueio > agora) return jsonResp({ erro: "Muitas tentativas erradas. Espere 10 minutos e tente de novo." }, 429);
      if (!iguais(await hashSenha(senha.slice(0, 64), acct.salt), acct.hash)) {
        acct.falhas = (acct.falhas || 0) + 1;
        if (acct.falhas >= 8) { acct.bloqueio = agora + 10 * 60 * 1000; acct.falhas = 0; }
        await st.put("acct", acct);
        return jsonResp({ erro: "Usuário ou senha incorretos." }, 401);
      }
      acct.falhas = 0; acct.bloqueio = 0;
      await st.put("acct", acct);
      const token = aleatorio(24);
      const tokens = ((await st.get("tokens")) || []).concat([{ token, t: agora }]).slice(-10);
      await st.put("tokens", tokens);
      return jsonResp({ ok: true, token });
    }

    // daqui para baixo precisa estar logado
    const token = (request.headers.get("authorization") || "").replace(/^Bearer\s+/, "");
    const tokens = (await st.get("tokens")) || [];
    if (!acct || !token || !tokens.some(x => iguais(x.token, token))) return jsonResp({ erro: "Sessão expirada. Entre de novo." }, 401);

    if (url.pathname === "/api/eu" || url.pathname === "/api/_verify") {
      return jsonResp({ user: request.headers.get("x-user") || "", admin: acct.admin === true });
    }
    if (url.pathname === "/api/dono") {
      if (request.method !== "POST") return jsonResp({ erro: "Método inválido." }, 405);
      if ((acct.donoBloqueio || 0) > agora) return jsonResp({ erro: "Muitas tentativas. Espere 30 minutos." }, 429);
      const b = await lerCorpo();
      const codigo = b && typeof b.codigo === "string" ? b.codigo.trim().toUpperCase() : "";
      if (!iguais(codigo, DONO_CODE)) {
        acct.donoFalhas = (acct.donoFalhas || 0) + 1;
        if (acct.donoFalhas >= 5) { acct.donoBloqueio = agora + 30 * 60 * 1000; acct.donoFalhas = 0; }
        await st.put("acct", acct);
        return jsonResp({ erro: "Código incorreto." }, 403);
      }
      acct.admin = true; acct.donoFalhas = 0;
      await st.put("acct", acct);
      return jsonResp({ ok: true, admin: true });
    }
    if (url.pathname === "/api/sair") {
      await st.put("tokens", tokens.filter(x => x.token !== token));
      return jsonResp({ ok: true });
    }
    if (url.pathname === "/api/progresso") {
      if (request.method === "GET") return jsonResp({ prog: (await st.get("prog")) || null });
      if (request.method === "PUT") {
        const b = await lerCorpo();
        if (!b || !b.prog) return jsonResp({ erro: "Dados inválidos." }, 400);
        const prog = limparProgresso(b.prog);
        prog.atualizado = agora;
        await st.put("prog", prog);
        return jsonResp({ ok: true, atualizado: agora });
      }
    }
    return jsonResp({ erro: "Método inválido." }, 405);
  }

  /* Cada uso empurra a limpeza automática para 24 h depois. */
  async renovar() {
    await this.ctx.storage.setAlarm(Date.now() + DIA);
  }

  lista(excluir) {
    return this.ctx.getWebSockets()
      .filter(ws => ws !== excluir && ws.readyState === 1)
      .map(ws => ws.deserializeAttachment())
      .filter(a => a && a.presence && a.presence.name)
      .map(a => ({ peer: a.peer, owner: !!a.owner, pid: a.pid || null, presence: a.presence }));
  }

  enviarTodos(obj, excluir) {
    const msg = JSON.stringify(obj);
    for (const ws of this.ctx.getWebSockets()) {
      if (ws === excluir) continue;
      try { ws.send(msg); } catch (e) { /* conexão fechando */ }
    }
  }

  avisarTodos(excluir) {
    this.enviarTodos({ t: "peers", peers: this.lista(excluir) }, excluir);
  }

  async webSocketMessage(ws, data) {
    if (typeof data !== "string" || data.length > 20000) return;
    let m;
    try { m = JSON.parse(data); } catch { return; }
    if (!m || typeof m !== "object") return;
    const a = ws.deserializeAttachment() || {};
    if (a.online) return this.onlineMsg(ws, m);

    if (m.t === "presence") {
      anotar(ws, { presence: limparPresenca(m.p) });
      this.avisarTodos();
      return;
    }

    /* voz: repassa os sinais de conexão (oferta, resposta, rotas) só para a pessoa certa */
    if (m.t === "sig") {
      if (typeof m.to !== "string" || !m.data || typeof m.data !== "object") return;
      const out = JSON.stringify({ t: "sig", from: a.peer, data: m.data });
      if (out.length > 20000) return;
      for (const s of this.ctx.getWebSockets()) {
        const x = s.deserializeAttachment();
        if (x && x.peer === m.to) { try { s.send(out); } catch (e) {} break; }
      }
      return;
    }

    if (m.t === "create") {
      if (await this.ctx.storage.get("state")) { ws.send(JSON.stringify({ t: "err", e: "existe" })); return; }
      if (typeof m.key !== "string" || m.key.length < 16 || m.key.length > 64 || !okId(m.qid) || !okOrder(m.order)) return;
      const novo = {
        key: m.key,
        topic: okTopic(m.topic) ? m.topic : "all",
        pool: Array.isArray(m.pool) ? m.pool.filter(okId).slice(0, 400) : [],
        idx: Number.isInteger(m.idx) ? m.idx : 0,
        qid: m.qid, order: m.order, phase: "q",
        ownerName: typeof m.name === "string" ? m.name.slice(0, 24) : "",
        due: {}, qStart: Date.now(), revAt: null,
        n: 1
      };
      await this.ctx.storage.put("state", novo);
      await this.renovar();
      anotar(ws, { owner: true });
      this.enviarTodos({ t: "state", state: publico(novo), now: Date.now() });
      this.avisarTodos();
      return;
    }

    if (m.t === "ident") {
      if (typeof m.k !== "string" || m.k.length < 16 || m.k.length > 64) return;
      const pid = await pidDe(m.k);
      anotar(ws, { pid });
      this.avisarTodos();
      return;
    }

    if (m.t === "claim") {
      const st = await this.ctx.storage.get("state");
      if (st && m.key === st.key) { anotar(ws, { owner: true }); this.avisarTodos(); }
      return;
    }

    if (m.t === "ctl") {
      const st = await this.ctx.storage.get("state");
      if (!st) return;
      const dono = typeof m.key === "string" && m.key === st.key;
      const eu = ws.deserializeAttachment() || {};
      const ajudante = !!eu.pid && (st.everyone === true || (st.helpers || []).some(h => h[0] === eu.pid));
      // dono: tudo. Ajudantes liberados pelo dono: só revelar e passar a questão.
      if (!dono && !(ajudante && (m.a === "reveal" || m.a === "next" || m.a === "back"))) return;
      if (m.a === "perm") {
        st.helpers = limparAjudantes(m.helpers);
        st.everyone = m.everyone === true;
        st.n = (st.n || 0) + 1;
        await this.ctx.storage.put("state", st);
        await this.renovar();
        this.enviarTodos({ t: "state", state: publico(st), now: Date.now() });
        return;
      }
      if (m.a === "end") {
        this.enviarTodos({ t: "state", state: null });
        await this.ctx.storage.deleteAlarm();
        await this.ctx.storage.deleteAll();
        for (const s of this.ctx.getWebSockets()) { try { s.close(1000, "encerrada"); } catch (e) {} }
        return;
      }
      if (m.a === "reveal") { if (st.phase !== "rev") { st.phase = "rev"; st.revAt = agoraMs(); } }
      else if (m.a === "next") {
        if (!okId(m.qid) || !okOrder(m.order) || !Number.isInteger(m.idx)) return;
        if (typeof m.cur === "string" && m.cur !== st.qid) return;   // alguém já passou esta questão
        empilhar(st, (st.due || {})[st.qid]);
        st.qid = m.qid; st.order = m.order; st.idx = m.idx; st.phase = "q";
        st.qStart = agoraMs(); st.revAt = null;
        if (Array.isArray(m.pool)) st.pool = m.pool.filter(okId).slice(0, 400);
        if (m.due) st.due = limparAgenda(m.due);
      } else if (m.a === "topic") {
        /* trocar ou somar assuntos sem desfazer a sala (chat e agenda continuam) */
        if (!okTopic(m.topic)) return;
        st.topic = m.topic;
        st.pool = Array.isArray(m.pool) ? m.pool.filter(okId).slice(0, 400) : [];
        st.idx = Number.isInteger(m.idx) ? m.idx : -1;
        if (okId(m.qid) && okOrder(m.order) && m.qid !== st.qid) {
          empilhar(st, (st.due || {})[st.qid]);
          st.qid = m.qid; st.order = m.order; st.phase = "q"; st.qStart = agoraMs(); st.revAt = null;
        }
      } else if (m.a === "back") {
        /* volta para a questão anterior, com a correção aberta e a avaliação desfeita */
        if (typeof m.cur === "string" && m.cur !== st.qid) return;
        const h = Array.isArray(st.hist) ? st.hist : [];
        if (!h.length) return;
        const ant = h.pop();
        st.hist = h;
        st.due = st.due || {};
        if (ant.due0) st.due[ant.qid] = ant.due0; else delete st.due[ant.qid];
        const agora = agoraMs();
        st.qid = ant.qid; st.order = ant.order; st.idx = ant.idx;
        st.phase = "rev"; st.qStart = agora - (ant.dur || 0); st.revAt = agora;
      } else return;
      st.n = (st.n || 0) + 1;
      await this.ctx.storage.put("state", st);
      await this.renovar();
      this.enviarTodos({ t: "state", state: publico(st), now: Date.now() });
      return;
    }

    if (m.t === "chat") {
      const text = typeof m.text === "string" ? m.text.replace(/[\u0000-\u001f\u007f]/g, " ").trim().slice(0, 300) : "";
      if (!text) return;
      const agora = Date.now();
      const atual = ws.deserializeAttachment() || {};
      const rl = (atual.rl || []).filter(t => agora - t < 5000); // anti-spam: 5 mensagens a cada 5 s
      if (rl.length >= 5) return;
      rl.push(agora);
      anotar(ws, { rl });
      const msg = { peer: atual.peer, name: (atual.presence && atual.presence.name) || "Alguém", text, ts: agora };
      const hist = (await this.ctx.storage.get("chat")) || [];
      hist.push(msg);
      while (hist.length > 50) hist.shift();
      await this.ctx.storage.put("chat", hist);
      await this.renovar();
      this.enviarTodos({ t: "chat", msg });
    }
  }

  async webSocketClose(ws, code) {
    try { ws.close(code === 1005 ? 1000 : code, "saiu"); } catch (e) {}
    if ((ws.deserializeAttachment() || {}).online) { this.avisarAdmins(ws); return; }
    this.avisarTodos(ws);
  }

  async webSocketError(ws) {
    if ((ws.deserializeAttachment() || {}).online) { this.avisarAdmins(ws); return; }
    this.avisarTodos(ws);
  }

  /* 24 horas sem nenhum uso: apaga a sala esquecida. */
  async alarm() {
    this.enviarTodos({ t: "state", state: null });
    await this.ctx.storage.deleteAll();
  }
}

/* ===== O SITE (index.html inteiro, guardado como texto) ===== */
const SITE = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Patologia Geral N1: banco de questões</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Literata:opsz,wght@7..72,400;7..72,600;7..72,700&family=Figtree:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F3F1F8; --card:#FFFFFF; --ink:#221C33; --muted:#655E7A; --line:#DCD6E8;\n  --hema:#3D2C74; --hema-soft:#E6E1F3; --eosin:#C93C74; --eosin-soft:#F8DDE8;\n  --frost:#ECE8F4; --frost2:#E2DCEE;\n  --ok:#1C7E60; --ok-soft:#DCF0E8; --bad:#B8373A; --bad-soft:#F7E0E0;\n  --serif:\"Literata\", Georgia, \"Times New Roman\", serif;\n  --sans:\"Figtree\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#16121F; --card:#211B2E; --ink:#EDE8F7; --muted:#A79FBD; --line:#3A3250;\n    --hema:#B6A6F0; --hema-soft:#2E2647; --eosin:#F07AA8; --eosin-soft:#43243A;\n    --frost:#2A2339; --frost2:#241E33;\n    --ok:#5FD1A8; --ok-soft:#173A30; --bad:#F28B8B; --bad-soft:#44222A;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#16121F; --card:#211B2E; --ink:#EDE8F7; --muted:#A79FBD; --line:#3A3250;\n  --hema:#B6A6F0; --hema-soft:#2E2647; --eosin:#F07AA8; --eosin-soft:#43243A;\n  --frost:#2A2339; --frost2:#241E33;\n  --ok:#5FD1A8; --ok-soft:#173A30; --bad:#F28B8B; --bad-soft:#44222A;\n}\n:root{box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px);}\n*,*::before,*::after{box-sizing:inherit;}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.5;-webkit-font-smoothing:antialiased;}\nbutton{font:inherit;color:inherit;}\n:focus-visible{outline:3px solid var(--eosin);outline-offset:2px;}\n.wrap{max-width:760px;margin:0 auto;padding:28px 18px 60px;}\nh1,h2,h3{font-family:var(--serif);font-weight:700;line-height:1.2;margin:0;}\n\n/* ---------- Home ---------- */\n.intro h1{font-size:clamp(1.9rem,5vw,2.6rem);letter-spacing:-0.01em;color:var(--hema);}\n.intro p{color:var(--muted);margin:10px 0 0;max-width:60ch;}\n.how{margin:22px 0 30px;padding:14px 16px;border-left:3px solid var(--eosin);background:var(--card);border-radius:0 8px 8px 0;font-size:.95rem;color:var(--muted);}\n.how strong{color:var(--ink);font-weight:600;}\n\n.slides{display:flex;flex-direction:column;gap:18px;}\n.slide{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);width:100%;min-height:168px;padding:0;border:1px solid var(--line);border-radius:6px;background:var(--card);cursor:pointer;text-align:left;overflow:hidden;box-shadow:0 1px 0 var(--line), 0 10px 24px -18px rgba(61,44,116,.45);transition:transform .15s ease, box-shadow .15s ease;}\n.slide:hover{transform:translateY(-2px);box-shadow:0 1px 0 var(--line), 0 16px 30px -18px rgba(61,44,116,.55);}\n.slide .label{padding:16px 16px 14px;background:repeating-linear-gradient(135deg,var(--frost) 0 3px,var(--frost2) 3px 6px);border-right:1px solid var(--line);display:flex;flex-direction:column;justify-content:space-between;gap:14px;}\n.slide .label h2{font-size:1.2rem;color:var(--ink);}\n.slide .label .total{font-size:.85rem;color:var(--muted);margin-top:4px;}\n.stats{display:flex;gap:14px;flex-wrap:wrap;}\n.stat{display:flex;flex-direction:column;line-height:1.15;}\n.stat b{font-size:1.25rem;font-family:var(--serif);}\n.stat span{font-size:.78rem;color:var(--muted);}\n.stat.due b{color:var(--eosin);}\n.stat.new b{color:var(--hema);}\n.stat.ok b{color:var(--ok);}\n.slide .glass{position:relative;display:flex;align-items:center;justify-content:center;padding:14px;}\n.tissue{width:min(150px,80%);aspect-ratio:1.35;opacity:.95;}\n.slide .go{position:absolute;right:12px;bottom:10px;font-size:.85rem;font-weight:600;color:var(--hema);}\n.slide.all{min-height:0;grid-template-columns:1fr;}\n.slide.all .label{border-right:0;flex-direction:row;align-items:center;justify-content:space-between;flex-wrap:wrap;}\n.footer{margin-top:36px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;font-size:.85rem;color:var(--muted);}\n.linkbtn{background:none;border:0;padding:6px 0;color:var(--muted);text-decoration:underline;cursor:pointer;}\n.linkbtn:hover{color:var(--bad);}\n\n/* ---------- Study ---------- */\n.topbar{display:flex;align-items:center;gap:12px;margin-bottom:10px;}\n.back{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:6px 12px;cursor:pointer;font-weight:500;}\n.topbar .t{flex:1;min-width:0;}\n.topbar .t h3{font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.topbar .t div{font-size:.82rem;color:var(--muted);}\n.bar{height:6px;background:var(--line);border-radius:6px;overflow:hidden;margin-bottom:22px;}\n.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--hema),var(--eosin));width:0;transition:width .3s ease;}\n.qcard{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:22px 20px;}\n.src{font-size:.8rem;color:var(--muted);margin-bottom:10px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;}\n.src .tag{color:var(--eosin);font-weight:600;}\n.qtext{font-family:var(--serif);font-size:1.18rem;line-height:1.55;margin:0 0 18px;}\n.opts{display:flex;flex-direction:column;gap:10px;}\n.opt{display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:start;width:100%;text-align:left;padding:12px 14px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);cursor:pointer;line-height:1.45;transition:border-color .12s ease, background .12s ease;}\n.opt:hover:not(:disabled){border-color:var(--hema);}\n.opt .l{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:.9rem;background:var(--hema-soft);color:var(--hema);}\n.opt:disabled{cursor:default;}\n.opt.right{border-color:var(--ok);background:var(--ok-soft);}\n.opt.right .l{background:var(--ok);color:#fff;}\n.opt.wrong{border-color:var(--bad);background:var(--bad-soft);}\n.opt.wrong .l{background:var(--bad);color:#fff;}\n.opt.dim{color:var(--muted);}\n.why{display:block;margin-top:6px;font-size:.86rem;line-height:1.45;color:var(--muted);}\n.opt.wrong .why{color:var(--bad);}\n.why b{font-weight:700;}\n.eh,.th{font-size:.76rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;margin-bottom:4px;}\n.eh{color:var(--hema);}\n.tip{margin-top:10px;padding:12px 14px;border-radius:8px;background:var(--eosin-soft);border-left:3px solid var(--eosin);font-size:.96rem;}\n.tip .th{color:var(--eosin);}\n.fb{margin-top:18px;}\n.verdict{font-family:var(--serif);font-size:1.25rem;font-weight:700;margin-bottom:6px;}\n.verdict.ok{color:var(--ok);}\n.verdict.no{color:var(--bad);}\n.expl{background:var(--bg);border-radius:8px;padding:12px 14px;font-size:.97rem;}\n.rate{margin-top:16px;}\n.rate p{margin:0 0 8px;font-size:.9rem;color:var(--muted);}\n.rbtns{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}\n.rbtn{border:1.5px solid var(--line);background:var(--card);border-radius:8px;padding:10px 6px;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:2px;font-weight:600;}\n.rbtn small{font-weight:400;color:var(--muted);font-size:.8rem;}\n.rbtn.hard:hover{border-color:var(--bad);}\n.rbtn.good:hover{border-color:var(--hema);}\n.rbtn.easy:hover{border-color:var(--ok);}\n.primary{display:block;width:100%;margin-top:16px;padding:12px;border:0;border-radius:8px;background:var(--hema);color:var(--card);font-weight:600;cursor:pointer;}\n.keys{margin-top:14px;font-size:.78rem;color:var(--muted);text-align:center;}\n.keys kbd{font-family:var(--sans);border:1px solid var(--line);border-bottom-width:2px;border-radius:4px;padding:0 5px;background:var(--card);}\n\n/* ---------- End / empty ---------- */\n.done{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:28px 22px;text-align:center;}\n.done h2{font-size:1.6rem;color:var(--hema);margin-bottom:8px;}\n.done p{color:var(--muted);margin:6px 0;}\n.score{display:flex;justify-content:center;gap:28px;margin:18px 0 6px;}\n.score div{display:flex;flex-direction:column;}\n.score b{font-family:var(--serif);font-size:2rem;}\n.score .a b{color:var(--ok);} .score .e b{color:var(--bad);}\n.score span{font-size:.82rem;color:var(--muted);}\n.row{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:18px;}\n.ghost{padding:11px 18px;border:1.5px solid var(--line);border-radius:8px;background:var(--card);cursor:pointer;font-weight:600;}\n.row .primary{width:auto;margin:0;padding:11px 18px;}\n\n.acct{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:18px 0 14px;padding:12px 14px;border-radius:10px;background:var(--hema-soft);font-size:.9rem;}\n.acct.in{background:var(--ok-soft);}\n.acct .primary,.acct .ghost{width:auto;margin:0;padding:9px 14px;}\n.tabs{display:flex;gap:6px;margin-bottom:14px;background:var(--bg);padding:4px;border-radius:10px;}\n.tabs button{flex:1;padding:9px;border:0;border-radius:7px;background:none;cursor:pointer;font-weight:600;color:var(--muted);}\n.tabs button.on{background:var(--card);color:var(--hema);box-shadow:0 1px 3px rgba(0,0,0,.08);}\n.panel .warn{margin-top:4px;}\n.primary:disabled{opacity:.6;cursor:default;}\n\n/* ---------- Acerto ao vivo e evolução ---------- */\n.acc{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:-10px 0 14px;}\n.accbox{display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;padding:8px 10px;border-radius:8px;background:var(--card);border:1px solid var(--line);}\n.accbox b{font-family:var(--serif);font-size:1.15rem;color:var(--muted);font-variant-numeric:tabular-nums;}\n.accbox span{font-size:.76rem;color:var(--muted);line-height:1.25;}\n.accbox.good b{color:var(--ok);} .accbox.mid b{color:var(--hema);} .accbox.low b{color:var(--eosin);}\n.stat.acc b{color:var(--ink);}\n.evo-entry{display:flex;align-items:center;gap:14px;width:100%;margin:0 0 18px;padding:14px 16px;border:1px solid var(--line);border-radius:10px;background:var(--card);cursor:pointer;text-align:left;}\n.evo-entry:hover{border-color:var(--hema);}\n.evo-entry h2{font-size:1.05rem;color:var(--hema);}\n.evo-entry p{margin:2px 0 0;font-size:.86rem;color:var(--muted);}\n.evo-ic{display:flex;align-items:flex-end;gap:3px;height:26px;flex-shrink:0;}\n.evo-ic i{width:6px;border-radius:2px;background:var(--hema);}\n.evo-ic i:nth-child(1){height:9px;opacity:.5}.evo-ic i:nth-child(2){height:15px;opacity:.7}.evo-ic i:nth-child(3){height:12px;opacity:.8}.evo-ic i:nth-child(4){height:24px;background:var(--ok)}\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px;}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 10px;display:flex;flex-direction:column;}\n.kpi b{font-family:var(--serif);font-size:1.5rem;color:var(--hema);}\n.kpi span{font-size:.78rem;color:var(--muted);line-height:1.25;}\n.evo-sec{margin-bottom:14px;}\n.evo-sub{font-size:.84rem !important;margin:4px 0 8px !important;}\n.chart{width:100%;height:auto;display:block;}\n.chart .cv{font-size:9px;fill:var(--muted);font-family:var(--sans);font-weight:600;}\n.chart .cd{font-size:9px;fill:var(--muted);font-family:var(--sans);}\n.evo-topic{margin-top:12px;}\n.evo-th{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:.92rem;margin-bottom:6px;}\n.evo-th span{color:var(--muted);font-size:.84rem;}\n.evo-topic .prog{border:1px solid var(--line);border-radius:8px;}\n.worst{list-style:none;margin:0 0 12px;padding:0;}\n.worst li{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--line);font-size:.9rem;}\n.worst .wn{flex-shrink:0;color:var(--eosin);font-weight:600;font-size:.82rem;}\n@media (max-width:520px){.kpis{grid-template-columns:1fr 1fr;}}\n\n/* ---------- Aviso de versão nova ---------- */\n.updbar{position:fixed;left:50%;transform:translateX(-50%);top:calc(env(safe-area-inset-top,0px) + 10px);z-index:80;display:flex;align-items:center;gap:12px;padding:10px 12px 10px 16px;border-radius:999px;background:var(--hema);color:var(--card);font-weight:600;font-size:.9rem;box-shadow:0 8px 24px -10px rgba(0,0,0,.5);max-width:calc(100vw - 20px);}\n.updbar button{border:0;border-radius:999px;padding:7px 14px;background:var(--card);color:var(--hema);font-weight:700;cursor:pointer;white-space:nowrap;}\n\n/* ---------- Painel do dono: quem está online ---------- */\n.fbtns{display:flex;gap:16px;flex-wrap:wrap;}\n.admin{position:fixed;left:0;top:0;bottom:0;z-index:70;pointer-events:none;}\n.admin-body{pointer-events:auto;position:absolute;left:0;top:0;bottom:0;width:272px;max-width:82vw;background:var(--card);border-right:1px solid var(--line);box-shadow:8px 0 26px -16px rgba(0,0,0,.45);padding:calc(env(safe-area-inset-top,0px) + 16px) 14px calc(env(safe-area-inset-bottom,0px) + 16px);overflow-y:auto;transform:translateX(-102%);transition:transform .22s ease;}\n.admin.open .admin-body{transform:none;}\n.admin-h{display:flex;flex-direction:column;gap:3px;margin-bottom:12px;}\n.admin-h b{font-family:var(--serif);font-size:1.05rem;color:var(--hema);}\n.admin-h small{font-size:.76rem;color:var(--muted);}\n.admin-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px;}\n.admin-list li{padding:9px 10px;border:1px solid var(--line);border-radius:9px;background:var(--bg);}\n.admin-list .an{display:flex;align-items:center;gap:7px;font-size:.92rem;}\n.admin-list .an em{font-style:normal;color:var(--muted);font-size:.8rem;}\n.admin-list .aw{margin-top:3px;font-size:.84rem;color:var(--ink);}\n.admin-list .am{margin-top:2px;font-size:.74rem;color:var(--muted);}\n.admin-list .aempty{color:var(--muted);font-size:.88rem;text-align:center;}\n.adot{width:8px;height:8px;border-radius:50%;background:var(--ok);flex-shrink:0;box-shadow:0 0 0 3px var(--ok-soft);}\n.admin-tab{pointer-events:auto;position:absolute;top:50%;left:0;transform:translateY(-50%);display:flex;align-items:center;gap:6px;padding:9px 12px 9px 10px;border:1px solid var(--line);border-left:0;border-radius:0 12px 12px 0;background:var(--card);box-shadow:4px 0 16px -10px rgba(0,0,0,.4);cursor:pointer;font-weight:700;font-size:.85rem;color:var(--hema);transition:left .22s ease;}\n.admin.open .admin-tab{display:none;}\n.admin-top{display:flex;align-items:center;justify-content:space-between;gap:8px;}\n@media (min-width:1100px){ body.admin-open{padding-left:272px;} }\n@media (max-width:520px){ .admin-tab .atxt{display:none;} }\n\n/* ---------- Quem pode revelar ---------- */\n.tbtns{display:flex;gap:6px;flex-wrap:wrap;}\n.permall{display:flex;gap:8px;align-items:center;padding:8px 10px;margin-bottom:8px;border-radius:8px;background:var(--card);cursor:pointer;font-weight:600;}\n.permall input{width:18px;height:18px;accent-color:var(--hema);}\n.tchecks label.dim{opacity:.55;}\n.person.helper{border-color:var(--hema);color:var(--hema);}\n\n/* ---------- Assunto da sala ---------- */\n.topicbar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:-4px 0 12px;padding:8px 12px;border-radius:10px;background:var(--card);border:1px solid var(--line);font-size:.9rem;}\n.topicbar b{color:var(--hema);}\n.topicpanel{margin:-6px 0 14px;padding:14px;border-radius:10px;background:var(--hema-soft);font-size:.9rem;}\n.topicpanel p{margin:0 0 8px;color:var(--muted);}\n.tchecks{display:grid;grid-template-columns:1fr 1fr;gap:6px;}\n.tchecks label{display:flex;gap:8px;align-items:center;padding:8px 10px;border-radius:8px;background:var(--card);cursor:pointer;}\n.tchecks input{width:18px;height:18px;accent-color:var(--hema);}\n@media (max-width:520px){.tchecks{grid-template-columns:1fr;}}\n\n/* ---------- Discursivas ---------- */\n.qcard.disc .qtext p{margin:0 0 10px;}\n.ctx{display:block;font-size:.85rem;color:var(--muted);font-style:italic;font-family:var(--sans);}\n.disc-l{display:block;font-size:.88rem;font-weight:600;margin:6px 0 6px;}\n#discTxt{display:block;width:100%;min-height:170px;padding:12px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;font-size:.96rem;line-height:1.5;resize:vertical;}\n#discTxt:focus{border-color:var(--hema);outline:none;}\n.qcard.disc .expl p{margin:0 0 8px;}\n.warnbox{background:var(--bad-soft);border-left-color:var(--bad);}\n.warnbox .th{color:var(--bad);}\n.checkl{margin-top:10px;padding:12px 14px;border:1px solid var(--line);border-radius:8px;}\n.checkl label{display:flex;gap:10px;align-items:flex-start;padding:6px 0;font-size:.93rem;cursor:pointer;border-bottom:1px dashed var(--line);}\n.checkl label:last-of-type{border-bottom:0;}\n.checkl input{width:18px;height:18px;margin-top:2px;accent-color:var(--ok);flex-shrink:0;}\n.ckscore{margin-top:8px;font-size:.9rem;color:var(--muted);}\n.rbtn.sug{border-color:var(--hema);box-shadow:0 0 0 3px var(--hema-soft);}\n\n/* ---------- Ritmo, cronômetro e revisão da sala ---------- */\n.ritmo{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 14px;font-size:.88rem;font-weight:600;color:var(--muted);}\n.seg{display:flex;gap:4px;background:var(--card);border:1px solid var(--line);padding:4px;border-radius:10px;flex:1;min-width:260px;}\n.seg button{flex:1;display:flex;flex-direction:column;align-items:center;padding:7px 8px;border:0;border-radius:7px;background:none;cursor:pointer;font-weight:600;color:var(--muted);font-size:.88rem;}\n.seg button small{font-weight:400;font-size:.72rem;}\n.seg button.on{background:var(--hema);color:var(--card);}\n.timer{display:inline-flex;align-items:center;gap:6px;margin-left:auto;padding:5px 11px;border-radius:999px;background:var(--hema-soft);color:var(--hema);font-weight:700;font-variant-numeric:tabular-nums;font-size:.95rem;flex-shrink:0;}\n.timer::before{content:\"\";width:9px;height:9px;border-radius:50%;background:var(--eosin);animation:blink 1s steps(2) infinite;}\n.timer.stopped{background:var(--ok-soft);color:var(--ok);}\n.timer.stopped::before{background:var(--ok);animation:none;}\n@keyframes blink{50%{opacity:.25}}\n.gbar .timer{margin-left:auto;}\n.bigclock{font-family:var(--serif);font-size:3rem;font-weight:700;color:var(--hema);font-variant-numeric:tabular-nums;margin:6px 0 10px;}\n.score .t b{color:var(--hema);}\n.qinfo{display:flex;flex-wrap:wrap;gap:6px 14px;margin:-4px 0 12px;font-size:.82rem;color:var(--muted);}\n.qinfo b{color:var(--ink);}\n.rbtns.four{grid-template-columns:repeat(4,1fr);}\n.rbtn.again:hover{border-color:var(--bad);}\n.g-rate{margin-top:14px;}\n@media (max-width:520px){.rbtns.four{grid-template-columns:repeat(2,1fr);}}\n@media (prefers-reduced-motion:reduce){.timer::before{animation:none;}}\n\n/* ---------- Chat e voz da sala ---------- */\n.side{background:var(--card);border:1px solid var(--line);border-radius:12px;display:flex;flex-direction:column;overflow:hidden;}\n.chat-h{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 8px 6px 12px;border-bottom:1px solid var(--line);}\n.chat-toggle{display:flex;align-items:center;gap:8px;min-width:0;flex:1;background:none;border:0;padding:4px 0;cursor:pointer;text-align:left;font-family:var(--serif);font-weight:700;color:var(--hema);font-size:1rem;}\n.chat-toggle .prev{font-family:var(--sans);font-weight:400;font-size:.8rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;}\n.badge{background:var(--eosin);color:#fff;border-radius:999px;font-size:.72rem;font-family:var(--sans);padding:1px 7px;}\n.voice-ctl{display:flex;gap:6px;flex-shrink:0;}\n.vbtn{border:1.5px solid var(--line);background:var(--card);border-radius:999px;padding:6px 11px;font-size:.8rem;font-weight:600;cursor:pointer;white-space:nowrap;}\n.vbtn.join{border-color:var(--ok);color:var(--ok);}\n.vbtn.mute.on{background:var(--bad-soft);border-color:var(--bad);color:var(--bad);}\n.vbtn.leave{color:var(--bad);}\n.voice-list{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:7px 10px;border-bottom:1px solid var(--line);font-size:.8rem;color:var(--muted);}\n.voice-list:empty{display:none;}\n.vchip{display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:999px;background:var(--bg);border:1.5px solid var(--line);color:var(--ink);transition:border-color .1s, box-shadow .1s;}\n.vchip .mic{width:8px;height:8px;border-radius:50%;background:var(--ok);}\n.vchip.muted .mic{background:var(--bad);}\n.vchip.wait{opacity:.6;}\n.talking{border-color:var(--ok) !important;box-shadow:0 0 0 3px var(--ok-soft);}\n.verr{width:100%;color:var(--bad);}\n.chat-log{flex:1;min-height:0;overflow-y:auto;padding:10px 12px;display:flex;flex-direction:column;gap:6px;background:var(--bg);}\n.chat-empty{margin:auto;color:var(--muted);font-size:.9rem;text-align:center;}\n.msg-row{display:flex;}\n.msg-row.mine{justify-content:flex-end;}\n.bubble{max-width:85%;padding:6px 10px 4px;border-radius:12px 12px 12px 4px;background:var(--card);border:1px solid var(--line);font-size:.92rem;line-height:1.35;overflow-wrap:anywhere;}\n.msg-row.mine .bubble{border-radius:12px 12px 4px 12px;background:var(--hema-soft);border-color:transparent;}\n.bubble b{display:block;font-size:.76rem;margin-bottom:1px;}\n.bubble time{display:block;text-align:right;font-size:.66rem;color:var(--muted);margin-top:1px;}\n.chat-in{display:flex;gap:8px;padding:8px;border-top:1px solid var(--line);}\n.chat-in input{flex:1;min-width:0;padding:9px 12px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;}\n.chat-in .primary{width:auto;margin:0;padding:9px 14px;}\n.rtc-audio{display:none;}\n/* tela larga (tablet, computador): conversa ao lado da questão */\n@media (min-width:760px){\n  #app.in-room{max-width:1180px;}\n  .room-grid{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:18px;align-items:start;}\n  .side{position:sticky;top:calc(env(safe-area-inset-top,0px) + 12px);height:calc(100vh - 32px);height:calc(100dvh - 32px - env(safe-area-inset-top,0px) - env(safe-area-inset-bottom,0px));}\n  .chat-toggle{cursor:default;}\n  .chat-toggle .prev,.badge{display:none !important;}\n}\n/* celular: conversa fixa embaixo; o campo de digitar fica sempre à mão */\n@media (max-width:759px){\n  .side{position:fixed;left:0;right:0;bottom:0;z-index:40;border-radius:14px 14px 0 0;border-bottom:0;border-left:0;border-right:0;box-shadow:0 -6px 24px -10px rgba(0,0,0,.35);padding-bottom:env(safe-area-inset-bottom,0px);}\n  .side .chat-log{display:none;height:38vh;flex:none;}\n  .side.open .chat-log{display:flex;}\n  #app.in-room #gmain{padding-bottom:160px;}\n  #app.in-room.chat-open #gmain{padding-bottom:calc(38vh + 180px);}\n}\n\n/* ---------- Modo em grupo ---------- */\n.group-entry{display:flex;align-items:center;gap:14px;width:100%;margin:0 0 18px;padding:16px;border:1.5px solid var(--hema);border-radius:10px;background:linear-gradient(100deg,var(--hema-soft),var(--card));cursor:pointer;text-align:left;}\n.group-entry:disabled{cursor:default;border-color:var(--line);opacity:.8;}\n.group-entry .gi{flex-shrink:0;display:flex;}\n.group-entry .gi i{width:22px;height:22px;border-radius:50%;border:2px solid var(--card);background:var(--eosin);margin-left:-7px;}\n.group-entry .gi i:first-child{margin-left:0;background:var(--hema);}\n.group-entry .gi i:last-child{background:var(--ok);}\n.group-entry h2{font-size:1.1rem;color:var(--hema);}\n.group-entry p{margin:2px 0 0;font-size:.86rem;color:var(--muted);}\n.field{display:flex;flex-direction:column;gap:6px;margin:14px 0;}\n.field label{font-size:.88rem;font-weight:600;}\n.field input{padding:10px 12px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;}\n.field input.code{text-transform:uppercase;letter-spacing:.3em;font-weight:700;font-size:1.2rem;max-width:180px;}\n.topic-pick{display:grid;grid-template-columns:1fr 1fr;gap:8px;}\n.topic-pick button{padding:10px;border:1.5px solid var(--line);border-radius:8px;background:var(--card);cursor:pointer;font-weight:500;text-align:left;font-size:.92rem;}\n.topic-pick button:hover{border-color:var(--hema);}\n.rooms{margin-top:10px;display:flex;flex-direction:column;gap:8px;}\n.roomrow{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:var(--bg);font-size:.9rem;}\n.roomrow b{letter-spacing:.15em;color:var(--hema);}\n.sep{height:1px;background:var(--line);margin:18px 0;}\n.gbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px;}\n.gcode{font-weight:700;letter-spacing:.2em;color:var(--hema);background:var(--hema-soft);padding:4px 10px;border-radius:6px;}\n.people{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px;}\n.person{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:var(--card);border:1px solid var(--line);font-size:.82rem;}\n.person.done{border-color:var(--ok);color:var(--ok);}\n.person .dot{width:7px;height:7px;border-radius:50%;background:var(--line);}\n.person.done .dot{background:var(--ok);}\n.person.lead{font-weight:700;}\n.opt.picked{border-color:var(--hema);background:var(--hema-soft);}\n.opt.picked .l{background:var(--hema);color:var(--card);}\n.chose{display:block;margin-top:6px;font-size:.8rem;font-weight:600;color:var(--hema);}\n.gstatus{margin-top:14px;font-size:.92rem;color:var(--muted);text-align:center;}\n.hostbar{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px;}\n.hostbar .primary{flex:1;margin:0;}\n.hostbar .ghost{flex-shrink:0;}\n.hostbar .ghost:disabled{opacity:.45;cursor:default;}\n.owner-tag{font-size:.78rem;font-weight:700;color:var(--ok);background:var(--ok-soft);padding:3px 9px;border-radius:999px;}\n.warn{padding:12px 14px;border-radius:8px;background:var(--eosin-soft);font-size:.92rem;}\n\n/* ---------- Robbins ---------- */\n.ref{display:flex;gap:10px;align-items:flex-start;margin-top:10px;padding:10px 12px;border-radius:8px;border:1px solid var(--line);font-size:.88rem;color:var(--muted);}\n.ref b{color:var(--hema);font-weight:600;}\n.book{position:relative;flex-shrink:0;width:15px;height:19px;margin-top:2px;border:2px solid var(--hema);border-radius:2px 4px 4px 2px;}\n.book::before{content:\"\";position:absolute;left:2px;top:-2px;bottom:-2px;width:2px;background:var(--hema);}\n.rmap{margin:0 0 26px;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 16px;}\n.rmap summary{cursor:pointer;font-weight:600;color:var(--hema);}\n.rmap h3{font-size:.98rem;margin:16px 0 6px;color:var(--ink);}\n.rmap ul{list-style:none;margin:0;padding:0;}\n.rmap li{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--line);font-size:.92rem;}\n.rmap li b{font-weight:600;color:var(--eosin);white-space:nowrap;font-size:.85rem;}\n.rmap li em{font-style:normal;color:var(--muted);font-size:.8rem;margin-left:4px;white-space:nowrap;}\n.refnote{margin-top:6px;font-size:.84rem;color:var(--bad);}\n.rmap .note{margin:12px 0 2px;font-size:.8rem;color:var(--muted);}\n\n/* ---------- Barra de progresso ---------- */\n.prog{grid-column:1/-1;padding:12px 16px 14px;border-top:1px solid var(--line);background:var(--card);}\n.prog-head{display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;margin-bottom:7px;}\n.prog-head b{font-family:var(--serif);font-size:1.3rem;color:var(--hema);font-variant-numeric:tabular-nums;}\n.prog-head .lbl{font-size:.88rem;font-weight:600;color:var(--ink);}\n.prog-head .det{margin-left:auto;font-size:.8rem;color:var(--muted);}\n.track{position:relative;height:12px;border-radius:12px;background:var(--frost2);overflow:hidden;}\n.track::after{content:\"\";position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,transparent calc(25% - 1px),var(--card) calc(25% - 1px) 25%,transparent 25% calc(50% - 1px),var(--card) calc(50% - 1px) 50%,transparent 50% calc(75% - 1px),var(--card) calc(75% - 1px) 75%,transparent 75%);opacity:.75;}\n.fill{display:block;height:100%;width:0;border-radius:12px;background:linear-gradient(90deg,var(--hema),var(--eosin));transition:width 1.1s cubic-bezier(.2,.8,.2,1);}\n.prog.full .fill{background:linear-gradient(90deg,var(--ok),var(--hema),var(--eosin));box-shadow:0 0 12px var(--eosin);}\n.prog.full .prog-head b{color:var(--ok);}\n.done .prog{border:1px solid var(--line);border-radius:10px;margin:18px 0 4px;text-align:left;}\n.gain{font-size:.85rem;font-weight:600;color:var(--ok);}\n@media (prefers-reduced-motion:reduce){.fill{transition:none}}\n\n/* ---------- Comemoração ---------- */\n.cheer{display:flex;align-items:center;gap:12px;margin:0 0 12px;padding:12px 14px;border-radius:10px;background:linear-gradient(100deg,var(--eosin-soft),var(--hema-soft));animation:pop .5s cubic-bezier(.2,1.5,.4,1) both;}\n.cheer .big{font-family:var(--serif);font-size:1.15rem;font-weight:700;color:var(--hema);line-height:1.25;}\n.cheer .sub{font-size:.88rem;color:var(--muted);}\n.cheer .dots{display:flex;gap:4px;flex-shrink:0;}\n.cheer .dots i{width:11px;height:11px;border-radius:50%;background:var(--eosin);box-shadow:inset -2px -2px 0 rgba(0,0,0,.12);animation:pop .4s cubic-bezier(.2,1.6,.4,1) both;}\n.cheer.lvl3{box-shadow:0 0 0 2px var(--eosin) inset;}\n.cheer.lvl4 .big{font-size:1.3rem;}\n@keyframes pop{0%{transform:scale(.6);opacity:0}100%{transform:scale(1);opacity:1}}\n.burst{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:50;}\n.bit{position:absolute;left:var(--x);top:var(--y);width:var(--s);height:var(--s);margin:calc(var(--s) / -2) 0 0 calc(var(--s) / -2);border-radius:50%;background:var(--c);animation:fly var(--t) cubic-bezier(.15,.7,.3,1) forwards;}\n.bit.cell::after{content:\"\";position:absolute;inset:32%;border-radius:50%;background:var(--hema);opacity:.9;}\n@keyframes fly{\n  0%{transform:translate(0,0) scale(.2);opacity:1}\n  65%{opacity:1}\n  100%{transform:translate(var(--dx),var(--dy)) scale(1) rotate(var(--r));opacity:0}\n}\n@media (prefers-reduced-motion:reduce){.burst{display:none}.cheer,.cheer .dots i{animation:none}}\n\n/* ---------- Escolher quando volta ---------- */\n.custom{margin-top:14px;border:1.5px dashed var(--line);border-radius:8px;padding:10px 12px;}\n.custom summary{cursor:pointer;font-weight:600;color:var(--hema);font-size:.93rem;}\n.custom[open] summary{margin-bottom:10px;}\n.chips{display:flex;flex-wrap:wrap;gap:8px;}\n.chip{border:1.5px solid var(--line);background:var(--card);border-radius:999px;padding:7px 13px;cursor:pointer;font-size:.9rem;font-weight:500;}\n.chip:hover{border-color:var(--hema);}\n.own{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:10px;font-size:.9rem;color:var(--muted);}\n.own input{width:80px;padding:7px 10px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;}\n.own .err{color:var(--bad);width:100%;}\n\n/* ---------- Backup ---------- */\n.backup-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px;}\n.backup-row .ghost{flex:1;min-width:180px;}\n.panel{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:22px 20px;}\n.panel h2{font-size:1.4rem;color:var(--hema);margin-bottom:8px;}\n.panel p{color:var(--muted);margin:6px 0 14px;}\n.panel textarea{display:block;width:100%;min-height:130px;font-family:ui-monospace,\"SF Mono\",Menlo,Consolas,monospace;font-size:.78rem;line-height:1.4;padding:10px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);resize:vertical;word-break:break-all;}\n.panel .row{justify-content:flex-start;}\n.msg{margin-top:12px;padding:10px 12px;border-radius:8px;font-size:.93rem;}\n.msg.ok{background:var(--ok-soft);color:var(--ok);}\n.msg.bad{background:var(--bad-soft);color:var(--bad);}\n\n@media (max-width:520px){\n  .slide{grid-template-columns:1fr;}\n  .slide .label{border-right:0;border-bottom:1px solid var(--line);}\n  .slide .glass{min-height:110px;}\n  .tissue{width:120px;}\n  .qcard{padding:18px 14px;}\n  .qtext{font-size:1.08rem;}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;}}\n</style>\n</head>\n<body>\n<div class=\"wrap\" id=\"app\"></div>\n\n<script>\n/* =========================================================\n   BANCO DE QUESTÕES\n   [id, assunto, origem, enunciado, alternativas, índice correto, comentário]\n   ========================================================= */\nconst TOPICS = {\n  adapt:   { name: \"Adaptações e lesão celular\", tissue: 0 },\n  aguda:   { name: \"Inflamação aguda\", tissue: 1 },\n  cronica: { name: \"Inflamação crônica e granulomatosa\", tissue: 2 },\n  provas:  { name: \"Provas antigas\", tissue: 3, sub: \"provas dos professores + questões extras\" }\n};\n\nconst A = \"Revisão N1, questão \";\nconst B = \"Revisão N1 (parte 2), questão \";\nconst C = \"Lista de adaptação e inflamação, pergunta \";\nconst P = \"Prova de Patologia Geral, item \";\nconst X = \"Questão extra no estilo da prova\";\nconst F1 = \"Prova FIMCA 1, item \", M2 = \"Prova Metropolitana 2, item \", F3 = \"Prova FIMCA 3, item \", F4A = \"Prova FIMCA 4A, item \", F4B = \"Prova FIMCA 4B, item \";\nconst ASSERT = [\"A afirmativa 1 está correta e a 2 incorreta, e a 2 justifica a 1.\",\"As afirmativas 1 e 2 estão corretas, porém a 2 não justifica a 1.\",\"A afirmativa 1 está correta, a 2 está incorreta e a 2 não justifica a 1.\",\"A afirmativa 1 está incorreta, a 2 está correta e a 2 justifica a 1.\",\"As afirmativas 1 e 2 estão corretas, e a 2 justifica a 1.\"];\n\nconst QUESTIONS = [\n/* ---------- REVISÃO N1 (10 questões) ---------- */\n[\"a01\",\"adapt\",A+\"1\",\"Um homem de 65 anos com hipertensão arterial crônica apresenta aumento da massa muscular do ventrículo esquerdo. Qual processo adaptativo melhor descreve essa alteração?\",\n[\"Hiperplasia\",\"Hipertrofia\",\"Atrofia\",\"Metaplasia\"],1,\n\"Cardiomiócitos praticamente não se dividem. Diante da sobrecarga de pressão, cada célula sintetiza mais proteínas contráteis e aumenta de tamanho: hipertrofia. O órgão cresce porque as células cresceram, não porque aumentaram em número.\"],\n[\"a02\",\"adapt\",A+\"2\",\"A substituição do epitélio colunar ciliado do trato respiratório por epitélio escamoso estratificado em fumantes é um exemplo de:\",\n[\"Displasia\",\"Hiperplasia\",\"Atrofia\",\"Metaplasia\"],3,\n\"Metaplasia é a troca de um tipo celular adulto por outro tipo adulto, mais resistente à agressão (aqui, a fumaça). Displasia é outra coisa: desorganização com atipia celular, já no caminho para neoplasia.\"],\n[\"a03\",\"aguda\",A+\"3\",\"Qual é a sequência correta de eventos celulares na inflamação aguda?\",\n[\"Marginação, Rolamento, Adesão, Transmigração\",\"Quimiotaxia, Rolamento, Fagocitose, Adesão\",\"Vasodilatação, Estase, Edema, Apoptose\",\"Transmigração, Adesão, Rolamento, Marginação\"],0,\n\"Com a estase, os leucócitos vão para a periferia do vaso (marginação), rolam sobre o endotélio (selectinas), aderem firmemente (integrinas) e atravessam a parede (transmigração/diapedese, PECAM-1). A quimiotaxia acontece depois, já no tecido.\"],\n[\"a04\",\"aguda\",A+\"4\",\"Qual mediador químico é o principal responsável pela vasodilatação imediata e pelo aumento da permeabilidade vascular na inflamação aguda?\",\n[\"Interferon-gama\",\"Histamina\",\"Leucotrieno B4\",\"Fator de Necrose Tumoral (TNF)\"],1,\n\"A histamina já está pronta nos grânulos dos mastócitos e é liberada em segundos: dilata arteríolas e aumenta a permeabilidade das vênulas (fase imediata). TNF e IFN-γ são citocinas de ação mais tardia; o LTB4 é principalmente quimiotático para neutrófilos.\"],\n[\"a05\",\"cronica\",A+\"5\",\"A formação de granulomas, caracterizada por agregados de macrófagos epitelioides, é uma marca registrada de qual processo?\",\n[\"Adaptação Celular por Atrofia\",\"Inflamação Aguda Supurativa\",\"Inflamação Crônica\",\"Regeneração Tecidual\"],2,\n\"O granuloma é um padrão especial de inflamação crônica: agregados de macrófagos ativados (células epitelioides), muitas vezes com células gigantes e um halo de linfócitos.\"],\n[\"a06\",\"aguda\",A+\"6\",\"Durante a inflamação aguda, o aumento da permeabilidade vascular que permite a saída de fluido rico em proteínas e células para o interstício é chamado de:\",\n[\"Transudato\",\"Linfedema\",\"Edema hidrostático\",\"Exsudato\"],3,\n\"Exsudato: rico em proteínas e células, sai porque a permeabilidade vascular aumentou (é inflamatório). Transudato: pobre em proteínas, sai de vasos íntegros por aumento da pressão hidrostática ou queda da pressão oncótica.\"],\n[\"a07\",\"cronica\",A+\"7\",\"Qual citocina é considerada o “ativador mestre” dos macrófagos na inflamação crônica, sendo produzida principalmente por células T?\",\n[\"IL-4\",\"IL-8\",\"Interferon-gama (IFN-γ)\",\"IL-10\"],2,\n\"IFN-γ, produzido por linfócitos Th1 e células NK, é o grande ativador clássico (M1) dos macrófagos. IL-4 leva à ativação alternativa (M2), IL-10 é anti-inflamatória e IL-8 é quimiocina de neutrófilos.\"],\n[\"a08\",\"aguda\",A+\"8\",\"As selectinas são moléculas de adesão fundamentais para qual etapa do recrutamento leucocitário?\",\n[\"Adesão firme\",\"Rolamento\",\"Diapedese\",\"Fagocitose\"],1,\n\"Selectinas (E, P e L) fazem ligações de baixa afinidade que se formam e se desfazem o tempo todo, então o leucócito rola. A adesão firme é feita pelas integrinas ligando ICAM-1 e VCAM-1.\"],\n[\"a09\",\"adapt\",A+\"9\",\"Qual das seguintes alterações celulares é considerada uma resposta adaptativa à redução de nutrientes ou estimulação hormonal?\",\n[\"Metaplasia\",\"Hiperplasia\",\"Atrofia\",\"Necrose\"],2,\n\"Atrofia é a redução do tamanho celular por nutrição inadequada, menor aporte sanguíneo, desuso, perda de inervação ou perda de estímulo hormonal (ex.: endométrio após a menopausa). Atenção ao enunciado: o sentido é a perda da estimulação hormonal. Estimulação hormonal aumentada causaria hiperplasia.\"],\n[\"a10\",\"aguda\",A+\"10\",\"O sistema do complemento pode ser ativado por três vias. Qual componente é comum a todas as vias e leva à formação do complexo de ataque à membrana (MAC)?\",\n[\"Lectina de ligação à manose\",\"C1q\",\"C3\",\"Fator B\"],2,\n\"As vias clássica, alternativa e das lectinas convergem na clivagem de C3 pela C3 convertase. A partir daí: C3b, C5 convertase e C5b-9 (MAC). C1q é só da clássica, a lectina de ligação à manose só da via das lectinas e o fator B só da alternativa.\"],\n\n/* ---------- REVISÃO N1, PARTE 2 (50 questões) ---------- */\n[\"b01\",\"adapt\",B+\"1\",\"Qual mecanismo celular explica o aumento do útero durante a gravidez?\",\n[\"Apenas hipertrofia das fibras musculares.\",\"Apenas hiperplasia do endométrio.\",\"Combinação de hipertrofia e hiperplasia do miométrio.\",\"Metaplasia hormonal do colo uterino.\"],2,\n\"O estrogênio estimula as células musculares lisas do miométrio a aumentarem de tamanho (hipertrofia) e de número (hiperplasia). É o exemplo clássico das duas adaptações fisiológicas acontecendo juntas.\"],\n[\"b02\",\"adapt\",B+\"2\",\"A atrofia celular por desuso resulta principalmente de:\",\n[\"Aumento da síntese proteica.\",\"Redução da autofagia.\",\"Degradação de proteínas via ubiquitina-proteassoma.\",\"Substituição por tecido adiposo via metaplasia.\"],2,\n\"Na atrofia a célula sintetiza menos e degrada mais proteínas. A principal via de degradação é a ubiquitina-proteassoma: proteínas marcadas com ubiquitina são destruídas no proteassoma. A autofagia também aumenta, não diminui.\"],\n[\"b03\",\"adapt\",B+\"3\",\"Qual das seguintes opções descreve a patogênese da metaplasia?\",\n[\"Mudança no fenótipo de células já diferenciadas.\",\"Reprogramação de células-tronco teciduais.\",\"Divisão celular descontrolada.\",\"Morte celular programada seguida de regeneração.\"],1,\n\"A célula madura não se transforma em outra. O que acontece é a reprogramação das células-tronco/de reserva do tecido, que passam a se diferenciar em outra linhagem por influência de citocinas, fatores de crescimento e da matriz.\"],\n[\"b04\",\"adapt\",B+\"4\",\"A hiperplasia patológica é clinicamente importante porque:\",\n[\"Sempre evolui para necrose.\",\"Constitui um solo fértil para o surgimento de câncer.\",\"É um processo irreversível.\",\"Causa diminuição da função orgânica.\"],1,\n\"A hiperplasia patológica (ex.: endometrial por excesso de estrogênio) ainda é controlada e regride se o estímulo cessar. Mas as divisões celulares repetidas aumentam a chance de mutações, então ela é terreno para câncer (ex.: carcinoma de endométrio).\"],\n[\"b05\",\"adapt\",B+\"5\",\"Qual organela sofre aumento proeminente na hipertrofia dos hepatócitos induzida por barbitúricos?\",\n[\"Mitocôndria.\",\"Retículo endoplasmático rugoso.\",\"Retículo endoplasmático liso.\",\"Lisossomos.\"],2,\n\"Barbitúricos são metabolizados pelo sistema citocromo P-450, que fica no retículo endoplasmático liso. O hepatócito expande o REL para destoxificar mais, e isso explica a tolerância ao fármaco.\"],\n[\"b06\",\"adapt\",B+\"6\",\"A deficiência de Vitamina A pode induzir qual tipo de adaptação no epitélio respiratório?\",\n[\"Atrofia.\",\"Hiperplasia glandular.\",\"Metaplasia escamosa.\",\"Displasia grave.\"],2,\n\"O ácido retinoico (vitamina A) é necessário para manter a diferenciação normal do epitélio respiratório. Sem ele, o epitélio sofre metaplasia escamosa.\"],\n[\"b07\",\"adapt\",B+\"7\",\"O coração de um paciente com caquexia por câncer apresenta-se reduzido e com pigmentação acastanhada. O pigmento é:\",\n[\"Hemossiderina.\",\"Lipofuscina.\",\"Melanina.\",\"Bilirrubina.\"],1,\n\"Lipofuscina é o pigmento de “desgaste”: resíduo da peroxidação lipídica de membranas digeridas por autofagia. Castanho-amarelado e perinuclear, dá o aspecto de atrofia parda do coração em idosos e caquéticos.\"],\n[\"b08\",\"adapt\",B+\"8\",\"Qual o estímulo principal para a hiperplasia compensatória do fígado após hepatectomia parcial?\",\n[\"Hormônios esteroides.\",\"Citocinas e fatores de crescimento (HGF, IL-6).\",\"Isquemia relativa.\",\"Deposição de colágeno.\"],1,\n\"Os hepatócitos remanescentes saem de G0 e proliferam estimulados por fatores de crescimento (HGF, TGF-α) e citocinas (IL-6, TNF). É hiperplasia compensatória.\"],\n[\"b09\",\"adapt\",B+\"9\",\"Na adaptação celular, a autofagia é um processo de:\",\n[\"Ingestão de partículas externas.\",\"Digestão de componentes próprios da célula por lisossomos.\",\"Expulsão de organelas danificadas para o exsudato.\",\"Morte celular por inflamação.\"],1,\n\"Autofagia: a célula envolve seus próprios componentes em vacúolos autofágicos, que se fundem com lisossomos e são digeridos. Aumenta na atrofia e na privação de nutrientes. Ingerir partículas externas é fagocitose.\"],\n[\"b10\",\"adapt\",B+\"10\",\"A hipertrofia fisiológica do músculo esquelético de um atleta é estimulada principalmente via:\",\n[\"Via PI3K/AKT.\",\"Via G-proteína acoplada.\",\"Via da Caspase 3.\",\"Via do NF-kB.\"],0,\n\"Hipertrofia fisiológica (exercício, IGF-1) usa principalmente a via PI3K/AKT. A hipertrofia patológica (sobrecarga, angiotensina, endotelina) depende mais de receptores acoplados à proteína G. Caspase 3 é da apoptose.\"],\n[\"b11\",\"aguda\",B+\"11\",\"Qual evento vascular ocorre primeiro na inflamação aguda após uma lesão leve?\",\n[\"Vasoconstrição transitória das arteríolas.\",\"Vasodilatação capilar permanente.\",\"Aumento da pressão osmótica plasmática.\",\"Formação de trombos plaquetários.\"],0,\n\"Logo após a lesão há uma vasoconstrição arteriolar transitória, de segundos. Depois vem a vasodilatação, responsável por calor e rubor.\"],\n[\"b12\",\"aguda\",B+\"12\",\"O mecanismo mais comum de extravasamento vascular na inflamação aguda é:\",\n[\"Lesão endotelial direta.\",\"Contração das células endoteliais (fendas interendoteliais).\",\"Transcitose aumentada.\",\"Angiogênese de vasos imaturos.\"],1,\n\"O mecanismo mais comum é a contração das células endoteliais das vênulas pós-capilares, abrindo fendas entre elas. É induzido por histamina, bradicinina e leucotrienos, e é rápido e reversível (15 a 30 minutos).\"],\n[\"b13\",\"aguda\",B+\"13\",\"Qual molécula de adesão é expressa no endotélio após ativação por TNF e IL-1 para promover a adesão firme?\",\n[\"L-selectina.\",\"ICAM-1.\",\"Glicoproteína de Lewis X.\",\"PECAM-1.\"],1,\n\"TNF e IL-1 induzem no endotélio ICAM-1 e VCAM-1, que se ligam às integrinas dos leucócitos (LFA-1, VLA-4) e garantem a adesão firme. L-selectina e Lewis X participam do rolamento; PECAM-1, da transmigração.\"],\n[\"b14\",\"aguda\",B+\"14\",\"A quimiotaxia leucocitária é direcionada por:\",\n[\"Gradiente de concentração de substâncias químicas (ex: C5a, LTB4).\",\"Aumento da pressão hidrostática.\",\"Diminuição do pH local.\",\"Estase sanguínea.\"],0,\n\"Quimiotaxia é o movimento orientado por um gradiente químico. Os quimiotáticos podem ser exógenos (produtos bacterianos) ou endógenos (C5a, LTB4, IL-8 e outras quimiocinas).\"],\n[\"b15\",\"aguda\",B+\"15\",\"O “burst” oxidativo (explosão respiratória) nos neutrófilos produz:\",\n[\"Óxido nítrico apenas.\",\"Espécies reativas de oxigênio (ERO), como o ânion superóxido.\",\"Histamina estocada.\",\"Proteína C reativa.\"],1,\n\"A NADPH oxidase (oxidase do fagócito) reduz O₂ a ânion superóxido, que depois vira H₂O₂: são as ERO usadas para matar micróbios. A deficiência dessa enzima causa a doença granulomatosa crônica.\"],\n[\"b16\",\"aguda\",B+\"16\",\"Qual das seguintes é uma característica morfológica da inflamação serosa?\",\n[\"Presença de grande quantidade de neutrófilos e pus.\",\"Extravasamento de fluido pobre em proteínas (efusão).\",\"Formação de cicatriz fibrótica precoce.\",\"Presença de necrose caseosa.\"],1,\n\"Inflamação serosa é o extravasamento de líquido fino (efusão) em cavidades ou bolhas, como na bolha de queimadura ou no derrame pleural. O Robbins descreve o líquido como pobre em células; a alternativa fala em proteínas, mas é a única compatível.\"],\n[\"b17\",\"aguda\",B+\"17\",\"O sistema das cininas resulta na formação de bradicinina, que causa:\",\n[\"Vasoconstrição e hipertensão local.\",\"Dor e aumento da permeabilidade vascular.\",\"Inibição da quimiotaxia.\",\"Degradação do colágeno.\"],1,\n\"A bradicinina (fator XII, calicreína, cininogênio) aumenta a permeabilidade vascular, dilata vasos e causa dor. É inativada rapidamente pela cininase, que é a própria ECA.\"],\n[\"b18\",\"aguda\",B+\"18\",\"As NETs (Armadilhas Extracelulares de Neutrófilos) são compostas por:\",\n[\"Apenas citocinas inflamatórias.\",\"Rede de cromatina nuclear com proteínas granulares.\",\"Complexos antígeno-anticorpo.\",\"Membranas mitocondriais rompidas.\"],1,\n\"O neutrófilo libera sua cromatina em forma de rede, com histonas e proteínas antimicrobianas dos grânulos, que prendem e matam microrganismos. O neutrófilo morre no processo.\"],\n[\"b19\",\"aguda\",B+\"19\",\"Qual proteína plasmática da fase aguda é usada clinicamente como marcador de inflamação?\",\n[\"Albumina.\",\"Proteína C reativa (PCR).\",\"Hemoglobina.\",\"Troponina.\"],1,\n\"A PCR é produzida pelo fígado sob estímulo de IL-6 (e também IL-1 e TNF) e sobe muito na inflamação. A albumina faz o contrário: cai (proteína de fase aguda negativa).\"],\n[\"b20\",\"aguda\",B+\"20\",\"A resolução da inflamação aguda envolve a troca de metabólitos do ácido araquidônico de pró-inflamatórios para:\",\n[\"Leucotrienos.\",\"Tromboxanos.\",\"Lipoxinas.\",\"Prostaglandina E2.\"],2,\n\"Na resolução, a produção de mediadores lipídicos muda de prostaglandinas e leucotrienos (pró-inflamatórios) para lipoxinas (e resolvinas), que inibem o recrutamento de neutrófilos.\"],\n[\"b21\",\"aguda\",B+\"21\",\"Qual célula é a primeira a chegar ao local da lesão na inflamação aguda (nas primeiras 6-24h)?\",\n[\"Macrófago.\",\"Linfócito.\",\"Neutrófilo.\",\"Plasmócito.\"],2,\n\"Neutrófilos predominam nas primeiras 6 a 24 horas: são mais numerosos no sangue, respondem rápido às quimiocinas e aderem bem. Entre 24 e 48 horas são substituídos por monócitos/macrófagos.\"],\n[\"b22\",\"aguda\",B+\"22\",\"O exsudato purulento (pus) consiste principalmente em:\",\n[\"Monócitos e fibrina.\",\"Neutrófilos, detritos celulares e microrganismos.\",\"Líquido aquoso com pouca proteína.\",\"Hemácias e plaquetas.\"],1,\n\"Pus é exsudato rico em neutrófilos vivos e mortos, restos de células necróticas, edema e os próprios microrganismos. Típico de bactérias piogênicas, como o estafilococo.\"],\n[\"b23\",\"aguda\",B+\"23\",\"O que define uma úlcera?\",\n[\"Uma coleção de pus em um espaço fechado.\",\"Um defeito local na superfície de um órgão ou tecido por descamação de tecido necrótico inflamatório.\",\"O excesso de fluido no espaço intersticial.\",\"A substituição de células parenquimatosas por colágeno.\"],1,\n\"Úlcera é uma escavação na superfície de um órgão ou tecido causada pela descamação de tecido necrótico e inflamado. Coleção de pus em espaço fechado é abscesso.\"],\n[\"b24\",\"aguda\",B+\"24\",\"Qual enzima é responsável pela digestão do microrganismo dentro do fagolisossomo na presença de cloreto?\",\n[\"Mieloperoxidase (MPO).\",\"Catalase.\",\"Elastase.\",\"Colagenase.\"],0,\n\"A mieloperoxidase, dos grânulos azurófilos, usa H₂O₂ e cloreto para formar ácido hipocloroso (HOCl). O sistema H₂O₂-MPO-halogênio é o mais potente sistema bactericida do neutrófilo.\"],\n[\"b25\",\"aguda\",B+\"25\",\"A febre durante a inflamação é mediada por citocinas que estimulam a síntese de prostaglandinas no:\",\n[\"Fígado.\",\"Hipotálamo.\",\"Medula óssea.\",\"Córtex adrenal.\"],1,\n\"IL-1 e TNF (pirógenos endógenos) aumentam a COX e a PGE₂ no hipotálamo, que eleva o ponto de ajuste da temperatura. É por isso que anti-inflamatórios (inibidores da COX) baixam a febre.\"],\n[\"b26\",\"cronica\",B+\"26\",\"A inflamação crônica é caracterizada por:\",\n[\"Predomínio de neutrófilos e edema intenso.\",\"Infiltração por células mononucleares, destruição tecidual e tentativa de cura.\",\"Apenas congestão vascular e calor.\",\"Resolução completa em 48 horas.\"],1,\n\"Os três pilares da inflamação crônica acontecem ao mesmo tempo: infiltrado mononuclear (macrófagos, linfócitos, plasmócitos), destruição tecidual e tentativa de reparo (angiogênese e fibrose).\"],\n[\"b27\",\"cronica\",B+\"27\",\"Os macrófagos M1 (via clássica) são ativados por:\",\n[\"IL-4 e IL-13.\",\"Endotoxinas bacterianas e IFN-gama.\",\"Glicocorticoides.\",\"Vitamina D.\"],1,\n\"Via clássica (M1): produtos microbianos como a endotoxina (via TLR) e IFN-γ de células T. O resultado é um macrófago microbicida e pró-inflamatório. IL-4 e IL-13 levam ao M2.\"],\n[\"b28\",\"cronica\",B+\"28\",\"Os macrófagos M2 (via alternativa) têm como função principal:\",\n[\"Matar bactérias e fungos.\",\"Reparo tecidual e efeitos anti-inflamatórios.\",\"Apresentação de antígenos para células B apenas.\",\"Produção de óxido nítrico em grandes quantidades.\"],1,\n\"Macrófagos M2 (ativados por IL-4 e IL-13) são reparadores e anti-inflamatórios: produzem TGF-β e fatores de crescimento, estimulam angiogênese e fibrose. Matar micróbios e produzir NO é papel do M1.\"],\n[\"b29\",\"cronica\",B+\"29\",\"Células gigantes multinucleadas (tipo Langhans) na inflamação granulomatosa derivam da fusão de:\",\n[\"Neutrófilos.\",\"Macrófagos/Células epitelioides.\",\"Linfócitos B.\",\"Fibroblastos.\"],1,\n\"Células gigantes surgem da fusão de macrófagos/células epitelioides. Tipo Langhans: núcleos na periferia, em ferradura. Tipo corpo estranho: núcleos espalhados pelo citoplasma.\"],\n[\"b30\",\"cronica\",B+\"30\",\"Um granuloma com necrose central de aspecto “semelhante a queijo” é típico de:\",\n[\"Sarcoidose.\",\"Tuberculose.\",\"Reação a corpo estranho (fio de sutura).\",\"Doença de Crohn.\"],1,\n\"Necrose caseosa (branco-amarelada, friável, lembra queijo) no centro do granuloma é típica da tuberculose. Sarcoidose e Crohn formam granulomas não caseosos.\"],\n[\"b31\",\"cronica\",B+\"31\",\"Qual subpopulação de linfócitos T auxilia na defesa contra bactérias extracelulares e recruta neutrófilos?\",\n[\"Th1.\",\"Th2.\",\"Th17.\",\"T reguladores.\"],2,\n\"Th17 produz IL-17, que recruta neutrófilos e monócitos: defesa contra bactérias extracelulares e fungos. Th1 (IFN-γ) ativa macrófagos; Th2 (IL-4, IL-5, IL-13) atua sobre eosinófilos e macrófagos M2.\"],\n[\"b32\",\"cronica\",B+\"32\",\"A fibrose, uma marca da inflamação crônica, é o resultado da deposição excessiva de:\",\n[\"Glicogênio.\",\"Colágeno e outros componentes da matriz extracelular.\",\"Proteínas de choque térmico.\",\"Amiloide.\"],1,\n\"Fibrose é a deposição excessiva de colágeno e matriz extracelular pelos fibroblastos, estimulados principalmente por TGF-β, substituindo o parênquima.\"],\n[\"b33\",\"cronica\",B+\"33\",\"O que caracteriza um “granuloma de corpo estranho”?\",\n[\"Presença obrigatória de necrose caseosa.\",\"Ausência de resposta imune mediada por células T específica ao agente.\",\"Formado apenas por linfócitos.\",\"Causado sempre por Mycobacterium tuberculosis.\"],1,\n\"O granuloma de corpo estranho se forma ao redor de material inerte grande demais para ser fagocitado (fio de sutura, talco), sem resposta T específica. Os granulomas imunológicos, ao contrário, dependem de ativação de células T.\"],\n[\"b34\",\"cronica\",B+\"34\",\"Na inflamação crônica, o acúmulo de linfócitos, plasmócitos e macrófagos pode formar estruturas semelhantes a linfonodos chamadas:\",\n[\"Granulomas piogênicos.\",\"Órgãos linfoides terciários.\",\"Abscessos frios.\",\"Focos de Ghon.\"],1,\n\"Na inflamação crônica prolongada, linfócitos, células apresentadoras e plasmócitos se organizam em folículos, às vezes com centros germinativos: órgãos linfoides terciários (ex.: sinóvia na artrite reumatoide, tireoidite de Hashimoto).\"],\n[\"b35\",\"cronica\",B+\"35\",\"Qual citocina produzida pelos macrófagos estimula a migração e proliferação de fibroblastos?\",\n[\"IL-12.\",\"PDGF (Fator de Crescimento Derivado de Plaquetas).\",\"Histamina.\",\"Heparina.\"],1,\n\"O PDGF, produzido por macrófagos, plaquetas e endotélio, estimula a migração e a proliferação de fibroblastos e músculo liso. Tecnicamente é um fator de crescimento, não uma citocina clássica. IL-12 induz resposta Th1.\"],\n[\"b36\",\"aguda\",B+\"36\",\"A opsonização facilita a fagocitose. As principais opsoninas são:\",\n[\"IgG e C3b.\",\"IgE e Histamina.\",\"Leucotrienos e Prostaglandinas.\",\"Fibrinogênio e Albumina.\"],0,\n\"Opsoninas revestem o micróbio e são reconhecidas por receptores do fagócito: a IgG pelo receptor Fc e o C3b pelo receptor de complemento. Lectinas plasmáticas também opsonizam.\"],\n[\"b37\",\"cronica\",B+\"37\",\"O infiltrado celular em uma reação de hipersensibilidade aguda (alérgica) ou infecção parasitária é rico em:\",\n[\"Monócitos.\",\"Eosinófilos.\",\"Neutrófilos.\",\"Basófilos apenas.\"],1,\n\"Eosinófilos predominam em reações mediadas por IgE (alergia) e em parasitoses, recrutados por eotaxina e IL-5. A proteína básica principal dos seus grânulos é tóxica para helmintos.\"],\n[\"b38\",\"aguda\",B+\"38\",\"Qual a função da proteína do complemento C5a?\",\n[\"Opsonização de bactérias.\",\"Lise direta da parede celular via MAC.\",\"Quimiotaxia de leucócitos e anafilatoxina.\",\"Inibição da inflamação.\"],2,\n\"C5a (junto com C3a) é anafilatoxina: faz os mastócitos liberarem histamina. O C5a também é um potente quimiotático para neutrófilos. Opsonização é papel do C3b; lise é do MAC (C5b-9).\"],\n[\"b39\",\"aguda\",B+\"39\",\"A via da ciclooxigenase (COX) produz:\",\n[\"Leucotrienos.\",\"Prostaglandinas e Tromboxanos.\",\"Lipoxinas.\",\"Espécies reativas de oxigênio.\"],1,\n\"A COX (1 e 2) transforma o ácido araquidônico em prostaglandinas (PGE₂, PGI₂, PGD₂) e tromboxano A₂. Leucotrienos e lipoxinas vêm das lipoxigenases.\"],\n[\"b40\",\"cronica\",B+\"40\",\"A inflamação crônica pode ser causada por:\",\n[\"Infecções persistentes (ex: sífilis).\",\"Exposição prolongada a agentes tóxicos (ex: sílica).\",\"Doenças autoimunes.\",\"Todas as alternativas anteriores.\"],3,\n\"As três são causas clássicas: infecções persistentes (TB, sífilis, fungos), doenças de hipersensibilidade e autoimunes, e exposição prolongada a agentes tóxicos exógenos (sílica) ou endógenos (lipídios na aterosclerose).\"],\n[\"b41\",\"aguda\",B+\"41\",\"Qual o destino mais provável da inflamação aguda se o agente for eliminado e o tecido puder se regenerar?\",\n[\"Fibrose.\",\"Progressão para inflamação crônica.\",\"Resolução.\",\"Formação de abscesso.\"],2,\n\"Agente eliminado, lesão pequena e tecido capaz de regenerar: resolução, com retorno à estrutura normal. Fibrose ocorre quando a destruição é extensa ou o tecido não regenera.\"],\n[\"b42\",\"cronica\",B+\"42\",\"O que é a angiogênese, comum no processo de cura e inflamação crônica?\",\n[\"Morte de vasos sanguíneos.\",\"Formação de novos vasos a partir de vasos preexistentes.\",\"Contração de arteríolas.\",\"Deposição de cálcio na parede vascular.\"],1,\n\"Angiogênese é a formação de novos vasos por brotamento a partir de vasos que já existem, estimulada principalmente pelo VEGF. É um dos componentes do tecido de granulação.\"],\n[\"b43\",\"aguda\",B+\"43\",\"Na via do óxido nítrico (NO) nos macrófagos, o NO reage com superóxido para formar o radical altamente citotóxico:\",\n[\"Peroxinitrito.\",\"Ácido hipocloroso.\",\"Peróxido de hidrogênio.\",\"Hidroxila.\"],0,\n\"NO (da iNOS dos macrófagos ativados) + superóxido = peroxinitrito (ONOO⁻), muito reativo e microbicida. Ácido hipocloroso vem do sistema da mieloperoxidase.\"],\n[\"b44\",\"aguda\",B+\"44\",\"A adesão firme de leucócitos ao endotélio depende da ativação das:\",\n[\"Selectinas por quimiocinas.\",\"Integrinas (mudança para estado de alta afinidade).\",\"Caderinas.\",\"Mucinas.\"],1,\n\"Quimiocinas no endotélio ativam o leucócito e mudam as integrinas (LFA-1, VLA-4) para o estado de alta afinidade. Elas se ligam a ICAM-1 e VCAM-1 e o leucócito para de rolar.\"],\n[\"b45\",\"aguda\",B+\"45\",\"A morfologia da inflamação fibrinosa (ex: pericardite fibrinosa) ocorre quando:\",\n[\"O dano vascular é grande o suficiente para permitir a saída de moléculas grandes como fibrinogênio.\",\"Há apenas infecção viral leve.\",\"Ocorre hiperplasia do mesotélio.\",\"Não há exsudato proteico.\"],0,\n\"Com lesão vascular mais intensa, moléculas grandes como o fibrinogênio saem do vaso e viram fibrina no espaço extravascular. É típico de revestimentos de cavidades: pericárdio, pleura, meninges.\"],\n[\"b46\",\"adapt\",B+\"46\",\"A “morte celular programada” que não induz inflamação é a:\",\n[\"Necrose.\",\"Apoptose.\",\"Gangrena.\",\"Infarto.\"],1,\n\"Na apoptose a membrana continua íntegra e os corpos apoptóticos são fagocitados rapidamente. Como o conteúdo celular não vaza, não há inflamação. Na necrose, o conteúdo extravasa e inflama.\"],\n[\"b47\",\"aguda\",B+\"47\",\"O aumento de leucócitos imaturos no sangue durante uma infecção (“desvio à esquerda”) ocorre devido à ação de:\",\n[\"IL-10.\",\"CSFs (Fatores estimuladores de colônias).\",\"Serotonina.\",\"Colesterol.\"],1,\n\"Na infecção, IL-1 e TNF estimulam a produção de fatores estimuladores de colônias (CSFs), que aceleram a liberação de neutrófilos da medula, incluindo formas imaturas (bastões): desvio à esquerda.\"],\n[\"b48\",\"cronica\",B+\"48\",\"Células epitelioides são:\",\n[\"Células epiteliais que migraram para o tecido conjuntivo.\",\"Macrófagos ativados com citoplasma expandido que lembram células epiteliais.\",\"Células-tronco da pele.\",\"Células endoteliais em regeneração.\"],1,\n\"Células epitelioides são macrófagos ativados (por IFN-γ), com citoplasma amplo, rosado e granular e limites pouco nítidos, o que lembra epitélio. São a base do granuloma.\"],\n[\"b49\",\"aguda\",B+\"49\",\"O fator de Hageman (Fator XII) ativa quais sistemas?\",\n[\"Sistemas de coagulação e cininas.\",\"Apenas o sistema complemento.\",\"Apenas a via da COX-2.\",\"Ciclo de Krebs.\"],0,\n\"O fator XII, ativado por contato com colágeno, membrana basal ou superfícies negativas, dispara a coagulação (via intrínseca) e o sistema das cininas (bradicinina). Também participa da fibrinólise e pode ativar complemento, mas nunca “apenas” ele.\"],\n[\"b50\",\"adapt\",B+\"50\",\"Qual das seguintes opções é um exemplo de metaplasia tecidual comum no esôfago devido ao refluxo gástrico (Esôfago de Barrett)?\",\n[\"Escamosa para colunar/glandular.\",\"Glandular para escamosa.\",\"Mesenquimal para óssea.\",\"Atrofia glandular.\"],0,\n\"No esôfago de Barrett o epitélio escamoso é substituído por epitélio colunar de tipo intestinal (com células caliciformes) por causa do refluxo ácido. É lesão pré-maligna para adenocarcinoma. É o caminho inverso da metaplasia do fumante.\"],\n\n/* ---------- LISTA DE ADAPTAÇÃO E INFLAMAÇÃO (19 questões; o arquivo não tem a 17) ---------- */\n[\"c01\",\"adapt\",C+\"1\",\"Um paciente submetido a uma nefrectomia unilateral para remoção de um tumor renal apresenta, após alguns meses, aumento significativo do tamanho do rim remanescente. Qual é o mecanismo celular primário responsável por essa alteração?\",\n[\"Proliferação celular acelerada induzida por fatores de crescimento.\",\"Transformação fenotípica de fibroblastos em células tubulares.\",\"Aumento no tamanho individual das células renais.\",\"Inibição da autofagia com acúmulo de organelas hiperfuncionais.\"],2,\n\"O rim remanescente sofre hipertrofia compensatória: as células (principalmente tubulares) aumentam de tamanho para dar conta da carga de trabalho. Há pouca proliferação; o mecanismo primário é o aumento do tamanho celular.\"],\n[\"c02\",\"adapt\",C+\"2\",\"O útero grávido sofre um aumento dramático de volume e peso durante a gestação, retornando ao tamanho quase normal após o parto. Quais processos celulares participam consecutivamente desse ciclo?\",\n[\"Metaplasia escamosa seguida de necrose isquêmica.\",\"Displasia tecidual seguida de regeneração\",\"Hipertrofia e hiperplasia seguidas de atrofia por apoptose.\",\"Apenas hipertrofia isolada sem alteração no número celular.\"],2,\n\"Na gestação, o estrogênio causa hipertrofia e hiperplasia do miométrio. Depois do parto, com a queda hormonal, o útero involui: atrofia, com apoptose de células musculares.\"],\n[\"c03\",\"adapt\",C+\"3\",\"O epitélio respiratório de fumantes crônicos sofre frequentemente uma substituição do epitélio colunar pseudo-estratificado ciliado por epitélio pavimentoso estratificado. Qual é a principal implicação patológica dessa alteração?\",\n[\"Evolução direta e obrigatória para carcinoma adenocarcinoma invasivo.\",\"Aumento irreversível na secreção de surfactante pulmonar.\",\"Perda de mecanismos protetores mucociliares importantes.\",\"Transformação neoplásica benigna imediata do tecido conjuntivo.\"],2,\n\"O epitélio escamoso resiste melhor à fumaça, mas não tem cílios nem células caliciformes: perde-se a produção de muco e a depuração mucociliar. A metaplasia pode favorecer carcinoma (escamoso, não adenocarcinoma), mas não é obrigatória.\"],\n[\"c04\",\"aguda\",C+\"4\",\"Qual dos seguintes eventos vasculares iniciais ocorre classicamente logo após uma lesão tecidual aguda que desencadeia a inflamação?\",\n[\"Vasoconstrição transitória das arteríolas locais.\",\"Constrição permanente das vênulas pós-capilares.\",\"Vasodilatação prolongada mediada por fibronectina.\",\"Formação imediata de trombos oclusivos em capilares profundos.\"],0,\n\"Primeiro, vasoconstrição arteriolar transitória (segundos). Em seguida, vasodilatação mediada principalmente por histamina e NO, que causa calor e rubor.\"],\n[\"c05\",\"aguda\",C+\"5\",\"Qual o principal tipo celular encontrado no infiltrado inflamatório agudo nas primeiras 24 a 48 horas após uma infecção bacteriana piogênica?\",\n[\"Linfócitos T citotóxicos.\",\"Fibroblastos ativados.\",\"Neutrófilos polimorfonucleares.\",\"Eosinófilos hipersegmentados.\"],2,\n\"Bactérias piogênicas atraem neutrófilos polimorfonucleares, que dominam o infiltrado agudo inicial e formam o pus.\"],\n[\"c06\",\"aguda\",C+\"6\",\"Um abscesso cutâneo fechado caracterizado por acúmulo local de pus representa qual padrão morfológico de inflamação aguda?\",\n[\"Inflamação fibrinosa com deposição de malhas de fibrina densa.\",\"Inflamação supurativa (ou purulenta).\",\"Inflamação serosa com predomínio de transudato albumínico.\",\"Úlcera péptica de mucosa.\"],1,\n\"Abscesso é uma coleção localizada de pus (neutrófilos e necrose liquefativa) em espaço fechado: padrão supurativo ou purulento.\"],\n[\"c07\",\"aguda\",C+\"7\",\"A inflamação fibrinosa ocorre tipicamente em cavidades de revestimento corporal (como meninges, pericárdio e pleura). Qual é o destino final mais comum da fibrina acumulada se o estímulo inflamatório for leve a moderado?\",\n[\"Transformação metaplásica em cartilagem hialina.\",\"Conversão espontânea em cristais de colesterol.\",\"Remoção por fibrinólise e fagocitose por macrófagos (resolução).\",\"Calcificação distrófica maciça imediata sem fibrose.\"],2,\n\"A fibrina pode ser dissolvida por fibrinólise e removida por macrófagos: resolução. Se não for removida, é invadida por fibroblastos e vasos (organização) e vira tecido fibroso, com aderências.\"],\n[\"c08\",\"aguda\",C+\"8\",\"O que caracteriza morfologicamente uma úlcera em mucosas ou pele afetada por processo inflamatório agudo?\",\n[\"Proliferação benigna hiperplásica de glândulas mucosas com fibrose estromal.\",\"Defeito ou escavação local na superfície do órgão devido à esfoliação de tecido necrótico inflamado.\",\"Formação de uma falsa membrana pseudomembranosa na superfície luminal.\",\"Acúmulo encapsulado de tecido granulomatoso epiteloide estéril.\"],1,\n\"Úlcera é o defeito local na superfície causado pela descamação de tecido necrótico e inflamado. Pseudomembrana é outra coisa (exsudato fibrinoso aderido à superfície).\"],\n[\"c09\",\"aguda\",C+\"9\",\"Qual dos seguintes desfechos da inflamação aguda é caracterizado por completa restauração do tecido ao seu estado normal prévio, com remoção total do exsudato e debris?\",\n[\"Resolução.\",\"Organização (cicatrização por fibrose).\",\"Metaplasia regenerativa persistente.\",\"Progressão para inflamação crônica fibrinoide.\"],0,\n\"Resolução: o exsudato e os restos são removidos (drenagem linfática e macrófagos), os mediadores são neutralizados e o tecido volta ao normal. Organização é substituição por tecido fibroso.\"],\n[\"c10\",\"cronica\",C+\"10\",\"Diferente da inflamação aguda, a inflamação crônica é caracterizada histologicamente pela presença de quais tipos celulares principais?\",\n[\"Linfócitos, plasmócitos e macrófagos.\",\"Eosinófilos e mastócitos exclusivamente.\",\"Fibroblastos imaturos e osteoclastos gigantes.\",\"Neutrófilos polimorfonucleares e plaquetas ativadas.\"],0,\n\"Células mononucleares são a marca histológica da inflamação crônica: macrófagos (célula dominante), linfócitos e plasmócitos. Neutrófilos são a marca da aguda.\"],\n[\"c11\",\"cronica\",C+\"11\",\"O que caracteriza morfologicamente a inflamação granulomatosa, um subtipo especializado de inflamação crônica?\",\n[\"Presença de focos de necrose fibrinoide isolada sem células inflamatórias.\",\"Agregados compactos de macrófagos ativados modificados (células epitelióides), frequentemente cercados por linfócitos e células gigantes.\",\"Proliferação difusa de neutrófilos em meio a exsudato purulento extenso.\",\"Acúmulo exclusivo de mastócitos e eosinófilos em torno de vasos sanguíneos.\"],1,\n\"Granuloma: agregado compacto de células epitelioides (macrófagos ativados), frequentemente com células gigantes multinucleadas e um halo de linfócitos. Pode ou não ter necrose central.\"],\n[\"c12\",\"cronica\",C+\"12\",\"Na inflamação granulomatosa causada pelo agente da tuberculose (Mycobacterium tuberculosis), qual tipo de necrose é classicamente associado ao centro do granuloma?\",\n[\"Necrose caseosa.\",\"Necrose gangrenosa seca.\",\"Necrose gordurosa enzimática.\",\"Necrose liquefativa pura.\"],0,\n\"Na tuberculose o centro do granuloma tem necrose caseosa: material amorfo, granular, eosinofílico, sem contornos celulares, com aspecto macroscópico de queijo.\"],\n[\"c13\",\"cronica\",C+\"13\",\"Qual é a diferença fundamental entre granulomas imunológicos e granulomas de corpo estranho?\",\n[\"Granulomas de corpo estranho apresentam sempre necrose caseosa extensa.\",\"Não há distinção histológica ou etiológica descrita no Robbins.\",\"Granulomas de corpo estranho formam-se ao redor de materiais inertes grandes; granulomas imunológicos são induzidos por agentes persistentes que estimulam a imunidade mediada por células T.\",\"Granulomas imunológicos não contêm células gigantes, apenas neutrófilos necróticos.\"],2,\n\"Corpo estranho: material inerte grande demais para fagocitar (sutura, talco), sem resposta T específica. Imunológico: agente persistente ou pouco degradável que ativa células T (Th1, IFN-γ), que ativam os macrófagos. Ex.: TB.\"],\n[\"c14\",\"aguda\",C+\"14\",\"Quais são os principais sinais cardinais clássicos da inflamação descritos desde a antiguidade por Celsus e Virchow?\",\n[\"Prurido, vesiculação, atrofia, esclerose e ulceração.\",\"Febre, calafrios, leucocitose, caquexia e necrose.\",\"Rubor, calor, tumor, dor e perda de função.\",\"Palidez, cianose, hipotensão, choque e acidose.\"],2,\n\"Celsus descreveu rubor, calor, tumor e dor. Virchow acrescentou o quinto sinal: perda de função (functio laesa).\"],\n[\"c15\",\"aguda\",C+\"15\",\"O que diferencia primariamente um exsudato inflamatório de um transudato não inflamatório?\",\n[\"Não há diferença físico-química mensurável entre ambos na prática médica.\",\"O exsudato apresenta alta concentração de proteínas e densidade específica elevada, decorrente do aumento da permeabilidade vascular.\",\"O transudato contém grande quantidade de neutrófilos íntegros e restos celulares.\",\"O exsudato é formado exclusivamente por diminuição da pressão oncótica plasmática.\"],1,\n\"Exsudato: proteínas altas, densidade acima de 1,020, células e restos celulares, por aumento de permeabilidade. Transudato: pobre em proteínas, densidade baixa, vasos íntegros, causado por pressão hidrostática alta ou oncótica baixa.\"],\n[\"c16\",\"adapt\",C+\"16\",\"Qual é a consequência celular imediata sobre o tecido quando o suprimento sanguíneo é interrompido de forma abrupta, levando à hipóxia severa?\",\n[\"Aumento imediato na proliferação de mitocôndrias e síntese de glicogênio.\",\"Redução drástica na síntese de ATP pela fosforilação oxidativa mitocondrial.\",\"Ativação estrita de vias de reparo tecidual mediadas por colágeno tipo I.\",\"Conversão irreversível e imediata de todas as células em tecido adiposo.\"],1,\n\"Sem oxigênio, a fosforilação oxidativa para e o ATP despenca. Em cascata: falha da bomba Na⁺/K⁺ (edema celular), glicólise anaeróbia (acidose, queda do glicogênio) e queda da síntese proteica.\"],\n[\"c18\",\"adapt\",C+\"18\",\"Qual é a diferença fundamental entre calcificação distrófica e calcificação metastática segundo o Robbins?\",\n[\"A calcificação distrófica ocorre em tecidos necrosados com calcemia normal; a calcificação metastática ocorre em tecidos normais associada à hipercalcemia.\",\"Não existe diferença clínica ou patológica entre ambas as formas de calcificação.\",\"A calcificação distrófica requer níveis sistêmicos elevados de paratormônio.\",\"A calcificação metastática acomete exclusivamente válvulas cardíacas necróticas.\"],0,\n\"Distrófica: em tecido morto ou lesado, com cálcio sérico normal (ateromas, valvas lesadas, necrose caseosa). Metastática: em tecido normal, por hipercalcemia (hiperparatireoidismo, destruição óssea, excesso de vitamina D).\"],\n[\"c19\",\"aguda\",C+\"19\",\"Qual é a principal função morfológica e patológica da inflamação fibrinosa que ocorre classicamente no pericárdio ou na pleura?\",\n[\"Formação imediata de necrose caseosa generalizada com cavitação pulmonar estéril.\",\"Proliferação neoplásica benigna de células mesoteliais induzida por infecção viral.\",\"Acúmulo de exsudato rico em fibrinogênio que se converte em fibrina, podendo sofrer resolução ou resultar em fibrose e aderências (organização).\",\"Acúmulo estrito de neutrófilos e liquefação necrótica purulenta em cavidade fechada.\"],2,\n\"O fibrinogênio extravasado vira fibrina. Dois destinos: fibrinólise e remoção (resolução) ou organização por fibroblastos e vasos, deixando fibrose e aderências (ex.: pericardite constritiva).\"],\n[\"c20\",\"cronica\",C+\"20\",\"Em uma úlcera péptica ou cutânea crônica, qual é a principal alteração histológica encontrada na base e nas bordas da lesão ao longo do tempo?\",\n[\"Metaplasia escamosa total do tecido muscular subjacente sem infiltrado inflamatório.\",\"Presença exclusiva de neutrófilos degenerados sem qualquer sinal de cicatrização ou tecido de granulação.\",\"Combinação de inflamação aguda na base, infiltrado mononuclear crônico periférico, proliferação de fibroblastos e angiogênese (tecido de granulação).\",\"Transformação sarcomatosa maligna imediata de células endoteliais locais.\"],2,\n\"Na úlcera crônica coexistem: inflamação aguda na base (neutrófilos), infiltrado mononuclear nas bordas e tentativa de reparo com tecido de granulação (fibroblastos e novos vasos), que evolui para cicatriz.\"],\n\n/* ---------- PROVAS ANTIGAS: prova de Patologia Geral (itens 06 a 16, transcritos como estão na prova) ---------- */\n[\"p06\",\"provas\",P+\"06\",\"Homem de 65 anos sofre AVC isquêmico. A área afetada apresenta digestão completa do tecido, formando uma cavidade líquida. Esse tipo de necrose é:\",\n[\"Liquefativa.\",\"Coagulativa.\",\"Caseosa.\",\"Gordurosa.\"],0,\n\"No sistema nervoso central, a necrose isquêmica é liquefativa: o tecido cerebral tem pouca matriz de sustentação e muitas enzimas, então é digerido e vira uma cavidade com líquido e restos. Em quase todos os outros órgãos sólidos, a isquemia causa necrose coagulativa.\"],\n[\"p07\",\"provas\",P+\"07\",\"Paciente de 40 anos sofre corte profundo na pele. Após alguns dias, observa-se tecido avermelhado, rico em capilares e fibroblastos. Esse tecido é característico de:\",\n[\"Tecido de granulação.\",\"Atrofia.\",\"Calcificação.\",\"Necrose.\"],0,\n\"Tecido de granulação é o tecido de reparo que aparece entre 3 e 5 dias: capilares novos (angiogênese), fibroblastos proliferando e matriz frouxa. Na ferida ele é rosado, avermelhado, granuloso e sangra com facilidade.\"],\n[\"p08\",\"provas\",P+\"08\",\"Paciente com hiperparatireoidismo apresenta depósitos de cálcio em pulmões e rins sem lesão prévia. Esse fenômeno corresponde a:\",\n[\"Calcificação metastática.\",\"Calcificação distrófica.\",\"Necrose.\",\"Fibrose.\"],0,\n\"Calcificação metastática ocorre em tecidos normais quando há hipercalcemia. No hiperparatireoidismo, o PTH alto retira cálcio dos ossos, e os depósitos aparecem principalmente em pulmões, rins, mucosa gástrica e vasos.\"],\n[\"p09\",\"provas\",P+\"09\",\"Durante choque séptico, células apresentam aumento do cálcio intracelular, ativando enzimas degradativas. Esse mecanismo contribui para:\",\n[\"Regeneração.\",\"Lesão celular.\",\"Metaplasia.\",\"Hiperplasia.\"],1,\n\"O cálcio alto no citosol ativa enzimas que destroem a célula: fosfolipases (membranas), proteases (citoesqueleto), endonucleases (DNA) e ATPases (gastam ATP). Ele também aumenta a permeabilidade das mitocôndrias. É um mecanismo central de lesão celular.\"],\n[\"p10\",\"provas\",P+\"10\",\"Paciente idoso apresenta aumento do estresse oxidativo celular ao longo dos anos. Esse processo resulta principalmente em:\",\n[\"Proteção celular.\",\"Dano oxidativo.\",\"Crescimento celular.\",\"Regeneração.\"],1,\n\"Com os anos, os radicais livres (espécies reativas de oxigênio) se acumulam e causam dano oxidativo: peroxidação dos lipídios das membranas, alteração de proteínas e lesão do DNA. Esse dano acumulado é uma das bases do envelhecimento celular e gera a lipofuscina.\"],\n[\"p11\",\"provas\",P+\"11\",\"Paciente com fratura óssea inicia processo de cicatrização. Qual célula é responsável pela síntese de colágeno no local?\",\n[\"Neutrófilo.\",\"Fibroblasto.\",\"Linfócito.\",\"Hemácia.\"],1,\n\"O fibroblasto é a célula que sintetiza colágeno e matriz extracelular no reparo, estimulado principalmente por TGF-β e PDGF. Na pele ele forma a cicatriz; na fratura participa da formação do calo.\"],\n[\"p12\",\"provas\",P+\"12\",\"Em análise histológica, a hematoxilina é utilizada para corar estruturas celulares. Qual componente é mais evidenciado?\",\n[\"Lipídios.\",\"Cálcio.\",\"Núcleo.\",\"Citoplasma.\"],2,\n\"A hematoxilina é um corante básico: cora estruturas ácidas (basófilas), principalmente o núcleo, rico em DNA e RNA, em azul-arroxeado. A eosina, que é ácida, cora o citoplasma e o colágeno de rosa.\"],\n[\"p13\",\"provas\",P+\"13\",\"Paciente com queimadura extensa evolui com formação de cicatriz. Esse desfecho ocorre principalmente quando:\",\n[\"Há regeneração completa.\",\"Não há angiogênese.\",\"Não há inflamação.\",\"A matriz extracelular é destruída.\"],3,\n\"Para regenerar, o tecido precisa de células capazes de se dividir e da matriz extracelular (o arcabouço) intacta. Na queimadura extensa a matriz é destruída, o tecido não consegue se reconstruir e o reparo acontece por deposição de colágeno: cicatriz.\"],\n[\"p14\",\"provas\",P+\"14\",\"Durante o processamento histológico uma das etapas é a selagem. Qual o principal objetivo dessa etapa?\",\n[\"Fixação do material.\",\"Proteção do material na parafina.\",\"Proteção do material na lâmina.\",\"Facilita a coloração.\"],2,\n\"A selagem (montagem) é a última etapa: depois da coloração, coloca-se o meio de montagem e a lamínula sobre o corte. Isso protege o material na lâmina e permite guardá-lo e observá-lo ao microscópio por muito tempo.\"],\n[\"p15\",\"provas\",P+\"15\",\"Paciente diabético apresenta hiperglicemia crônica, levando à glicação de proteínas intracelulares. Esse processo é classificado como:\",\n[\"Depósito intracelular patológico.\",\"Necrose.\",\"Apoptose.\",\"Calcificação.\"],0,\n\"Na hiperglicemia crônica, a glicose se liga às proteínas sem ajuda de enzimas (glicação), formando produtos de glicação avançada que se acumulam. É um acúmulo (depósito) patológico, não morte celular.\"],\n[\"p16\",\"provas\",P+\"16\",\"Paciente com sangramento prévio nos tecidos. Esse pigmento é classificado como:\",\n[\"Lipofuscina.\",\"Hemossiderina.\",\"Calcificação.\",\"Glicogênio.\"],1,\n\"Hemossiderina é o pigmento derivado da hemoglobina. Depois de um sangramento, os macrófagos fagocitam as hemácias e o ferro fica guardado como hemossiderina, um pigmento castanho-dourado. É o que deixa o hematoma amarelado na evolução, e cora de azul pelo método de Perls.\"],\n\n/* ---------- PROVAS ANTIGAS: questão discursiva da prova ---------- */\n[\"d01\",\"provas\",\"Prova de Patologia Geral, questão discursiva (item 1, valor 1,0)\",\n\"<p>Homem de 48 anos, com histórico de etilismo crônico há mais de 20 anos, procura o pronto-socorro com dor abdominal intensa, de início súbito, localizada em epigástrio e irradiando para o dorso. Refere náuseas, vômitos e piora da dor após ingestão de alimentos.</p><p>Ao exame físico, apresenta dor à palpação abdominal profunda, principalmente em epigástrio, além de sinais de irritação peritoneal leve. Exames laboratoriais mostram elevação significativa de amilase e lipase séricas. A tomografia abdominal evidencia aumento do pâncreas, áreas de edema e focos sugestivos de necrose. O diagnóstico é de pancreatite aguda.</p><p>a) Qual é o tipo de necrose que está ocorrendo?<br>b) Descreva as alterações macro e microscópicas observadas nesse tipo de necrose.</p>\",\n[],-1,\"\"],\n\n/* ---------- PROVAS ANTIGAS: questões extras no mesmo estilo (não caíram na prova) ---------- */\n[\"x01\",\"provas\",X,\"Paciente sofre infarto agudo do miocárdio. Ao microscópio, as células mortas mantêm o contorno, mas perdem o núcleo. Esse tipo de necrose é:\",\n[\"Coagulativa.\",\"Liquefativa.\",\"Caseosa.\",\"Gordurosa.\"],0,\n\"Na isquemia do coração, a necrose é coagulativa: as proteínas e as próprias enzimas se desnaturam, então a arquitetura do tecido e o contorno das células ficam preservados por dias, como \\\"fantasmas\\\" de células, mas sem núcleo.\"],\n[\"x02\",\"provas\",X,\"Paciente com tuberculose pulmonar apresenta lesão com material branco-amarelado, friável, semelhante a queijo. Esse tipo de necrose é:\",\n[\"Gordurosa.\",\"Caseosa.\",\"Coagulativa.\",\"Fibrinoide.\"],1,\n\"Necrose caseosa é típica da tuberculose: macroscopicamente parece queijo; ao microscópio é um material amorfo, rosado e granular, sem contornos celulares, geralmente no centro de um granuloma.\"],\n[\"x03\",\"provas\",X,\"Paciente idoso apresenta células do coração e do fígado com pigmento castanho-amarelado ao redor do núcleo, resultante do desgaste celular. Esse pigmento é:\",\n[\"Hemossiderina.\",\"Melanina.\",\"Lipofuscina.\",\"Bilirrubina.\"],2,\n\"Lipofuscina é o pigmento do desgaste celular: restos de membranas oxidadas (peroxidação lipídica) que ficam em vacúolos. É castanho-amarelado, perinuclear, e aumenta com a idade e na atrofia.\"],\n[\"x04\",\"provas\",X,\"Paciente com estenose da valva aórtica apresenta depósitos de cálcio na valva lesionada, com cálcio sérico normal. Esse fenômeno corresponde a:\",\n[\"Calcificação metastática.\",\"Calcificação distrófica.\",\"Ossificação.\",\"Hiperplasia.\"],1,\n\"Calcificação distrófica acontece em tecido lesado, degenerado ou necrótico, com cálcio no sangue normal. Valvas cardíacas lesionadas, ateromas e necrose caseosa são exemplos clássicos.\"],\n[\"x05\",\"provas\",X,\"Paciente etilista crônico apresenta fígado aumentado e amarelado, com vacúolos de gordura no citoplasma dos hepatócitos. Esse achado é:\",\n[\"Esteatose.\",\"Necrose gordurosa.\",\"Metaplasia.\",\"Calcificação.\"],0,\n\"Esteatose é o acúmulo de triglicerídeos dentro de células vivas, principalmente hepatócitos. O álcool é a causa mais comum: o fígado fica aumentado, amarelado e gorduroso, e os hepatócitos mostram vacúolos de gordura.\"],\n[\"x06\",\"provas\",X,\"Em uma célula que sofre necrose, o núcleo se condensa, fica pequeno e muito escuro. Essa alteração nuclear é chamada de:\",\n[\"Cariorrexe.\",\"Cariólise.\",\"Picnose.\",\"Mitose.\"],2,\n\"As alterações do núcleo na necrose são três: picnose (núcleo encolhe e fica muito basofílico), cariorrexe (núcleo se fragmenta) e cariólise (núcleo perde a cor e desaparece).\"],\n[\"x07\",\"provas\",X,\"Na coloração de rotina (H&E), a eosina é utilizada para corar principalmente:\",\n[\"Núcleo.\",\"Citoplasma e matriz extracelular.\",\"Lipídios.\",\"DNA.\"],1,\n\"A eosina é um corante ácido: cora estruturas básicas (acidófilas ou eosinofílicas), como o citoplasma e o colágeno, em rosa. A hematoxilina cora o núcleo.\"],\n[\"x08\",\"provas\",X,\"Durante o processamento histológico, o formol é utilizado logo após a coleta da peça. Qual o principal objetivo dessa etapa?\",\n[\"Fixação do material.\",\"Desidratação.\",\"Inclusão em parafina.\",\"Coloração.\"],0,\n\"O formol fixa o material: interrompe a autólise e a ação de bactérias e preserva a estrutura do tecido. É a primeira etapa, feita logo após a coleta.\"],\n[\"x09\",\"provas\",X,\"Células de um tecido sofrem morte programada, com condensação da cromatina e formação de corpos apoptóticos, sem inflamação. Esse processo é:\",\n[\"Necrose.\",\"Apoptose.\",\"Autólise.\",\"Calcificação.\"],1,\n\"Na apoptose a célula se condensa, fragmenta o núcleo e se divide em corpos apoptóticos com membrana íntegra, que são fagocitados rapidamente. Como o conteúdo não vaza, não há inflamação.\"],\n[\"x10\",\"provas\",X,\"Durante a isquemia, a falta de oxigênio reduz a produção de ATP. A primeira alteração celular, ainda reversível, é:\",\n[\"Tumefação celular.\",\"Cariorrexe.\",\"Calcificação.\",\"Necrose caseosa.\"],0,\n\"Sem ATP, a bomba de sódio e potássio para: sódio e água entram e a célula incha (tumefação celular ou degeneração hidrópica). É a primeira alteração da lesão e ainda é reversível.\"],\n[\"d02\",\"provas\",\"Discursiva extra no estilo da prova (valor 1,0)\",\n\"<p>Homem de 58 anos, tabagista e hipertenso, dá entrada no pronto-socorro com dor torácica intensa há 6 horas e evolui para óbito 4 dias depois. Na necropsia, observa-se área pálida e bem delimitada na parede do ventrículo esquerdo.</p><p>a) Qual é o tipo de necrose que está ocorrendo?<br>b) Descreva as alterações macro e microscópicas observadas nesse tipo de necrose.</p>\",\n[],-1,\"\"]\n,\n\n/* ================= PROVA FIMCA 1 ================= */\n[\"f01\",\"provas\",F1+\"01\",\"Evaldo, 45 anos, atleta de alto desempenho, que realiza levantamento de peso há 15 anos. Notou que seus músculos estavam maiores e mais fortes. O médico explicou que essa mudança é uma adaptação celular natural do músculo à atividade física intensa.<br><br>Qual das opções melhor explicam as adaptações celulares que ocorreram no músculo de Evaldo?\",\n[\"Atrofia e hipertrofia.\",\"Hipertrofia e hiperplasia.\",\"Hiperplasia e metaplasia.\",\"Hipertrofia e displasia.\",\"Metaplasia e displasia.\"],1,\n\"O músculo cresceu por aumento de demanda. Na correção da prova a resposta foi “Hipertrofia e hiperplasia”, a única alternativa só com adaptações de aumento. Para discutir: o músculo esquelético adulto quase não se divide, então o componente principal é a hipertrofia (fibras maiores, com mais proteínas contráteis).\"],\n[\"f02\",\"provas\",F1+\"02\",\"1. A principal causa de morte celular irreversível é a lesão isquêmica prolongada, que ocorre quando há interrupção do suprimento sanguíneo para a célula ou tecido,<br><b>PORQUE</b><br>2. a falta de oxigênio e nutrientes essenciais leva a uma cascata de eventos que resulta na morte celular por liberação de enzimas lisossômicas e produção de radicais livres.<br><br>Podemos afirmar que:\",\nASSERT.slice(),4,\n\"As duas afirmativas estão corretas e a segunda explica a primeira. A isquemia é a causa mais comum de lesão celular: sem oxigênio o ATP cai, as membranas são lesadas, as enzimas lisossômicas vazam e digerem a célula, e formam-se radicais livres.\"],\n[\"f03\",\"provas\",F1+\"03\",\"A apoptoses é um processo de morte celular programada que ocorre naturalmente em vários tecidos e órgãos.<br><br>Qual das opções é uma característica típica da apoptose?\",\n[\"Inflamação aguda.\",\"Degeneração hidrópica.\",\"Calcificação metastática.\",\"Fragmentação nuclear e citoplasmática.\",\"Depósitos de lipofuscina.\"],3,\n\"Na apoptose a célula encolhe, a cromatina se condensa, o núcleo se fragmenta e a célula se divide em corpos apoptóticos com pedaços de citoplasma e núcleo, que são fagocitados sem inflamação.\"],\n[\"f04\",\"provas\",F1+\"04\",\"Marcos, 65 anos, etilista crônico, foi internado por dor abdominal intensa e febre. Ele foi submetido a TC de abdome que revelou área de necrose de pâncreas e edema peripancreático. A equipe médica diagnosticou pancreatite necrosante.<br><br>Qual das seguintes opções descreve o tipo de necrose que ocorreu no pâncreas e tecido peripancreático adjacente respectivamente.\",\n[\"Necrose liquefativa e necrose de coagulação.\",\"Necrose gordurosa e necrose caseosa.\",\"Necrose de coagulação e necrose gordurosa.\",\"Necrose gangrenosa e necrose liquefativa.\",\"Necrose gordurosa e necrose fibrinoide.\"],2,\n\"Atenção ao “respectivamente”: primeiro o pâncreas, depois a gordura ao redor. No tecido adiposo peripancreático, as lipases causam necrose gordurosa (saponificação). A única alternativa que coloca a gordurosa no lugar certo é a de coagulação (pâncreas) e gordurosa (peripancreático).\"],\n[\"f05\",\"provas\",F1+\"05\",\"Roberto, 48 anos, com histórioco de tuberculose pulmonar, febre, tosse com expectoração purulenta e dispneia. A radiografia de tórax revela um padrão de infiltrado com cavitação pulmonar. A biópsia pulmonar é realizada e revela áreas de necrose caseosa, cercadas por uma reação inflamatória crônica.<br><br>Qual das seguintes opções apresenta uma microscopia típica dessa lesão pulmonar?\",\n[\"Processo inflamatório crônico granulomatoso rico em células gigantes multinucleadas e centro de necrose caseosa.\",\"Processo inflamatório crônico inespecífico com formação de gigantócitos e necrose caseosa central.\",\"Processo inflamatório crônico agudizado com presença de corpo estranho inerte e formação de granulomas.\",\"Processo inflamatório crônico inespecífico com tecido de granulação associado.\",\"Fibrose tecidual, proliferação vascular e ausência de granulomas.\"],0,\n\"Tuberculose é inflamação crônica granulomatosa: granulomas com macrófagos epitelioides, células gigantes multinucleadas (tipo Langhans), halo de linfócitos e centro de necrose caseosa.\"],\n[\"f06\",\"provas\",F1+\"06\",\"Mariana, 5 anos, foi levado ao PS infantil por febre elevada, rouquidão, dor de gargata e perda de apetite. Foi diagnosticada com amigdalite bacteriana supurativa.<br><br>Qual das alternativas apresentam características dessa doença?\",\n[\"Linfocitose característica de infecções virais.\",\"Infiltrado inflamatório neutrofílico e edema.\",\"Necrose fibrinoide vascular.\",\"Infiltrado linfomononuclear com granulomas.\",\"Infiltrado inflamatório agudo úlcero-flegmonoso.\"],1,\n\"Infecção bacteriana aguda e supurativa (com pus): infiltrado rico em neutrófilos e edema, pelo aumento da permeabilidade vascular.\"],\n[\"h07\",\"provas\",\"Prova FIMCA 1, discursiva (item 07, valor 2,00)\",\n\"<p>Durante a inflamação, as células imunológicas liberam mediadores químicos que causam vasodilatação e aumento da permeabilidade vascular, permitindo a saída de células do sistema imunológico para o local afetado.</p><p>Baseado nessas informações responda as questões:<br>a) Descreva sucintamente o papel da inflamação no organismo vivo, vascularizado.<br>b) Como diferenciar didaticamente uma inflamação aguda da crônica?</p>\",[],-1,\"\"],\n[\"h08\",\"provas\",\"Prova FIMCA 1, discursiva (item 08, valor 2,00)\",\n\"<p>Solange, 28 anos, refere colecistectomia por videolaparoscopia há seis meses, refere estar incomodada com a cicatriz que não gostou esteticamente, sem outras queixas.</p><p>Baseado no caso clínico e em seus conhecimentos responda:<br>a) Descreva a importância da matriz extracelular (MEC) no processo de reparo tecidual.<br>b) Descreva sucintamente três distúrbios que podem ocorrer no processo de reparo tecidual.</p>\",[],-1,\"\"],\n\n/* ================= PROVA METROPOLITANA 2 ================= */\n[\"m01\",\"provas\",M2+\"01\",\"Como pudemos vivenciar nas aulas práticas de laboratório a avaliação histopatológica de materiais como biópsias, peças cirúrgicas e exames citológicos, bem como estudar que para a preparação de uma lâmina para microscopia óptica é necessário uma série de etapas a serem seguidas para posterior análise microscópica final.<br><br>Assinale a alternativa que destaca diferenças importantes entre a os exames histopatológicos e citológicos.\",\n[\"Forma de coleta do material e fixação do material coletado.\",\"Forma de processamento do material e selagem das lâminas.\",\"A avaliação arquitetural do tecido é possível em ambos exames.\",\"Avaliação dos núcleos e citoplasma das células apenas nos exames citológicos.\",\"Colorações histoquímicas especiais (exceto HE), é possível apenas nos exames histopatológicos.\"],0,\n\"Histopatologia e citologia diferem já na coleta e na fixação. Na histopatologia retira-se um fragmento de tecido (biópsia, peça cirúrgica), fixado em formol e incluído em parafina, o que permite ver a arquitetura. Na citologia coletam-se células soltas (raspado, punção, líquidos), estendidas na lâmina e fixadas geralmente em álcool, sem arquitetura.\"],\n[\"m02\",\"provas\",M2+\"02\",\"Baseado no seguinte caso clínico responda o item 02 e o item 03.<br>Isabel, 60 anos, foi diagnosticada com câncer de mama. Ela iniciou um tratamento de quimioterapia há algumas semanas. Uma biópsia é realizada para avaliar as células tumorais e os efeitos do tratamento.<br><br>Qual das seguintes características seria mais indicativa de <b>apoptose</b> na biópsia das células tumorais?\",\n[\"Tumefação celular.\",\"Preservação da morfologia nuclear.\",\"Liberação de enzimas lisossômicas.\",\"Fragmentação celular dentro de macrófagos.\",\"Transformação de células em conteúdo líquido.\"],3,\n\"Na apoptose a célula se fragmenta em corpos apoptóticos, rapidamente fagocitados por macrófagos. Ver fragmentos celulares dentro de macrófagos é a marca da apoptose. A quimioterapia mata células tumorais principalmente por apoptose, pelo dano ao DNA.\"],\n[\"m03\",\"provas\",M2+\"03\",\"Além da apoptose, diversas neoplasias podem apresentar <b>necrose isquêmica</b> associada, qual das seguintes características é possível observar nesse tipo de necrose.\",\n[\"Transformação de células em conteúdo líquido.\",\"Preservação da arquitetura tecidual por algum tempo.\",\"Material hialino perivascular.\",\"Material granuloso circundado por granulomas.\",\"Material amorfo rico em células gigantes multinucleadas.\"],1,\n\"Necrose isquêmica em tecido sólido é necrose de coagulação: proteínas e enzimas se desnaturam, então a arquitetura do tecido e o contorno das células ficam preservados por alguns dias.\"],\n[\"m04\",\"provas\",M2+\"04\",\"Baseado no seguinte caso clínico responda o item 04, o item 05 e o item 6he.<br>Daniel, 48 anos, etilista crônico, apresenta-se ao médico com queixas de fadiga crônica e desconforto abdominal. Exames laboratoriais revelam níveis elevados de enzimas hepáticas e aumento hepático ao exame de USG. Uma biópsia hepática é realizada para avaliar as alterações nas células do fígado.<br><br>Considerando os sintomas de Daniel e a investigação da biópsia hepática, qual das seguintes características seria mais indicativa das possíveis lesões celulares reversíveis?\",\n[\"Tumefação celular e esteatonecrose.\",\"Esteatose e fragmentação nuclear.\",\"Tumefação e sombras celulares.\",\"Esteatonecrose e degeneração gordurosa.\",\"Esteatose e tumefação celular.\"],4,\n\"As duas lesões reversíveis clássicas são a tumefação celular (degeneração hidrópica) e a esteatose (degeneração gordurosa). No etilista, os hepatócitos acumulam gordura (esteatose).\"],\n[\"m05\",\"provas\",M2+\"05\",\"Uma das principais causas de pancreatite aguda ocorre pelo consumo de álcool. Dentre as necroses observadas no tecido adiposo peripancretático, podemos descrever os seguintes achados.\",\n[\"Arquitetura básica do tecido necrótico é preservada por alguns dias.\",\"Transformação do tecido em material líquido.\",\"Restos granulares com formação de granulomas.\",\"Destruição de adipócitos e ácidos graxos combinados com cálcio.\",\"Aparência amorfa eosinofílica nos vasos.\"],3,\n\"Na pancreatite, as lipases destroem os adipócitos. Os ácidos graxos liberados se combinam com o cálcio (saponificação), formando áreas branco-giz: é a necrose gordurosa.\"],\n[\"m06\",\"provas\",M2+\"06\",\"Considerando que os hepatócitos são células estáveis, caso Daniel continue consumindo álcool e inicie um processo de destruição do parênquima hepático. Qual das adaptações celulares é a mais provável encontrarmos nos hepatócitos remanescentes durante esse processo de evolução?\",\n[\"Atrofia e hiperplasia.\",\"Metaplasia e hipertrofia.\",\"Hiperplasia e hipertrofia.\",\"Metaplasia e atrofia.\",\"Hiperplasia e metaplasia.\"],2,\n\"Hepatócitos são células estáveis: ficam quietos, mas voltam a se dividir quando há perda de tecido. Os que sobram respondem com hiperplasia (dividem-se) e hipertrofia (aumentam de tamanho) para compensar.\"],\n[\"m07\",\"provas\",M2+\"07\",\"Maria, 75 anos, procura atendimento médico devido a queixas de perda de elasticidade da pele, rugas e redução da força muscular. Uma avaliação médica é realizada para entender as alterações celulares associadas ao envelhecimento.<br><br>Considerando as queixas de Maria e a avaliação médica, qual das seguintes características seria mais indicativa de envelhecimento celular?\",\n[\"Aumento da capacidade de regeneração tecidual.\",\"Acúmulo de danos no DNA.\",\"Preservação da função mitocondrial.\",\"Ativação de células quiescentes.\",\"Atividade celular aumentada.\"],1,\n\"O envelhecimento celular resulta do acúmulo de dano: no DNA (mutações e falha de reparo), nas proteínas e nas mitocôndrias (radicais livres), além do encurtamento dos telômeros e da senescência. A capacidade de regeneração cai.\"],\n[\"m08\",\"provas\",M2+\"08\",\"As reações de redução-oxidação com formação de diferentes espécies reativas de oxigênio podem estimular a produção de enzimas de degradação que lesam às células. Também é possível que essas moléculas quando produzidas em condições fisiológicas desempenhem papeis importantes ao funcionamento celular. Leia atentamente as afirmativas abaixo.<br>1- Os radicais livres causam peroxidação dos lipídios dentro das membranas plasmáticas e organelas.<br>2- Os radicais livres são capazes de formar complexos de adição que favorecem o reparo do dano oxidativo causado no DNA.<br>3- O óxido nítrico é um mediador químico importante gerado por células endoteliais e macrófagos e pode atuar como radical livre.<br>4- As proteínas não dobradas ou mal dobradas conferem funções adaptativas positivas para a célula afetada.<br><br>Assinale a opção que demonstra a correspondência correta, sendo (F) para afirmativa falsa e (V) para a afirmativa verdadeira.\",\n[\"1- F, 2- V, 3- V, 4- F.\",\"1- F, 2- F, 3- V, 4-V.\",\"1- V, 2- V, 3- F, 4- F.\",\"1- V, 2- F, 3- V, 4- F.\",\"1- F, 2- F, 3- V, 4- V.\"],3,\n\"1 é verdadeira: radicais livres causam peroxidação dos lipídios das membranas. 2 é falsa: eles formam adutos que LESAM o DNA, não ajudam no reparo. 3 é verdadeira: o óxido nítrico, produzido por endotélio e macrófagos, é um radical livre. 4 é falsa: proteínas mal dobradas se acumulam, causam estresse do retículo e podem levar à apoptose.\"],\n[\"n01\",\"provas\",\"Prova Metropolitana 2, discursiva (item 1, valor 2,2)\",\n\"<p>O processo de apoptose pode ser dividido em uma fase de iniciação, durante a qual algumas caspases se tornam cataliticamente ativas, e uma fase de execução, durante a qual outras caspases iniciam a degradação de componentes celulares críticos. A ativação das caspases depende de um equilíbrio de sintonia fina entre a produção de proteínas pró-apoptóticas e antipoptóticas.</p><p>a) Como ocorre a ativação da via intrínseca e da via extrínseca da apoptose?<br>b) Quais são os principais genes pró-apoptóticos?<br>c) Quais são as caspases executoras da apoptose?</p>\",[],-1,\"\"],\n\n/* ================= PROVA FIMCA 3 ================= */\n[\"j01\",\"provas\",F3+\"01\",\"Joana, 38 anos, realizou cirurgia estética para colocação de prótese, porém precisou retirar após 1 ano, pois fora informada que havia problema naquele lote de próteses. Observou-se pseudocápsula fibrosa, com formação de granulomas com células gigantes multinucleadas e presença de material refringente em seu interior.<br><br>Qual das opções melhor caracterizam o quadro clínico acima descrito?\",\n[\"Processo inflamatório crônico inespecífico agudizado.\",\"Processo inflamatório crônico com granulomas imunes.\",\"Processo inflamatório crônico com granulomas não imunes.\",\"Processo inflamatório agudo.\",\"Processo inflamatório hiperagudo.\"],2,\n\"Material estranho inerte (o material refringente da prótese) induz granulomas de corpo estranho: macrófagos e células gigantes englobando o material, sem resposta imune específica de linfócitos T. Por isso “granulomas não imunes”. A pseudocápsula fibrosa é a reação crônica ao redor do implante.\"],\n[\"j02\",\"provas\",F3+\"02\",\"1. O principal objetivo da inflamação aguda é neutralizar e remover agentes agresssores,<br><b>PORQUE</b><br>2. a falta de oxigênio e nutrientes teciduais retardam o processo de reparo tecidual.<br><br>Podemos afirmar que:\",\nASSERT.slice(),1,\n\"A 1 é verdadeira: a inflamação aguda existe para neutralizar e remover o agressor. A 2 também é verdadeira: sem oxigênio e nutrientes o reparo fica mais lento. Mas uma não explica a outra: o objetivo da inflamação não decorre da falta de oxigênio.\"],\n[\"j03\",\"provas\",F3+\"03\",\"1. Necrose coagulativa é o tipo mais comum de necrose, caracterizado pela perda da integridade da célula, coagulação das proteínas citoplasmáticas e presença de sombras celulares à microscopia. Geralmente é causada por isquemia.<br>2. Necrose liquefativa ocorre quando as células mortas são rapidamente degradadas por enzimas lisossômicas e outros componentes do sistema imunológico, resultando numa massa líquida ou purulenta. Sendo comum por infecções bacterianas ou fúngicas e abscessos cerebrais.<br>3. Necrose gordurosa ocorre quando os ácidos graxos são liberados e após a morte celular reagem com sais de cálcio, caracterizando a calcificação metastática. É comum em tecido adiposo como mama e peritônio.<br><br>Assinale a opção que demonstra a correspondência correta, sendo (F) para afirmativa falsa e (V) para a afirmativa verdadeira.\",\n[\"1- F, 2- V, 3- V.\",\"1- V, 2- V, 3- V.\",\"1- V, 2- V, 3- F.\",\"1- V, 2- F, 3- F.\",\"1- F, 2- F, 3- V.\"],2,\n\"1 é verdadeira: a necrose de coagulação é a mais comum (isquemia) e mostra as “sombras” das células. 2 é verdadeira: a liquefativa digere as células em massa líquida ou purulenta (abscessos, infecções, cérebro). 3 é falsa: na necrose gordurosa, o cálcio que se deposita no tecido morto é calcificação DISTRÓFICA, não metastática.\"],\n[\"j04\",\"provas\",F3+\"04\",\"Gabriela, 15 anos, refere ter ido à manicure, que durante o procedimento lesou a cutícula próximo a uma das unhas e houve saída de sangue no momento. No dia seguinte notou dor, vermelhidão local, diminuição da mobilidade e saída de pus, que após cinco dias de evolução houve resolução do quadro.<br><br>Qual das seguintes opções demonstra a sequência correta dos 5 erres que ocorrem na inflamação.\",\n[\"Reconhecimento, resposta inflamatória, reparo, recuperação e regeneração.\",\"Reconhecimento, reparo, recuperação, revascularização e remoção.\",\"Reconhecimento, resposta inflamatória, reação, recuperação e regeneração.\",\"Reconhecimeno, resposta inflamatória, remoção, reparo e recuperação.\",\"Reconhecimento, resposta inflamatória, revascularização, regeneração e recuperação.\"],3,\n\"O professor usou a sequência: reconhecimento do agressor, resposta inflamatória (chegada dos leucócitos), remoção do agente, reparo e recuperação. Nas edições mais novas do Robbins, os “5 R” são reconhecimento, recrutamento, remoção, regulação e resolução (reparo). A alternativa d é a única que segue essa lógica.\"],\n[\"j05\",\"provas\",F3+\"05\",\"Jacira, 45 anos, refere litíase (cálculo) em vesícula biliar diagnosticada há 10 anos, porém ainda não teve coragem de fazer a cirurgia, pois tem poucos sintomas.<br><br>Qual das seguintes opções apresenta possíveis achados morfológicos nessa vesícula.\",\n[\"Processo inflamatório crônico inespecífico com linfócitos, fibrose e destruição tecidual.\",\"Processo inflamatório crônico granulomatoso com necrose gangrenosa.\",\"Processo inflamatório agudo rico em neutrófilos.\",\"Processo inflamatório agudo rico em eosinófilos.\",\"Processo inflamatório agudo com formação de abscessos.\"],0,\n\"Cálculo na vesícula há 10 anos, com poucos sintomas, é colecistite crônica: a agressão repetida e prolongada leva a infiltrado de linfócitos (inflamação crônica inespecífica), fibrose da parede e destruição tecidual.\"],\n[\"j06\",\"provas\",F3+\"06\",\"<span class=\\\"ctx\\\">Caso do item 04: Gabriela, 15 anos, lesão da cutícula na manicure, com dor, vermelhidão, pus e resolução em cinco dias.</span><br>Considerando um caso clássico de inflamação aguda, como o de Gabriela, acima descrito,<br><br>qual das seguintes afirmações é correta sobre a inflamação aguda?\",\n[\"A inflamação aguda é uma resposta do sistema imunológico às infecções bacterianas, virais, auto-imunes, isquêmicas e apoptóticas.\",\"Os sinais clínicos da inflamação aguda incluem de e perda de função permanente do órgão afetado.\",\"A inflamação aguda é um processo silencioso que não apresenta sintomas clínicos.\",\"A inflamação aguda é uma resposta do sistema imunológico a estímulos crônicos.\",\"A vasodilatação, aumento da permeabilidade vascular e exsudação de líquidos, células e proteínas plasmáticas para o meio extravascular são característicos da inflamação aguda.\"],4,\n\"Os eventos centrais da inflamação aguda são vasculares: vasodilatação, aumento da permeabilidade e saída (exsudação) de líquido, proteínas e células (principalmente neutrófilos) para o tecido.\"],\n[\"k07\",\"provas\",\"Prova FIMCA 3, discursiva (item 07, valor 2,25)\",\n\"<p>Na hiperplasia linfoide folicular é possível observar os macrófagos de corpos tingíveis, que são macrófagos repletos de corpos apoptóticos, nos centros germinativos de linfonodos de padrão reacional.</p><p>Baseado nessas informações responda as questões:<br>a) Sintetize com suas palavras os principais eventos que ocorrem durante a ativação da via extrínseca da apoptose.<br>b) Sintetize com suas palavras os principais eventos que ocorrem durante a ativação da via intrínseca da apoptose.</p>\",[],-1,\"\"],\n[\"k08\",\"provas\",\"Prova FIMCA 3, discursiva (item 08, valor 2,25)\",\n\"<p>Rafael, 53 anos, com histórico de tuberculose pulmonar, febre, tosse com expectoração purulenta e dispneia. A radiografia de tórax revela um padrão de infiltrado com cavitação pulmonar. Foi submetido a biópsia pulmonar para pesquisa de bacilos álcool ácido resistentes.</p><p>Baseado no caso clínico e em seus conhecimentos responda:<br>a) Descreva os achados morfológicos microscópicos clássicos de uma biópsia de tuberculose pulmonar.<br>b) Quais são as diferenças entre granuloma e tecido de granulação?</p>\",[],-1,\"\"],\n\n/* ================= PROVA FIMCA 4A ================= */\n[\"r01\",\"provas\",F4A+\"01\",\"Renato, 16 anos, previamente hígido (saudável), estava em uma pescaria quando iniciou quadro de dor intensa em fossa ilíaca direita, voltou a cidade com temperatura de 38,5ºC, náusea e dois episódios de vômitos.<br><br>Qual é o diagnóstico mais provável e processo patológico associado:\",\n[\"Prostatite aguda e processo inflamatório granulomatoso.\",\"Colecistite crônica calculosa e processo inflamatório granulomatoso tipo corpo estranho.\",\"Apendicite aguda e processo inflamatório supurativo.\",\"Dermatite aguda e processo inflamatório gangrenoso.\",\"Distrofia muscular e processo inflamatório agudo.\"],2,\n\"Dor em fossa ilíaca direita, febre, náuseas e vômitos num jovem = apendicite aguda. A apendicite é o exemplo clássico de inflamação aguda supurativa (purulenta), rica em neutrófilos, que pode evoluir com abscesso ou perfuração.\"],\n[\"r02\",\"provas\",F4A+\"02\",\"Manuela, 28 anos realizou exame preventivo colpocitológico, resultando amostra celular com presença de células escamosas, glandulares e metaplásicas. Processo inflamatório e negatividade para malignidade.<br><br>Baseado nesse caso, o que é possível afirmar?\",\n[\"A metaplasia escamosa que ocorre no colo de útero é uma adaptação celular comum e esperada em mulheres com vida sexual ativa.\",\"A presença de células metaplásicas favorece o surgimento de adenocarcinomas da região endocervical do colo uterino.\",\"As células escamosas fazem parte do epitélio pavimentoso estratificado da região endocervical do colo de útero com inflamação aguda.\",\"O processo inflamatório gerado pelo HPV leva a processos adaptativos como a metaplasia glandular do colo de útero.\",\"O esfregaço cervical com células metaplásicas sugere lesão pré-neoplásica causada pela infecção do vírus HPV.\"],0,\n\"No colo do útero, o epitélio glandular exposto é substituído por epitélio escamoso: é a metaplasia escamosa da zona de transformação, uma adaptação comum e esperada. O laudo negativo para malignidade mostra que não há lesão pré-neoplásica.\"],\n[\"r03\",\"provas\",F4A+\"03\",\"Solange, 44 anos, moradora de rua, vem acompanhando no ambulatório para tratamento de tuberculose miliar. Na biópsia pulmonar pode-se observar numerosos granulomas com centro de necrose caseosa e halos linfocitários.<br><br>Dentre os mecanismos de lesão celular podemos citar os seguintes eventos.\",\n[\"Depleção de ATP, danos e disfunções mitocondriais e calcificação metastática.\",\"Depleção de ATP, Acúmulo de radicais livres e atrofia celular.\",\"Depleção de ATP, bloqueio apoptótico e acúmulo de radicais livres.\",\"Influxo de cálcio, defeitos na permeabilidade da membrana e esteatose.\",\"Danos e disfunções mitocondriais, influxo de cálcio e acúmulo de radicais livres.\"],4,\n\"Os principais mecanismos bioquímicos da lesão celular são: depleção de ATP, dano mitocondrial, influxo de cálcio, acúmulo de radicais livres, defeitos na permeabilidade das membranas e dano ao DNA e às proteínas. Só a alternativa e traz apenas mecanismos de lesão.\"],\n[\"s01\",\"provas\",\"Prova FIMCA 4A, discursiva (item 01, valor 2,5)\",\n\"<p>Solange, 44 anos, moradora de rua, vem acompanhando no ambulatório para tratamento de tuberculose miliar. Na biópsia pulmonar pode-se observar numerosos granulomas com centro de necrose caseosa e halos linfocitários.</p><p>Baseado no caso clínico responda o que se pede:<br>a) O que é um granuloma e quais suas funções.<br>b) Descreva as vias de ativação e funções das diferentes populações macrofágicas.</p>\",[],-1,\"\"],\n[\"s02\",\"provas\",\"Prova FIMCA 4A, discursiva (item 02, valor 2,25)\",\n\"<p>Luciana, 36 anos, G1A0P1, em fase de puerpério está no quinto dia pós-cirúrgico de cesária e ooforectomia direita, que foram realizadas com sucesso. Ao exame físico, nota-se ferida cirúrgica com discreta secreção serosa clara, mínima hiperemia e dor local.</p><p>Baseado no caso e em seus conhecimentos prévios, responda as seguintes questões.<br>a) Cite e descreva a função de três mediadores químicos do processo inflamatório.<br>b) Descreva objetivamente todas as fases evolutivas do reparo tecidual.</p>\",[],-1,\"\"],\n\n/* ================= PROVA FIMCA 4B ================= */\n[\"t01\",\"provas\",F4B+\"01\",\"Gabriel, recém nascido a termo, apresenta febre e tosse produtiva há cinco dias. Ao exame físico apresentou estertores crepitantes em base esquerda. Ao raio X notou-se broncograma aéreo, sendo diagnosticado pneumonia bacteriana em base pulmonar esquerda.<br><br>Quais achados e processo patológico associados:\",\n[\"Neutrófilos intra-alveolares com formação de abscessos e processo inflamatório agudo.\",\"Neutrófilos intersticiais, membrana hialina e perda da tolerância imunológica periférica.\",\"Neutrófilos e linfócitos peribrônquicos e processo inflamatório granulomatoso.\",\"Neutrófilos, linfócitos e macrófagos intra-alveolares e processo inflamatório crônico.\",\"Linfócitos e plasmócitos intersticiais e perda da tolerância imunológica central.\"],0,\n\"Pneumonia bacteriana é inflamação aguda supurativa: os alvéolos se enchem de exsudato rico em neutrófilos (daí o broncograma aéreo e os estertores), podendo formar abscessos.\"],\n[\"t02\",\"provas\",F4B+\"02\",\"Melissa, 22 anos, G2A1P1, 34 semanas de gestação, faz pré-natal e refere fazer uso contínuo de medicação pois tem hipertensão arterial sistêmica.<br><br>Sobre as adaptações celulares envolvidas nesse caso, assinale a melhor alternativa.\",\n[\"O tecido mamário por ser constituído por glândulas, apresentam metaplasia, hipertrofia e hiperplasia decorrentes do processo gestacional.\",\"O músculo estriado cardíaco dessa paciente apresenta atrofia e autofagia decorrente do aumento metabólico durante a gravidez.\",\"O músculo liso do corpo uterino bem como o endométrio apresentam hipertrofia e hiperplasia durante a gestação.\",\"O endométrio apresenta proliferação celular com hipertrofia e hiperplasia glandular, seguidas de apoptose maciça durante o processo gestacional.\",\"A cardiomiopatia hipertensiva é responsável pelo processo hiperplásico do músculo estriado cardíaco.\"],2,\n\"Na gestação, os hormônios causam hipertrofia e hiperplasia das células musculares lisas do útero e também do endométrio. É o exemplo clássico de hipertrofia + hiperplasia fisiológicas.\"],\n[\"t03\",\"provas\",F4B+\"03\",\"Durante o processo normal da embriogênese são necessários que ocorram uma sequência de eventos que culminem com apoptoses celulares em locais específicos.<br><br>Quais dos seguintes eventos culminam com a apoptose?\",\n[\"Depleção de ATP, danos e disfunções mitocondriais e a multiplicação das células tronco de tecidos permanentes.\",\"Acúmulo de radicais livres, autofagia e ativação das moléculas BCL-2 e BCL-XL.\",\"Depleção de ATP, bloqueio pró-apoptótico e acúmulo de radicais livres.\",\"Influxo de cálcio, defeitos na permeabilidade da membrana e ativação do sistema complemento.\",\"Ativação das proteínas Bax e Bak, expressão das moléculas Faz.\"],4,\n\"Na embriogênese a apoptose é programada. Pela via intrínseca, BAX e BAK são ativadas e abrem a mitocôndria; pela via extrínseca, o receptor Fas (a prova escreveu “Faz”) ligado ao seu ligante dispara a caspase-8. Só a alternativa e traz eventos que levam à apoptose.\"],\n[\"u01\",\"provas\",\"Prova FIMCA 4B, discursiva (item 01, valor 2,5)\",\n\"<p>Solange, 44 anos, moradora de rua, vem acompanhando no ambulatório para tratamento de tuberculose miliar. Na biópsia pulmonar pode-se observar numerosos granulomas com centro de necrose caseosa e halos linfocitários.</p><p>Responda o que se pede:<br>a) Descreva três diferenças entre inflamação aguda e inflamação crônica.<br>b) Descreva duas diferenças entre apoptose e necrose.</p>\",[],-1,\"\"],\n[\"u02\",\"provas\",\"Prova FIMCA 4B, discursiva (item 02, valor 2,25)\",\n\"<p>Madalena, 58 anos, realizou colectomia a direita há dois meses, porém relada dor e enrijecimento em parede abdominal a direita, ao realizar exame de USG abdominal nota-se acúmulo de líquido intracavitário. É realizada nova abertura com inventário da cavidade onde localiza-se restos de gaze parcialmente encapsulados.</p><p>Baseado no caso e em seus conhecimentos prévios, responda as seguintes questões.<br>a) A pseudocápsula que revestia a gaze foi enviada para exame histopatológico, quais as alterações histopatológicas poderiam ser observadas?<br>b) Quais são as diferenças entre granuloma e tecido de granulação?</p>\",[],-1,\"\"]\n\n];\n\n/* =========================================================\n   POR QUE CADA ALTERNATIVA ESTÁ ERRADA + MACETE\n   EXTRA[id] = [[motivo por alternativa (null na correta)], \"macete\"]\n   ========================================================= */\nconst EXTRA = {\na01:[[\"Hiperplasia é aumento do NÚMERO de células. Cardiomiócitos adultos praticamente não se dividem, então não conseguem responder assim.\",null,\"Atrofia é o oposto: a célula diminui, por menos demanda ou menos estímulo.\",\"Metaplasia é a troca de um tipo celular por outro. O miocárdio continua sendo miocárdio.\"],\n\"Célula que não divide só pode crescer: coração e músculo esquelético respondem à sobrecarga com hipertrofia. Pense: “quem não multiplica, engorda”.\"],\na02:[[\"Displasia é crescimento desordenado com atipia (núcleos alterados, perda da organização). Aqui um epitélio normal só foi trocado por outro normal.\",\"Hiperplasia aumentaria o número das mesmas células colunares, sem mudar o tipo de epitélio.\",\"Atrofia reduziria o tamanho das células, sem trocar o tipo.\",null],\n\"METAplasia = METAmorfose do tecido: um epitélio adulto e normal vira outro, mais resistente. No fumante, o brônquio “veste uma armadura” de epitélio escamoso.\"],\na03:[[null,\"Mistura as etapas: a quimiotaxia acontece depois da transmigração, e a fagocitose é o fim do processo, não vem antes da adesão.\",\"Vasodilatação, estase e edema são eventos vasculares, não celulares. E apoptose não faz parte do recrutamento.\",\"São as etapas certas, mas na ordem de trás para frente.\"],\n\"Pense num carro entrando num estacionamento: encosta na lateral (marginação), anda devagar (rolamento), estaciona (adesão) e o motorista sai (transmigração). Sigla M-R-A-T.\"],\na04:[[\"IFN-γ é citocina de linfócitos T e NK que ativa macrófagos. Age em horas a dias, não em segundos.\",null,\"LTB4 é principalmente quimiotático para neutrófilos. Os leucotrienos que aumentam a permeabilidade são C4, D4 e E4.\",\"TNF precisa ser sintetizado, então age mais tarde, ativando endotélio e leucócitos.\"],\n\"Imediato = pré-formado. A histamina já está “engatilhada” nos grânulos do mastócito: basta degranular. A vermelhidão da picada de inseto em segundos é histamina.\"],\na05:[[\"Atrofia é adaptação celular (redução de tamanho), sem agregados de macrófagos.\",\"A supurativa é aguda, dominada por neutrófilos e pus, não por macrófagos epitelioides.\",null,\"Regeneração é reposição de células do mesmo tipo. Granuloma é inflamação, não reparo.\"],\n\"Granuloma é a “muralha” que o corpo constrói quando não consegue eliminar o agressor. Se precisou construir muralha, é porque a briga é longa: crônica.\"],\na06:[[\"Transudato é pobre em proteínas e células e sai de vasos íntegros por desequilíbrio de pressões.\",\"Linfedema é edema por obstrução da drenagem linfática, não por aumento da permeabilidade.\",\"Edema hidrostático vem do aumento de pressão (ex.: insuficiência cardíaca) com o vaso íntegro, e o líquido é transudato.\",null],\n\"EXsudato: EXtravasa tudo (proteína e célula) porque o vaso “furou”. TRANSudato: só o líquido atravessa um vaso íntegro.\"],\na07:[[\"IL-4 (com IL-13) faz a ativação alternativa (M2), voltada para reparo.\",\"IL-8 é quimiocina que atrai neutrófilos. Não ativa macrófagos.\",null,\"IL-10 é anti-inflamatória: desliga macrófagos.\"],\n\"IFN-Gama é o Gatilho do macrófago matador (M1). Macrófago ativado por IFN-γ vira a célula epitelioide do granuloma.\"],\na08:[[\"Adesão firme é função das integrinas (LFA-1, VLA-4) ligando ICAM-1 e VCAM-1.\",null,\"A diapedese (transmigração) depende principalmente da PECAM-1 (CD31).\",\"A fagocitose acontece no tecido, por receptores de opsoninas e de padrões microbianos.\"],\n\"Selectina “seleciona e solta”: liga fraco, pega e solta, pega e solta, e o leucócito rola. Integrina “integra” firme, e ele para.\"],\na09:[[\"Metaplasia é resposta a irritação crônica, trocando o tipo celular. Não é causada por falta de nutrientes.\",\"Hiperplasia responde a AUMENTO de estímulo (hormônios, fatores de crescimento).\",null,\"Necrose é morte celular, não adaptação.\"],\n\"Atrofia é “modo economia”: faltou comida, sangue, uso, nervo ou hormônio, a célula encolhe para sobreviver.\"],\na10:[[\"A lectina de ligação à manose inicia só a via das lectinas.\",\"C1q inicia só a via clássica, ligando anticorpos (IgG, IgM).\",null,\"O fator B participa só da via alternativa.\"],\n\"As três vias são estradas diferentes que chegam na mesma praça: C3. De lá saem C3b (opsoniza), C3a e C5a (inflamam) e o MAC (lisa).\"],\n\nb01:[[\"O “apenas” derruba: além de crescer, as células musculares lisas também se multiplicam.\",\"O aumento é do miométrio (músculo), não só do endométrio, e envolve também hipertrofia.\",null,\"Metaplasia não explica aumento de volume. O útero cresce por adaptação do músculo.\"],\n\"Músculo liso consegue dividir E crescer, então usa as duas armas. Em prova, desconfie de alternativas com “apenas”.\"],\nb02:[[\"Na atrofia a síntese de proteínas diminui.\",\"A autofagia aumenta na atrofia (a célula recicla partes de si).\",null,\"Substituição por gordura pode ocorrer no órgão, mas não é metaplasia nem o mecanismo celular da atrofia.\"],\n\"Ubiquitina é a “etiqueta de lixo”: a proteína marcada vai para o proteassoma, o “triturador”. Atrofia = menos fabricação + mais trituração.\"],\nb03:[[\"Célula já diferenciada não muda de tipo. Esse é o erro clássico que a questão quer pegar.\",null,\"Divisão descontrolada é característica de neoplasia. A metaplasia é reversível.\",\"Não há morte programada seguida de regeneração: a troca vem da diferenciação diferente das células-tronco.\"],\n\"Metaplasia não é a célula madura trocando de roupa. É a fábrica (célula-tronco) que muda o molde.\"],\nb04:[[\"Hiperplasia não evolui para necrose. São processos diferentes.\",null,\"Hiperplasia é reversível: tirou o estímulo, ela regride. Isso a diferencia da neoplasia.\",\"O tecido hiperplásico em geral mantém ou aumenta a função.\"],\n\"Hiperplasia patológica é “reversível, mas perigosa”: cada divisão a mais é uma chance de mutação. Ex.: hiperplasia endometrial → carcinoma de endométrio.\"],\nb05:[[\"Mitocôndrias não são o local de metabolização de barbitúricos.\",\"O RER sintetiza proteínas para exportação, não destoxifica fármacos.\",null,\"Lisossomos fazem digestão intracelular, não metabolizam fármacos.\"],\n\"REL = Retículo da Eliminação de drogas (citocromo P-450). Mais droga, mais REL, e mais tolerância ao remédio.\"],\nb06:[[\"A falta de vitamina A não apenas reduz as células: ela muda o tipo de epitélio.\",\"Não há aumento de glândulas. Ao contrário, perde-se o epitélio secretor.\",null,\"Displasia não é consequência direta da deficiência. A resposta é adaptativa (metaplasia).\"],\n\"Vitamina A mantém o epitélio “especializado” (secretor, ciliado). Sem ela, o epitélio “simplifica” para escamoso. No olho, isso causa a xeroftalmia.\"],\nb07:[[\"Hemossiderina vem do ferro (hemorragia, sobrecarga de ferro), não do desgaste celular.\",null,\"Melanina é pigmento de melanócitos, não de cardiomiócitos.\",\"Bilirrubina causa icterícia, não pigmento perinuclear em células atróficas.\"],\n\"Lipofuscina = pigmento “da idade”: Lipo (gordura oxidada) + fusc (escuro). Coração pequeno e marrom = atrofia parda.\"],\nb08:[[\"Esteroides não são o principal estímulo da regeneração hepática.\",null,\"Isquemia não estimula proliferação, ela causa lesão.\",\"Colágeno é produto da fibrose, não estímulo para hiperplasia.\"],\n\"HGF = Hepatocyte Growth Factor, o nome já entrega. A IL-6 “acorda” o hepatócito (tira de G0) e o HGF manda ele dividir.\"],\nb09:[[\"Ingerir material de fora é fagocitose (heterofagia).\",null,\"A célula não expulsa organelas para o exsudato. Ela as digere internamente.\",\"Autofagia é mecanismo de sobrevivência, não morte por inflamação.\"],\n\"AUTO-fagia = comer a si mesmo. Em jejum, a célula recicla peças velhas para sobreviver.\"],\nb10:[[null,\"Receptores acoplados à proteína G predominam na hipertrofia patológica (angiotensina, endotelina, catecolaminas).\",\"Caspase 3 é executora da apoptose, não de crescimento.\",\"NF-κB é fator de transcrição ligado principalmente à inflamação.\"],\n\"Atleta = “AKT-leta”: exercício → IGF-1 → PI3K/AKT (hipertrofia boa). Doença, como a hipertensão → proteína G (hipertrofia ruim).\"],\nb11:[[null,\"A vasodilatação vem depois, e não é permanente.\",\"Na inflamação o que sobe é a pressão osmótica do interstício, pela saída de proteínas. Não é o primeiro evento.\",\"Trombos não são o primeiro evento da inflamação aguda.\"],\n\"Primeiro o susto (contrai), depois a festa (dilata). A constrição dura só segundos.\"],\nb12:[[\"Lesão endotelial direta acontece em agressões graves (queimaduras, toxinas). Não é o mais comum.\",null,\"Transcitose aumentada existe (ex.: estímulo por VEGF), mas é mecanismo secundário.\",\"Vasos novos vazam, mas isso é típico do reparo, não do extravasamento agudo.\"],\n\"As células endoteliais “encolhem os ombros” (contraem) e abrem frestas. É rápido, dura 15 a 30 minutos e é típico da histamina.\"],\nb13:[[\"L-selectina fica no leucócito (L de leucócito) e participa do rolamento.\",null,\"Sialil-Lewis X é o ligante das selectinas no leucócito: também rolamento.\",\"PECAM-1 (CD31) atua na transmigração.\"],\n\"TNF e IL-1 “acendem” o endotélio, que passa a expor ICAM-1 e VCAM-1: são as mãos que seguram a integrina do leucócito.\"],\nb14:[[null,\"Pressão hidrostática move líquido, não orienta leucócitos.\",\"pH baixo não é o sinal que direciona a migração.\",\"A estase ajuda a marginação, mas não dá direção ao leucócito no tecido.\"],\n\"Quimio-taxia = movimento guiado pela química. O leucócito “segue o cheiro” do mais fraco para o mais forte: C5a, LTB4, IL-8 e produtos bacterianos.\"],\nb15:[[\"O NO vem da iNOS, principalmente em macrófagos. O burst oxidativo gera ERO.\",null,\"Histamina é de mastócitos, não produto do burst.\",\"A PCR é produzida pelo fígado.\"],\n\"Burst = explosão de oxigênio: a NADPH oxidase joga elétrons no O₂ e forma superóxido. Sem essa enzima: doença granulomatosa crônica (infecções de repetição).\"],\nb16:[[\"Neutrófilos e pus definem a inflamação supurativa (purulenta).\",null,\"A serosa é leve e costuma resolver, sem cicatriz.\",\"Necrose caseosa é da tuberculose (granulomatosa).\"],\n\"Serosa = “soro”: líquido claro e ralo. Bolha de queimadura é o exemplo clássico.\"],\nb17:[[\"A bradicinina é vasodilatadora: causa hipotensão, não hipertensão.\",null,\"Ela não inibe a quimiotaxia.\",\"Ela não é enzima de matriz.\"],\n\"BradiCINina = DOR. Na clínica: o IECA impede a quebra da bradicinina e por isso causa tosse e angioedema.\"],\nb18:[[\"NETs não são citocinas. São estruturas físicas feitas de DNA.\",null,\"Complexos antígeno-anticorpo são outra coisa (hipersensibilidade tipo III).\",\"Não são membranas mitocondriais.\"],\n\"NET = rede de pesca: fios de cromatina com “iscas” antimicrobianas dos grânulos. O neutrófilo morre ao lançar a rede.\"],\nb19:[[\"A albumina CAI na inflamação (proteína de fase aguda negativa).\",null,\"Hemoglobina não é proteína de fase aguda.\",\"Troponina é marcador de lesão do miocárdio.\"],\n\"Inflamou, a IL-6 manda o fígado fazer PCR. O fibrinogênio também sobe, e é por isso que o VHS aumenta.\"],\nb20:[[\"Leucotrienos são pró-inflamatórios.\",\"Tromboxano é pró-agregante e vasoconstritor.\",null,\"PGE2 é pró-inflamatória (dor, febre, vasodilatação).\"],\n\"LipOXINAS dão o “X” final na inflamação: mandam os neutrófilos pararem de chegar. Guarde: lipoxinas = resolução.\"],\nb21:[[\"Macrófagos predominam depois, a partir de 24 a 48 horas.\",\"Linfócitos marcam inflamação crônica ou viral.\",null,\"Plasmócitos são da inflamação crônica.\"],\n\"Neutrófilo é o bombeiro: primeiro a chegar e vive pouco. Macrófago é o faxineiro que chega depois e fica.\"],\nb22:[[\"Fibrina é da inflamação fibrinosa, e monócitos não são o principal componente do pus.\",null,\"Líquido aquoso pobre em proteína é o da inflamação serosa.\",\"Hemácias predominariam num exsudato hemorrágico.\"],\n\"Pus = neutrófilo + lixo + bactéria. Piogênico = “gera pus”, como o estafilococo.\"],\nb23:[[\"Coleção de pus em espaço fechado é abscesso.\",null,\"Excesso de fluido no interstício é edema.\",\"Substituição do parênquima por colágeno é fibrose.\"],\n\"Úlcera = buraco na superfície (pele, mucosa). Abscesso = bolsa de pus fechada.\"],\nb24:[[null,\"A catalase degrada H₂O₂, ou seja, faz o contrário.\",\"A elastase é protease que degrada proteínas e tecido, sem usar cloreto.\",\"A colagenase degrada colágeno da matriz.\"],\n\"MPO + Cl⁻ + H₂O₂ = HOCl, a “água sanitária” do neutrófilo.\"],\nb25:[[\"O fígado produz proteínas de fase aguda, mas não regula a temperatura.\",null,\"A medula produz leucócitos (leucocitose), não a febre.\",\"O córtex adrenal produz cortisol, que é anti-inflamatório.\"],\n\"Hipotálamo = termostato. A PGE₂ “sobe o termostato”. Por isso aspirina e dipirona baixam a febre.\"],\nb26:[[\"Neutrófilos e edema intenso descrevem a inflamação aguda.\",null,\"Congestão e calor são sinais vasculares da aguda.\",\"Resolução rápida é desfecho da aguda.\"],\n\"Crônica = três coisas ao mesmo tempo: mononucleares, destruição e reparo. “Briga, estraga e conserta junto”.\"],\nb27:[[\"IL-4 e IL-13 fazem a ativação alternativa (M2).\",null,\"Glicocorticoides inibem os macrófagos.\",\"Vitamina D não é o ativador clássico.\"],\n\"M1 = Mata (endotoxina + IFN-γ). M2 = Monta de novo, ou seja, repara (IL-4, IL-13).\"],\nb28:[[\"Matar microrganismos é função do M1.\",null,\"Apresentar antígenos não é “apenas para células B”, nem é a função principal do M2.\",\"NO em grande quantidade é produto do M1.\"],\n\"M1 = Mata. M2 = Monta de novo: reparo, fibrose, angiogênese e controle da inflamação.\"],\nb29:[[\"Neutrófilos não se fundem em células gigantes.\",null,\"Linfócitos B viram plasmócitos, não células gigantes.\",\"Fibroblastos produzem colágeno e não se fundem.\"],\n\"Célula gigante = vários macrófagos “dando as mãos” (fusão) para englobar algo grande. Langhans tem os núcleos em ferradura na borda.\"],\nb30:[[\"A sarcoidose tem granulomas NÃO caseosos.\",null,\"O granuloma de corpo estranho não tem necrose caseosa: tem o material estranho no centro.\",\"A doença de Crohn tem granulomas não caseosos.\"],\n\"Caseosa = queijo = tuberculose (também alguns fungos). “A tuberculose come queijo”.\"],\nb31:[[\"Th1 (IFN-γ) ativa macrófagos contra microrganismos intracelulares.\",\"Th2 (IL-4, IL-5, IL-13) atua contra helmintos e na alergia, recrutando eosinófilos.\",null,\"T reguladores suprimem a resposta imune.\"],\n\"Th1 → macrófago. Th2 → eosinófilo. Th17 → neutrófilo. “O 17 chama o exército de neutrófilos”.\"],\nb32:[[\"Acúmulo de glicogênio é depósito intracelular (ex.: glicogenoses).\",null,\"Proteínas de choque térmico são chaperonas dentro da célula.\",\"Amiloide é depósito de proteína mal dobrada (amiloidose), não fibrose.\"],\n\"Fibrose = cicatriz de colágeno. O maestro é o TGF-β, que manda o fibroblasto produzir matriz.\"],\nb33:[[\"O granuloma de corpo estranho não tem necrose caseosa.\",null,\"Ele é formado por macrófagos e células gigantes, não só por linfócitos.\",\"É causado por material inerte, não pela tuberculose.\"],\n\"Corpo estranho = macrófago sem imunologia: o corpo não “reconhece” o fio de sutura, só tenta englobá-lo.\"],\nb34:[[\"Granuloma piogênico é uma lesão vascular proliferativa. O nome engana: não é granuloma nem tem pus.\",null,\"Abscesso frio é uma coleção sem sinais inflamatórios agudos, típica da tuberculose.\",\"Foco de Ghon é a lesão da tuberculose primária no pulmão.\"],\n\"Terciário = terceiro tipo de órgão linfoide (depois dos primários e secundários): o tecido inflamado cria seu próprio “linfonodo”.\"],\nb35:[[\"IL-12 induz resposta Th1, não fibroblastos.\",null,\"Histamina é mediador vascular agudo.\",\"Heparina é anticoagulante liberado por mastócitos.\"],\n\"PDGF: “Puxa e Divide Fibroblastos”. Atrai e multiplica.\"],\nb36:[[null,\"IgE se liga a mastócitos (alergia). Histamina é mediador vascular.\",\"Leucotrienos e prostaglandinas são mediadores lipídicos, não opsoninas.\",\"Fibrinogênio e albumina não são as opsoninas principais.\"],\n\"Opsonina é o “tempero” que deixa o micróbio apetitoso para o fagócito. As principais: IgG e C3b.\"],\nb37:[[\"Monócitos predominam na crônica em geral, não na alergia e na parasitose.\",null,\"Neutrófilos predominam nas infecções bacterianas agudas.\",\"Basófilos participam, mas são poucos, e o “apenas” invalida.\"],\n\"Eosinófilo = alergia e verme. IgE e parasita no enunciado? Pense em eosinófilo.\"],\nb38:[[\"Opsonização é função do C3b.\",\"A lise é feita pelo MAC (C5b-C9).\",null,\"C5a é pró-inflamatório, não inibe a inflamação.\"],\n\"Fragmentos “a” (C3a, C5a) Alarmam: são anafilatoxinas. Fragmento C3b “Bota etiqueta” no micróbio (opsoniza).\"],\nb39:[[\"Leucotrienos vêm da 5-lipoxigenase.\",null,\"Lipoxinas também vêm das lipoxigenases.\",\"ERO vêm da NADPH oxidase.\"],\n\"COX → Prostaglandinas + Tromboxano (a aspirina bloqueia). LOX → Leucotrienos + Lipoxinas: “L com L”.\"],\nb40:[[\"Está correta, mas é só uma das causas.\",\"Está correta, mas é só uma das causas.\",\"Está correta, mas é só uma das causas.\",null],\n\"Causas de inflamação crônica: infecção que persiste, doença imune (autoimune ou alérgica) e agente tóxico prolongado (sílica, lipídios).\"],\nb41:[[\"Fibrose ocorre quando o dano é extenso ou o tecido não consegue regenerar.\",\"Progressão para crônica acontece quando o agente persiste.\",null,\"Abscesso ocorre com bactérias piogênicas não contidas.\"],\n\"Agente eliminado + tecido que regenera = tudo volta ao normal (resolução).\"],\nb42:[[\"É o oposto do que acontece.\",null,\"Contração de arteríolas é vasoconstrição.\",\"Deposição de cálcio na parede é calcificação vascular.\"],\n\"Angio-gênese = nascimento de vasos por brotamento. O motor principal é o VEGF.\"],\nb43:[[null,\"Ácido hipocloroso vem de MPO + H₂O₂ + Cl⁻.\",\"H₂O₂ vem da conversão do superóxido.\",\"A hidroxila vem do H₂O₂ com ferro (reação de Fenton).\"],\n\"NO + superóxido = peroxiNITRITO. Tem “nitro” no nome porque veio do óxido NÍTRICO.\"],\nb44:[[\"Selectinas fazem o rolamento. As quimiocinas ativam integrinas, não selectinas.\",null,\"Caderinas fazem junções entre células.\",\"Mucinas são glicoproteínas do muco.\"],\n\"A quimiocina “aperta o botão” da integrina: de baixa para alta afinidade, e o leucócito freia.\"],\nb45:[[null,\"Infecção viral leve tende a causar inflamação serosa.\",\"Hiperplasia do mesotélio não define o padrão fibrinoso.\",\"A inflamação fibrinosa exige exsudato rico em proteínas.\"],\n\"Fibrinogênio é molécula GRANDE: só sai se o vaso estiver bem lesado. Pericardite fibrinosa dá o atrito pericárdico na ausculta.\"],\nb46:[[\"Na necrose a membrana rompe, o conteúdo vaza e há inflamação.\",null,\"Gangrena é necrose de um membro ou tecido.\",\"Infarto é necrose isquêmica.\"],\n\"Apoptose é a morte “educada”: empacota tudo em corpos apoptóticos e não suja o chão. Necrose explode e inflama.\"],\nb47:[[\"IL-10 é anti-inflamatória.\",null,\"Serotonina é amina vasoativa, sem papel na medula.\",\"Colesterol não estimula a medula óssea.\"],\n\"CSF acelera a “fábrica” da medula, que manda até os “estagiários” (bastões) para o sangue: desvio à esquerda.\"],\nb48:[[\"Epitelioide não é epitélio. É macrófago parecido com epitélio.\",null,\"Não são células-tronco.\",\"Não são células endoteliais.\"],\n\"Epitelioide = “com cara de” epitélio (o sufixo -oide significa parecido). É um macrófago fantasiado.\"],\nb49:[[null,\"Pode ativar complemento, mas o “apenas” deixa errada.\",\"A COX-2 não é ativada pelo fator XII.\",\"Ciclo de Krebs é metabolismo energético.\"],\n\"Fator XII (Hageman) é o “faz-tudo” do plasma: coagulação, cininas (bradicinina) e fibrinólise.\"],\nb50:[[null,\"Colunar para escamoso é o que acontece no brônquio do fumante, o inverso.\",\"Metaplasia óssea ocorre em tecido conjuntivo, não no epitélio do esôfago.\",\"Atrofia não é metaplasia.\"],\n\"Barrett: o esôfago “vira intestino” para aguentar o ácido. Fumante: o brônquio “vira pele”. São caminhos opostos.\"],\n\nc01:[[\"No rim adulto o crescimento compensatório é principalmente por aumento das células, não por proliferação.\",\"Fibroblasto não se transforma em célula tubular.\",null,\"Não é por inibição de autofagia.\"],\n\"Perdeu um rim? O que sobrou “malha”: as células crescem (hipertrofia compensatória).\"],\nc02:[[\"Não há metaplasia nem necrose no ciclo da gestação.\",\"Displasia é alteração pré-neoplásica, não fisiológica.\",null,\"O “apenas” derruba: também há hiperplasia.\"],\n\"Gestação: cresce (hipertrofia + hiperplasia). Parto: encolhe (atrofia com apoptose).\"],\nc03:[[\"Não é obrigatória, e se evoluir tende a carcinoma escamoso, não adenocarcinoma.\",\"Surfactante é produzido pelos pneumócitos tipo II nos alvéolos, não pelo epitélio brônquico.\",null,\"Não é neoplasia e não envolve o tecido conjuntivo.\"],\n\"Metaplasia é uma troca: ganha resistência, perde função. O brônquio aguenta a fumaça, mas perde a “vassoura” (cílios) e o muco.\"],\nc04:[[null,\"Não há constrição permanente: as vênulas ficam mais permeáveis.\",\"Fibronectina é proteína de matriz, não vasodilatadora.\",\"Trombos oclusivos imediatos não são o evento inicial.\"],\n\"Primeiro o susto (contrai), depois a festa (dilata). A constrição dura só segundos.\"],\nc05:[[\"Linfócitos T citotóxicos são de resposta viral ou crônica.\",\"Fibroblastos aparecem no reparo.\",null,\"Eosinófilos são de alergia e parasitose.\"],\n\"Piogênico = gera pus = neutrófilo.\"],\nc06:[[\"A fibrinosa tem fibrina em superfícies como pericárdio e pleura, não pus.\",null,\"A serosa tem líquido ralo. E transudato nem é inflamatório.\",\"Úlcera é defeito na superfície, não coleção fechada.\"],\n\"Abscesso = pus preso numa bolsa. Supurativa = pus.\"],\nc07:[[\"Fibrina não sofre metaplasia.\",\"Fibrina não se transforma em colesterol.\",null,\"Calcificação pode aparecer tardiamente em áreas lesadas, mas não é o destino comum nem imediato.\"],\n\"Pouca fibrina: some (fibrinólise). Muita fibrina: vira cicatriz (organização) e deixa aderências.\"],\nc08:[[\"Proliferação de glândulas não é úlcera.\",null,\"Pseudomembrana é exsudato fibrinoso aderido à superfície (ex.: colite por C. difficile).\",\"Isso descreve um granuloma.\"],\n\"Úlcera = buraco na superfície (pele, mucosa). Abscesso = bolsa de pus fechada.\"],\nc09:[[null,\"Organização deixa cicatriz, não devolve o tecido normal.\",\"Esse desfecho não existe.\",\"Progressão para crônica acontece quando o agente persiste.\"],\n\"Resolução é o “Ctrl+Z” da inflamação: tudo volta como era.\"],\nc10:[[null,\"Eosinófilos e mastócitos podem aparecer, mas o “exclusivamente” deixa errada.\",\"Fibroblastos aparecem no reparo, e osteoclastos não são típicos.\",\"Neutrófilos são a marca da inflamação aguda.\"],\n\"Crônica = LPM: Linfócitos, Plasmócitos e Macrófagos.\"],\nc11:[[\"Necrose fibrinoide isolada é típica de vasculites, não de granuloma.\",null,\"Neutrófilos com exsudato purulento são inflamação supurativa.\",\"Mastócitos e eosinófilos em torno de vasos não formam granuloma.\"],\n\"Granuloma = bolinha de macrófagos epitelioides + células gigantes + coroa de linfócitos.\"],\nc12:[[null,\"Gangrena é necrose de membros por isquemia.\",\"Necrose gordurosa ocorre no pâncreas e na mama.\",\"Necrose liquefativa ocorre em abscessos e no cérebro.\"],\n\"Caseosa = queijo = tuberculose. “A tuberculose come queijo”.\"],\nc13:[[\"O granuloma de corpo estranho não tem necrose caseosa.\",\"O Robbins distingue claramente os dois tipos.\",null,\"Granulomas imunológicos têm células gigantes, e não são feitos de neutrófilos.\"],\n\"Corpo estranho = macrófago sem imunologia (material inerte). Imunológico = macrófago comandado pela célula T (ex.: tuberculose).\"],\nc14:[[\"Prurido e vesículas são sinais de doenças de pele específicas.\",\"Febre e leucocitose são manifestações sistêmicas, não os sinais locais clássicos.\",null,\"Isso descreve choque.\"],\n\"Os quatro de Celsus rimam: rubOR, calOR, tumOR, dOR. Virchow acrescentou a perda de função.\"],\nc15:[[\"Há diferença mensurável: proteínas, densidade e células.\",null,\"O transudato é pobre em células.\",\"Queda da pressão oncótica gera transudato, não exsudato.\"],\n\"EXsudato: EXtravasa tudo (proteína e célula) porque o vaso “furou”. TRANSudato: só o líquido atravessa um vaso íntegro.\"],\nc16:[[\"Sem oxigênio não há aumento de mitocôndrias, e o glicogênio é CONSUMIDO na glicólise anaeróbia.\",null,\"Reparo não é consequência imediata.\",\"Não existe conversão em tecido adiposo.\"],\n\"Sem O₂ = sem ATP. Tudo o que vem depois (edema celular, acidose, queda da síntese de proteínas) é consequência da falta de ATP.\"],\nc18:[[null,\"Há diferença clara de causa e de local.\",\"PTH elevado está ligado à calcificação metastática.\",\"Valvas lesionadas calcificam de forma distrófica.\"],\n\"DIStrófica = tecido DOENTE, cálcio normal. METAstática = tecido normal, cálcio ALTO no sangue que se “espalha”.\"],\nc19:[[\"Necrose caseosa com cavitação descreve tuberculose.\",\"Não há neoplasia.\",null,\"Neutrófilos e liquefação em cavidade fechada descrevem empiema ou abscesso.\"],\n\"Fibrinogênio é molécula grande: só sai com vaso bem lesado. Depois, ou a fibrina some (resolução) ou vira cicatriz com aderências.\"],\nc20:[[\"Músculo não sofre metaplasia escamosa, e há infiltrado inflamatório.\",\"Na úlcera crônica há sinais de reparo, com tecido de granulação.\",null,\"Não há transformação maligna imediata.\"],\n\"Úlcera crônica tem camadas: fundo com neutrófilos, meio com tecido de granulação e borda com inflamação crônica e fibrose.\"],\np06:[[null,\"Coagulativa é a necrose da isquemia em órgãos sólidos (coração, rim, baço), onde o contorno das células se mantém. O cérebro é a exceção.\",\"Caseosa é típica da tuberculose: material branco e friável, como queijo.\",\"Gordurosa ocorre no tecido adiposo, principalmente na pancreatite aguda.\"],\n\"Cérebro isquêmico “derrete”: AVC = liquefativa. Coração isquêmico “coagula”: infarto = coagulativa.\"],\np07:[[null,\"Atrofia é diminuição do tamanho das células, não formação de tecido novo.\",\"Calcificação é depósito de sais de cálcio.\",\"Necrose é morte celular. O tecido descrito está vivo e proliferando.\"],\n\"Granulação = “granulinhos” vermelhos na ferida. Cada grânulo é um capilar novo cercado de fibroblastos.\"],\np08:[[null,\"Distrófica ocorre em tecido lesado ou necrótico, com cálcio sérico normal. Aqui o enunciado diz “sem lesão prévia”.\",\"Necrose é morte celular, não depósito de cálcio em tecido sadio.\",\"Fibrose é deposição de colágeno.\"],\n\"METAstática = tecido normal, cálcio ALTO no sangue. DIStrófica = tecido DOENTE, cálcio normal.\"],\np09:[[\"Regeneração é reposição de células. O cálcio intracelular alto destrói, não repara.\",null,\"Metaplasia é a troca de um tipo celular por outro, por estímulo crônico.\",\"Hiperplasia é aumento do número de células.\"],\n\"Cálcio dentro da célula liga as “tesouras”: fosfolipase, protease, endonuclease e ATPase.\"],\np10:[[\"O estresse oxidativo agride a célula. Quem protege são os antioxidantes.\",null,\"Não estimula crescimento: o dano leva à perda de função.\",\"Não há regeneração, há dano acumulado.\"],\n\"Estresse oxidativo é a “ferrugem” da célula: membrana, proteína e DNA vão oxidando com os anos.\"],\np11:[[\"Neutrófilo é a célula da inflamação aguda (fagocitose), não produz colágeno.\",null,\"Linfócito participa da resposta imune.\",\"Hemácia transporta oxigênio.\"],\n\"FIBROblasto faz FIBRA: colágeno.\"],\np12:[[\"Os lipídios são dissolvidos no processamento de rotina e aparecem como espaços vazios.\",\"O cálcio aparece roxo na H&E, mas não é o que a hematoxilina mais evidencia.\",null,\"O citoplasma é corado pela eosina (rosa).\"],\n\"H&E: Hematoxilina cora o núcleo de roxo; Eosina cora o citoplasma de rosa.\"],\np13:[[\"Regeneração completa é o oposto de cicatriz: restaura o tecido original.\",\"Há angiogênese na cicatrização (tecido de granulação).\",\"Há inflamação, e ela faz parte do reparo.\",null],\n\"Arcabouço intacto = regenera. Arcabouço destruído = cicatriz.\"],\np14:[[\"A fixação (com formol) vem logo depois da coleta, para preservar o tecido.\",\"A parafina é o suporte da inclusão, para cortar no micrótomo. Isso não é selagem.\",null,\"A selagem vem depois da coloração, não facilita a coloração.\"],\n\"Selar = lacrar a lâmina com a lamínula, no fim de tudo. Ordem: fixação, desidratação, diafanização, inclusão, corte, coloração e montagem (selagem).\"],\np15:[[null,\"Necrose é morte celular com ruptura da membrana.\",\"Apoptose é morte celular programada.\",\"Calcificação é depósito de cálcio.\"],\n\"O açúcar “gruda” na proteína e fica acumulado: glicação = depósito.\"],\np16:[[\"Lipofuscina é o pigmento do desgaste celular (envelhecimento), não do sangramento.\",null,\"Calcificação é depósito de cálcio, não pigmento do sangue.\",\"Glicogênio é reserva de glicose, não pigmento.\"],\n\"HEMOssiderina = HEMOrragia: o ferro do sangue fica guardado no macrófago.\"],\nx01:[[null,\"Liquefativa é a do cérebro e dos abscessos.\",\"Caseosa é a da tuberculose.\",\"Gordurosa é a do tecido adiposo (pancreatite).\"],\n\"Coagulativa = “fantasma”: a forma da célula fica, o núcleo some.\"],\nx02:[[\"Gordurosa ocorre na pancreatite e no tecido adiposo.\",null,\"Coagulativa mantém a arquitetura do tecido. Na caseosa ela desaparece.\",\"Fibrinoide ocorre na parede dos vasos, nas vasculites.\"],\n\"Caseosa = queijo = tuberculose.\"],\nx03:[[\"Hemossiderina vem do ferro, após sangramento.\",\"Melanina é o pigmento dos melanócitos.\",null,\"Bilirrubina causa icterícia.\"],\n\"Lipofuscina é o pigmento da idade: Lipo (gordura oxidada) + fusc (escuro).\"],\nx04:[[\"Metastática ocorre com hipercalcemia, em tecido normal.\",null,\"Ossificação é formação de osso.\",\"Hiperplasia é aumento do número de células.\"],\n\"DIStrófica = tecido DOENTE, cálcio normal. METAstática = tecido normal, cálcio ALTO.\"],\nx05:[[null,\"Necrose gordurosa é a morte do tecido adiposo por lipases, como na pancreatite.\",\"Metaplasia é a troca de um tipo celular por outro.\",\"Calcificação é depósito de cálcio.\"],\n\"Esteatose = gordura DENTRO da célula viva. Necrose gordurosa = tecido adiposo MORTO.\"],\nx06:[[\"Cariorrexe é a fragmentação do núcleo.\",\"Cariólise é o núcleo perdendo a cor até sumir.\",null,\"Mitose é divisão celular, não morte.\"],\n\"Picnose encolhe, cariorrexe quebra, cariólise apaga.\"],\nx07:[[\"O núcleo é corado pela hematoxilina.\",null,\"Os lipídios se perdem no processamento.\",\"O DNA fica no núcleo, corado pela hematoxilina.\"],\n\"Eosina = rosa = citoplasma. Hematoxilina = roxo = núcleo.\"],\nx08:[[null,\"A desidratação (com álcool) vem depois da fixação.\",\"A inclusão em parafina vem depois.\",\"A coloração é uma das últimas etapas.\"],\n\"Formol = fixar: “congela” o tecido no tempo para ele não se decompor.\"],\nx09:[[\"Na necrose a membrana rompe, o conteúdo vaza e há inflamação.\",null,\"Autólise é a digestão do tecido pelas próprias enzimas depois da morte.\",\"Calcificação é depósito de cálcio.\"],\n\"Apoptose é a morte “educada”: empacota tudo e não suja o chão.\"],\nx10:[[null,\"Cariorrexe é sinal de lesão irreversível (necrose).\",\"Calcificação é tardia.\",\"Caseosa é o padrão de necrose da tuberculose.\"],\n\"Sem ATP, a bomba de sódio para: entra água e a célula incha. É o primeiro sinal, e ainda é reversível.\"]\n,\nf01:[[\"Atrofia é redução do tamanho das células, o contrário do que aconteceu.\",null,\"Metaplasia é troca de tipo celular, que não ocorre no músculo treinado.\",\"Displasia é crescimento desordenado com atipia, uma alteração pré-neoplásica.\",\"Nem metaplasia nem displasia acontecem por exercício.\"],\n\"Exercício = músculo maior: pense primeiro em hipertrofia. Nesta prova, o gabarito foi hipertrofia + hiperplasia.\"],\nf02:[[\"A afirmativa 2 está correta: ela descreve o mecanismo da morte celular na isquemia.\",\"A 2 justifica a 1: explica por que a isquemia mata a célula.\",\"A 2 está correta e justifica a 1.\",\"A 1 está correta: a isquemia é a causa mais comum de lesão celular.\",null],\n\"Questão de “PORQUE”: 1º veja se cada frase é verdadeira sozinha; 2º pergunte se a 2 responde ao “por quê?” da 1.\"],\nf03:[[\"A apoptose não causa inflamação, porque o conteúdo da célula não vaza.\",\"Degeneração hidrópica é lesão reversível, com a célula inchada. Na apoptose ela encolhe.\",\"Calcificação metastática ocorre por hipercalcemia em tecidos normais.\",null,\"Lipofuscina é o pigmento do desgaste, no envelhecimento e na atrofia.\"],\n\"Apoptose: encolhe, fragmenta, empacota e não inflama.\"],\nf04:[[\"Falta a necrose gordurosa na gordura peripancreática.\",\"Caseosa é a necrose da tuberculose, não da pancreatite.\",null,\"Gangrenosa é a necrose de membros isquêmicos e não descreve a gordura.\",\"Fibrinoide ocorre na parede dos vasos (vasculites), não no tecido adiposo, e a ordem ficaria invertida.\"],\n\"Pâncreas + gordura ao redor: a gordura é sempre necrose GORDUROSA. Leia o “respectivamente” com calma.\"],\nf05:[[null,\"Não é “inespecífico”: a tuberculose é o exemplo clássico de inflamação granulomatosa, um padrão específico.\",\"Corpo estranho inerte forma granuloma de corpo estranho, sem necrose caseosa.\",\"Tecido de granulação é tecido de reparo, não a lesão típica da tuberculose.\",\"A tuberculose forma granulomas: “ausência de granulomas” está errado.\"],\n\"Tuberculose: granuloma + célula gigante de Langhans + centro caseoso (queijo).\"],\nf06:[[\"Linfocitose é típica de infecção viral. Aqui a infecção é bacteriana.\",null,\"Necrose fibrinoide ocorre na parede de vasos, em vasculites.\",\"Infiltrado linfomononuclear com granulomas é inflamação crônica granulomatosa.\",\"O essencial na amigdalite supurativa é neutrófilo + edema; úlcero-flegmonoso descreve lesão que ulcera e se espalha.\"],\n\"Bactéria piogênica aguda = neutrófilo + edema + pus.\"],\nm01:[[null,\"A selagem (montagem) é feita nos dois tipos de lâmina, então não é a diferença destacada.\",\"A arquitetura do tecido só é avaliada na histopatologia. A citologia vê células soltas.\",\"Núcleo e citoplasma são avaliados nos dois exames.\",\"Colorações especiais também podem ser feitas em citologia.\"],\n\"Histo = pedaço de tecido (arquitetura), fixado em formol. Cito = células soltas, fixadas em álcool.\"],\nm02:[[\"Tumefação é lesão reversível ou necrose, com a célula inchada. Na apoptose ela encolhe.\",\"Na apoptose o núcleo muda: condensa (picnose) e se fragmenta (cariorrexe).\",\"Enzimas lisossômicas vazando e lesando o tecido é característica da necrose.\",null,\"Transformação em conteúdo líquido é a necrose liquefativa.\"],\n\"Apoptose na lâmina: célula pequena, núcleo fragmentado e pedaços dentro do macrófago.\"],\nm03:[[\"Transformação em líquido é a necrose liquefativa (cérebro, abscessos).\",null,\"Material hialino perivascular lembra a necrose fibrinoide das vasculites.\",\"Material granuloso cercado por granulomas é a necrose caseosa (tuberculose).\",\"Material amorfo com células gigantes remete a granuloma, não à isquemia.\"],\n\"Isquemia em órgão sólido = coagulação = arquitetura preservada (“fantasmas”).\"],\nm04:[[\"Esteatonecrose (necrose gordurosa) já é lesão irreversível.\",\"Fragmentação nuclear (cariorrexe) é sinal de necrose, irreversível.\",\"“Sombras celulares” são os contornos de células mortas na necrose de coagulação.\",\"Esteatonecrose é necrose, irreversível.\",null],\n\"Reversível = célula viva inchada (tumefação) ou com gordura (esteatose). Núcleo quebrando = já morreu.\"],\nm05:[[\"Arquitetura preservada por dias é a necrose de coagulação.\",\"Material líquido é a necrose liquefativa.\",\"Restos granulares com granulomas é a necrose caseosa.\",null,\"Material amorfo eosinofílico nos vasos é a necrose fibrinoide.\"],\n\"Gordura + lipase + cálcio = sabão (saponificação).\"],\nm06:[[\"Atrofia é redução. Os hepatócitos que sobram precisam trabalhar mais, não menos.\",\"Metaplasia não ocorre nos hepatócitos.\",null,\"Nem metaplasia nem atrofia são a resposta compensatória.\",\"Hiperplasia sim, mas metaplasia não ocorre nos hepatócitos.\"],\n\"Célula estável que perde vizinhas se multiplica e cresce (hiperplasia + hipertrofia). Metaplasia é troca de epitélio (brônquio, esôfago, colo).\"],\nm07:[[\"Com a idade a capacidade de regeneração diminui.\",null,\"A função mitocondrial piora com a idade, com mais radicais livres.\",\"Células quiescentes e células-tronco perdem capacidade de ativação com o tempo.\",\"A atividade celular diminui com o envelhecimento.\"],\n\"Envelhecer = acumular estrago: DNA, proteína, mitocôndria e telômero curto.\"],\nm08:[[\"A 1 é verdadeira e a 2 é falsa.\",\"A 1 é verdadeira e a 4 é falsa.\",\"A 2 é falsa (radical livre lesa o DNA) e a 3 é verdadeira (o NO é radical livre).\",null,\"A 1 é verdadeira e a 4 é falsa.\"],\n\"Radical livre só estraga: lipídio (peroxidação), proteína e DNA. O NO é um radical livre que vasodilata e também mata micróbios.\"],\nj01:[[\"Não é inespecífico: há granulomas, um padrão específico.\",\"Granulomas imunes dependem de antígeno e de linfócitos T (ex.: tuberculose). Aqui o estímulo é material inerte.\",null,\"Um ano de evolução com granulomas e fibrose é crônico, não agudo.\",\"Hiperagudo não se aplica: o processo é crônico.\"],\n\"Material refringente (brilha na luz polarizada) + célula gigante = granuloma de CORPO ESTRANHO (não imune).\"],\nj02:[[\"A 2 está correta e não justifica a 1.\",null,\"A 2 está correta.\",\"A 1 está correta.\",\"As duas estão corretas, mas a 2 não explica o objetivo da inflamação.\"],\n\"Duas verdades não bastam: a 2 precisa responder “por quê?” da 1. Aqui não responde.\"],\nj03:[[\"A 1 é verdadeira: a coagulativa é a necrose mais comum.\",\"A 3 é falsa: a calcificação da necrose gordurosa é distrófica.\",null,\"A 2 é verdadeira.\",\"A 1 e a 2 são verdadeiras e a 3 é falsa.\"],\n\"Cálcio em tecido MORTO = distrófica. Se a questão juntar necrose com “metastática”, desconfie.\"],\nj04:[[\"O reparo não vem antes da remoção do agressor.\",\"Falta a resposta inflamatória, e a remoção no fim está fora de ordem.\",\"“Reação” e “regeneração” não fazem parte dos 5 R.\",null,\"Revascularização e regeneração não são etapas dos 5 R.\"],\n\"Ordem lógica: ver o inimigo, chamar a tropa, tirar o inimigo, consertar e recuperar.\"],\nj05:[[null,\"Não há granulomas nem necrose gangrenosa numa colecistite crônica calculosa comum.\",\"Neutrófilos predominam na colecistite aguda.\",\"Eosinófilos não caracterizam a colecistite.\",\"Abscessos são complicação aguda.\"],\n\"Anos de cálculo com pouco sintoma = crônica: linfócito + fibrose.\"],\nj06:[[\"A apoptose não causa inflamação, e doenças autoimunes costumam causar inflamação crônica.\",\"A perda de função na inflamação aguda é temporária, não permanente.\",\"A inflamação aguda é barulhenta: dor, calor, rubor, tumor e perda de função.\",\"Estímulos crônicos causam inflamação crônica.\",null],\n\"Aguda = vaso dilata + vaza (exsudato) + neutrófilo.\"],\nr01:[[\"Prostatite não dá dor em fossa ilíaca direita, e inflamação aguda não é granulomatosa.\",\"Colecistite dá dor no hipocôndrio direito, e o quadro é agudo.\",null,\"Dermatite é inflamação de pele.\",\"Distrofia muscular é doença genética do músculo, sem febre aguda.\"],\n\"Fossa ilíaca direita + febre + vômito = apêndice. Apendicite aguda = supurativa (pus e neutrófilos).\"],\nr02:[[null,\"A metaplasia escamosa não favorece adenocarcinoma. O câncer de colo se relaciona principalmente ao HPV.\",\"A endocérvice é revestida por epitélio glandular (colunar). O escamoso é da ectocérvice.\",\"A metaplasia do colo é escamosa, não glandular, e é uma adaptação comum.\",\"Células metaplásicas são normais, e o laudo foi negativo para malignidade.\"],\n\"Colo do útero: glandular vira escamoso = metaplasia escamosa (normal). O brônquio do fumante também vira escamoso.\"],\nr03:[[\"Calcificação metastática é consequência da hipercalcemia, não mecanismo de lesão.\",\"Atrofia é adaptação, não mecanismo de lesão.\",\"“Bloqueio apoptótico” não é mecanismo de lesão.\",\"Esteatose é acúmulo intracelular (um resultado), não mecanismo.\",null],\n\"Mecanismos de lesão: ATP baixo, mitocôndria, cálcio, radicais livres, membrana e DNA/proteínas.\"],\nt01:[[null,\"Membrana hialina é do dano alveolar difuso, e perda de tolerância é autoimunidade.\",\"Pneumonia bacteriana aguda não é granulomatosa.\",\"Macrófagos e linfócitos com processo crônico não descrevem uma infecção de cinco dias.\",\"Linfócitos e plasmócitos sugerem processo crônico ou viral.\"],\n\"Bactéria no alvéolo = neutrófilo no alvéolo (aguda, supurativa).\"],\nt02:[[\"A mama na gestação tem hiperplasia (e hipertrofia) glandular, mas não metaplasia.\",\"O coração na gestação e na hipertensão sofre hipertrofia, não atrofia.\",null,\"Não há apoptose maciça do endométrio durante a gestação.\",\"O músculo cardíaco sofre hipertrofia. Ele quase não se divide, então não é hiperplasia.\"],\n\"Útero grávido = hipertrofia + hiperplasia. Coração com hipertensão = só hipertrofia.\"],\nt03:[[\"Tecidos permanentes não têm multiplicação de células-tronco, e isso não leva à apoptose.\",\"BCL-2 e BCL-XL são ANTIapoptóticas: bloqueiam a apoptose.\",\"Bloquear o pró-apoptótico impede a apoptose.\",\"Complemento não é o mecanismo da apoptose. Influxo de cálcio com defeito de membrana lembra necrose.\",null],\n\"Pró-apoptóticas: BAX, BAK e Fas. Antiapoptóticas: BCL-2 e BCL-XL (“seguram a vida”).\"]\n\n};\n\n/* =========================================================\n   ONDE ESTUDAR NO ROBBINS (capítulo e seção de cada questão)\n   ========================================================= */\nconst CHAPTERS = {\n  1: \"Cap. 1, Respostas celulares ao estresse: adaptação, lesão e morte\",\n  2: \"Cap. 2, Inflamação aguda e crônica\",\n  3: \"Cap. 3, Renovação, regeneração e reparo dos tecidos\"\n};\n/* [capítulo, nome da seção, página inicial no PDF da 8ª edição] */\nconst SEC = {\n  hipertrofia:[1,\"Hipertrofia\",35], hiperplasia:[1,\"Hiperplasia\",39], atrofia:[1,\"Atrofia\",41], metaplasia:[1,\"Metaplasia\",44],\n  atp:[1,\"Mecanismos da lesão celular: depleção de ATP\",66], apoptose:[1,\"Apoptose\",88], autofagia:[1,\"Autofagia\",106],\n  pigmentos:[1,\"Acúmulos intracelulares: pigmentos\",118], calcificacao:[1,\"Calcificação patológica\",122],\n  historia:[2,\"Visão geral da inflamação: destaques históricos\",140], vascular:[2,\"Reações dos vasos sanguíneos na inflamação aguda\",145],\n  recrutamento:[2,\"Reações dos leucócitos: recrutamento\",150], reconhecimento:[2,\"Reconhecimento dos micro-organismos e tecidos mortos\",158],\n  remocao:[2,\"Remoção dos agentes agressores\",160], ativacao:[2,\"Outras respostas funcionais dos leucócitos ativados\",165],\n  termino:[2,\"Término da resposta inflamatória aguda\",171], aminas:[2,\"Mediadores derivados de células: aminas vasoativas\",175],\n  araquidonico:[2,\"Metabólitos do ácido araquidônico\",176], complemento:[2,\"Sistema complemento\",188],\n  cininas:[2,\"Sistemas da coagulação e das cininas\",190], resultados:[2,\"Resultados da inflamação aguda\",194],\n  serosa:[2,\"Padrões morfológicos: inflamação serosa\",197], fibrinosa:[2,\"Padrões morfológicos: inflamação fibrinosa\",198],\n  supurativa:[2,\"Inflamação supurativa ou purulenta: abscessos\",199], ulceras:[2,\"Padrões morfológicos: úlceras\",200],\n  causas_cronica:[2,\"Causas da inflamação crônica\",203], morf_cronica:[2,\"Inflamação crônica: características morfológicas\",204],\n  macrofagos:[2,\"Participação dos macrófagos na inflamação crônica\",206], outras_celulas:[2,\"Outras células na inflamação crônica\",210],\n  granuloma:[2,\"Inflamação granulomatosa\",213], sistemicos:[2,\"Efeitos sistêmicos da inflamação\",216],\n  fatores:[3,\"Fatores de crescimento\",244], regeneracao:[3,\"Mecanismos de regeneração dos tecidos e órgãos\",258],\n  hepatica:[3,\"Regeneração hepática\",259], reparo:[3,\"Cura por reparo, formação de cicatriz e fibrose\",273],\n  angiogenese:[3,\"Mecanismos da angiogênese\",274], fibrose:[3,\"Fibrose\",290],\n  morf_lesao:[1,\"Morfologia da lesão celular: alterações do núcleo\",52], reversivel:[1,\"Lesão celular reversível\",54],\n  necrose:[1,\"Padrões de necrose tecidual\",58], calcio_int:[1,\"Mecanismos da lesão celular: influxo de cálcio\",71],\n  radicais:[1,\"Mecanismos da lesão celular: radicais livres\",73], acumulos:[1,\"Acúmulos intracelulares\",107],\n  feridas:[3,\"Cura de feridas: tecido de granulação\",278],\n  visao:[2,\"Visão geral da inflamação\",138], apoptose_mec:[1,\"Mecanismos da apoptose\",96], envelhecimento:[1,\"Envelhecimento celular\",126],\n  mec:[3,\"Matriz extracelular e interações célula-matriz\",262], reparo_pat:[3,\"Aspectos patológicos do reparo: cicatriz hipertrófica e queloide\",288]\n};\n/* seção de cada questão; \":N\" indica a página exata quando o ponto está mais adiante na seção */\nconst REF = {\n  a01:\"hipertrofia\", a02:\"metaplasia\", a03:\"recrutamento\", a04:\"aminas\", a05:\"granuloma\", a06:\"vascular\", a07:\"macrofagos\", a08:\"recrutamento:152\", a09:\"atrofia\", a10:\"complemento\",\n  b01:\"hipertrofia\", b02:\"atrofia:43\", b03:\"metaplasia\", b04:\"hiperplasia\", b05:\"hipertrofia:38\", b06:\"metaplasia\", b07:\"pigmentos\", b08:\"hepatica\", b09:\"autofagia\", b10:\"hipertrofia:36\",\n  b11:\"vascular:146\", b12:\"vascular:147\", b13:\"recrutamento:152\", b14:\"recrutamento:155\", b15:\"remocao\", b16:\"serosa\", b17:\"cininas\", b18:\"remocao\", b19:\"sistemicos\", b20:\"termino\",\n  b21:\"recrutamento:157\", b22:\"supurativa\", b23:\"ulceras\", b24:\"remocao:163\", b25:\"sistemicos\", b26:\"morf_cronica\", b27:\"ativacao\", b28:\"ativacao\", b29:\"granuloma\", b30:\"granuloma\",\n  b31:\"outras_celulas:211\", b32:\"fibrose\", b33:\"granuloma:214\", b34:\"outras_celulas:211\", b35:\"fatores:245\", b36:\"reconhecimento:159\", b37:\"outras_celulas\", b38:\"complemento\", b39:\"araquidonico\", b40:\"causas_cronica\",\n  b41:\"resultados\", b42:\"angiogenese\", b43:\"remocao:163\", b44:\"recrutamento:152\", b45:\"fibrinosa\", b46:\"apoptose\", b47:\"sistemicos:217\", b48:\"granuloma\", b49:\"cininas\", b50:\"metaplasia:45\",\n  c01:\"regeneracao\", c02:\"hipertrofia\", c03:\"metaplasia\", c04:\"vascular:146\", c05:\"recrutamento:157\", c06:\"supurativa\", c07:\"fibrinosa\", c08:\"ulceras\", c09:\"resultados\", c10:\"morf_cronica\",\n  c11:\"granuloma\", c12:\"granuloma\", c13:\"granuloma:214\", c14:\"historia\", c15:\"vascular\", c16:\"atp\", c18:\"calcificacao\", c19:\"fibrinosa\", c20:\"ulceras\",\n  p06:\"necrose:60\", p07:\"feridas\", p08:\"calcificacao:125\", p09:\"calcio_int\", p10:\"radicais\", p11:\"reparo\", p13:\"reparo\", p15:\"acumulos\", p16:\"pigmentos:119\",\n  d01:\"necrose:61\", d02:\"necrose:59\",\n  x01:\"necrose:59\", x02:\"necrose:61\", x03:\"pigmentos\", x04:\"calcificacao:123\", x05:\"acumulos:110\", x06:\"morf_lesao\", x09:\"apoptose\", x10:\"reversivel\",\n  f01:\"hipertrofia:36\", f02:\"atp\", f03:\"apoptose:92\", f04:\"necrose:61\", f05:\"granuloma\", f06:\"supurativa\", h07:\"visao\", h08:\"mec\",\n  m02:\"apoptose:92\", m03:\"necrose:59\", m04:\"reversivel\", m05:\"necrose:62\", m06:\"hepatica\", m07:\"envelhecimento\", m08:\"radicais\", n01:\"apoptose_mec\",\n  j01:\"granuloma:214\", j02:\"visao\", j03:\"necrose\", j04:\"visao\", j05:\"morf_cronica\", j06:\"vascular\", k07:\"apoptose_mec\", k08:\"granuloma\",\n  r01:\"supurativa\", r02:\"metaplasia\", r03:\"atp\", s01:\"granuloma\", s02:\"reparo\", t01:\"supurativa\", t02:\"hipertrofia\", t03:\"apoptose_mec:99\", u01:\"apoptose\", u02:\"granuloma:214\"\n};\nconst REF_NOTE = {\n  m01: \"Esse assunto é de técnica histológica (Histologia), não está no Robbins.\",\n  j04: \"Os “5 R” aparecem nas edições mais novas do Robbins. Na 8ª edição, a seção mais próxima é a visão geral da inflamação.\",\n  h08: \"Os distúrbios do reparo (cicatriz hipertrófica, queloide, deiscência) estão na p. 288.\",\n  p12: \"Esse assunto é de técnica histológica (Histologia), não está no Robbins.\",\n  p14: \"Esse assunto é de técnica histológica (Histologia), não está no Robbins.\",\n  x07: \"Esse assunto é de técnica histológica (Histologia), não está no Robbins.\",\n  x08: \"Esse assunto é de técnica histológica (Histologia), não está no Robbins.\",\n  b18: \"As NETs não aparecem na 8ª edição (o tema entrou nas edições mais novas). A seção indicada é a mais próxima: como o neutrófilo mata micro-organismos.\"\n};\n\nfunction refParts(id){\n  const [key, pg] = (REF[id] || \"\").split(\":\");\n  const s = SEC[key];\n  if (!s) return null;\n  return { ch: s[0], name: s[1], page: pg ? +pg : s[2] };\n}\n\nfunction refHTML(id){\n  const r = refParts(id);\n  if (!r) return REF_NOTE[id] ? `<div class=\"ref\"><span class=\"book\" aria-hidden=\"true\"></span><div><div class=\"eh\">Onde estudar</div>${REF_NOTE[id]}</div></div>` : \"\";\n  const note = REF_NOTE[id] ? `<div class=\"refnote\">${REF_NOTE[id]}</div>` : \"\";\n  return `<div class=\"ref\"><span class=\"book\" aria-hidden=\"true\"></span><div>\n    <div class=\"eh\">Onde está no Robbins</div>\n    <b>${CHAPTERS[r.ch]}</b>, seção “${r.name}”, <b>p. ${r.page}</b>.${note}</div></div>`;\n}\n\nfunction robbinsMapHTML(){\n  const count = {};\n  QUESTIONS.forEach(q => { const k = (REF[q[0]] || \"\").split(\":\")[0]; count[k] = (count[k] || 0) + 1; });\n  const block = ch => Object.keys(SEC).filter(k => SEC[k][0] === ch && count[k])\n    .map(k => `<li><span>${SEC[k][1]} <em>p. ${SEC[k][2]}</em></span><b>${count[k]} ${count[k] === 1 ? \"questão\" : \"questões\"}</b></li>`).join(\"\");\n  return `<details class=\"rmap\">\n    <summary>Ver quais seções do Robbins as questões cobrem</summary>\n    <h3>${CHAPTERS[1]}</h3><ul>${block(1)}</ul>\n    <h3>${CHAPTERS[2]}</h3><ul>${block(2)}</ul>\n    <h3>${CHAPTERS[3]}</h3><ul>${block(3)}</ul>\n    <p class=\"note\">Robbins &amp; Cotran, Patologia: Bases Patológicas das Doenças, 8ª edição. As páginas são as do PDF do livro (parte 1).</p>\n  </details>`;\n}\n\n/* =========================================================\n   REVISÃO ESPAÇADA (estilo Anki, simplificado)\n   ========================================================= */\nconst KEY = \"patologia-n1-srs-v1\";\nconst DAY = 86400000;\nconst MIN = 60000;\nlet memoryStore = {};\nfunction load(){ try{ const raw = localStorage.getItem(KEY); return raw ? JSON.parse(raw) : {}; }catch(e){ return memoryStore; } }\nconst HIST_KEY = \"patologia-n1-hist\";\nlet onProgressSaved = null;\nfunction save(){\n  try{ localStorage.setItem(KEY, JSON.stringify(state)); localStorage.setItem(HIST_KEY, JSON.stringify(hist)); }catch(e){ memoryStore = state; }\n  if (onProgressSaved) onProgressSaved();\n}\nlet state = load();\nlet hist = (() => { try { return JSON.parse(localStorage.getItem(HIST_KEY)) || {}; } catch(e){ return {}; } })();\nfunction dayKey(ts){ const d = ts ? new Date(ts) : new Date(); return d.getFullYear() + \"-\" + String(d.getMonth() + 1).padStart(2, \"0\") + \"-\" + String(d.getDate()).padStart(2, \"0\"); }\n\n/* registra cada resposta: tentativas (a), acertos (k), quando (t) e o total do dia */\nfunction track(id, ok){\n  const s = Object.assign(blank(), state[id] || {});\n  s.a = (s.a || 0) + 1; if (ok) s.k = (s.k || 0) + 1; s.t = Date.now();\n  state[id] = s;\n  const d = dayKey(), h = hist[d] || [0, 0];\n  h[0]++; if (ok) h[1]++; hist[d] = h;\n  save();\n}\n\nfunction blank(){ return { r:0, e:2.5, i:0, d:0, l:0, n:0 }; }\n\nfunction nextDays(s, grade){\n  if (grade === \"hard\") return s.r === 0 ? 1 : Math.max(s.i + 1, Math.round(s.i * 1.2));\n  if (grade === \"good\") return s.r === 0 ? 2 : Math.max(s.i + 1, Math.round(s.i * s.e));\n  if (grade === \"easy\") return s.r === 0 ? 4 : Math.max(s.i + 2, Math.round(s.i * s.e * 1.3));\n  return 0;\n}\n\n/* Véspera de prova: tempos em minutos que crescem pouco (Difícil não cresce) */\nconst RITMO_KEY = \"patologia-n1-ritmo\";\nlet ritmo = (() => { try { return localStorage.getItem(RITMO_KEY) || \"prova\"; } catch(e){ return \"prova\"; } })();\nfunction setRitmo(r){ ritmo = r; try { localStorage.setItem(RITMO_KEY, r); } catch(e){} }\nconst PROVA = { again: [5, 5, 5], hard: [15, 15, 15], good: [30, 60, 120], easy: [60, 120, 240] };\nfunction provaMins(s, grade){ const a = PROVA[grade]; return a[Math.min((s && s.r) || 0, a.length - 1)]; }\nfunction fmtMins(m){\n  if (m < 60) return m + \" min\";\n  const h = m / 60;\n  return (Number.isInteger(h) ? h : h.toFixed(1).replace(\".\", \",\")) + \" h\";\n}\nfunction intervalLabel(s, grade){ return ritmo === \"prova\" ? fmtMins(provaMins(s, grade)) : fmtDays(nextDays(s, grade)); }\n\nfunction schedule(id, grade, customDays, unit){\n  const s = Object.assign(blank(), state[id] || {});\n  const now = Date.now();\n  if (grade === \"custom\"){\n    if (customDays === 0){ s.d = now + 10 * MIN; }\n    else if (unit === \"min\"){ s.r += 1; s.i = customDays / 1440; s.d = now + customDays * MIN; }\n    else { s.i = customDays; s.r += 1; s.d = now + customDays * DAY; }\n  } else if (grade !== \"again\" && ritmo === \"prova\"){\n    const m = provaMins(s, grade);\n    if (grade === \"hard\") s.e = Math.max(1.3, s.e - 0.15);\n    if (grade === \"easy\") s.e = s.e + 0.15;\n    s.r += 1; s.i = m / 1440; s.d = now + m * MIN;\n  } else if (grade === \"again\"){\n    s.e = Math.max(1.3, s.e - 0.2); s.i = 0; s.r = 0; s.l += 1; s.d = now + 10 * MIN;\n  } else {\n    const days = nextDays(s, grade);\n    if (grade === \"hard\") s.e = Math.max(1.3, s.e - 0.15);\n    if (grade === \"easy\") s.e = s.e + 0.15;\n    s.i = days; s.r += 1; s.d = now + days * DAY;\n  }\n  s.n += 1;\n  state[id] = s; save();\n}\n\nfunction fmtDays(d){\n  if (d <= 1) return \"1 dia\";\n  if (d < 30) return d + \" dias\";\n  const m = Math.round(d / 30);\n  if (m < 12) return m === 1 ? \"1 mês\" : m + \" meses\";\n  const y = Math.round(d / 365);\n  return y === 1 ? \"1 ano\" : y + \" anos\";\n}\nfunction fmtUntil(ts){\n  const diff = ts - Date.now();\n  if (diff <= 0) return \"agora\";\n  if (diff < 60 * MIN) return \"em \" + Math.max(1, Math.round(diff / MIN)) + \" min\";\n  if (diff < DAY) return \"em \" + Math.round(diff / (60 * MIN)) + \" h\";\n  return \"em \" + fmtDays(Math.round(diff / DAY));\n}\n\nlet customIds = new Set();\nfunction cardsOf(topic){\n  if (topic === \"all\") return QUESTIONS;\n  if (topic === \"custom\") return QUESTIONS.filter(q => customIds.has(q[0]));\n  return QUESTIONS.filter(q => q[1] === topic);\n}\nfunction topicAcc(topic){\n  let a = 0, k = 0;\n  cardsOf(topic).forEach(q => { const s = state[q[0]]; if (s){ a += s.a || 0; k += s.k || 0; } });\n  return { a, k, pct: a ? Math.round(k / a * 100) : null };\n}\n\nfunction statsOf(topic){\n  const now = Date.now();\n  let novas = 0, revisar = 0, emdia = 0, next = Infinity;\n  cardsOf(topic).forEach(q => {\n    const s = state[q[0]];\n    if (!s) novas++;\n    else if (s.d <= now) revisar++;\n    else { emdia++; next = Math.min(next, s.d); }\n  });\n  return { novas, revisar, emdia, next, total: cardsOf(topic).length, acc: topicAcc(topic).pct };\n}\n\nfunction shuffle(arr){ const a = arr.slice(); for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }\n\n/* progresso: dominada = 3 acertos seguidos; 1 e 2 acertos contam 1/3 e 2/3 */\nfunction progressOf(topic){\n  const cards = cardsOf(topic);\n  let sum = 0, dom = 0, prog = 0;\n  cards.forEach(q => {\n    const s = state[q[0]];\n    if (!s) return;\n    const w = Math.min(s.r, 3) / 3;\n    sum += w;\n    if (s.r >= 3) dom++; else prog++;\n  });\n  return { pct: Math.round(sum / cards.length * 100), dom, prog, novas: cards.length - dom - prog };\n}\n\nfunction progHTML(p, from){\n  const full = p.pct >= 100;\n  const gain = from != null && p.pct > from ? `<span class=\"gain\">+${p.pct - from} pontos nesta sessão</span>` : \"\";\n  return `<div class=\"prog${full ? \" full\" : \"\"}\">\n    <div class=\"prog-head\">\n      <b data-to=\"${p.pct}\" data-from=\"${from != null ? from : 0}\">${from != null ? from : 0}%</b>\n      <span class=\"lbl\">${full ? \"dominado!\" : \"aprendido\"}</span>\n      ${gain}\n      <span class=\"det\">${p.dom} ${p.dom === 1 ? \"dominada\" : \"dominadas\"}, ${p.prog} em progresso</span>\n    </div>\n    <div class=\"track\" role=\"progressbar\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"${p.pct}\" aria-label=\"Percentual aprendido\">\n      <i class=\"fill\" style=\"width:${from != null ? from : 0}%\" data-w=\"${p.pct}\"></i>\n    </div>\n  </div>`;\n}\n\nfunction animateBars(){\n  const reduce = window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  const fills = app.querySelectorAll(\".fill[data-w]\");\n  const nums = app.querySelectorAll(\".prog-head b[data-to]\");\n  if (reduce){\n    fills.forEach(f => f.style.width = f.dataset.w + \"%\");\n    nums.forEach(n => n.textContent = n.dataset.to + \"%\");\n    return;\n  }\n  requestAnimationFrame(() => requestAnimationFrame(() => {\n    fills.forEach(f => f.style.width = f.dataset.w + \"%\");\n  }));\n  const t0 = performance.now(), dur = 1100;\n  const step = now => {\n    const k = Math.min(1, (now - t0) / dur);\n    const e = 1 - Math.pow(1 - k, 3);\n    nums.forEach(n => {\n      const a = +n.dataset.from, b = +n.dataset.to;\n      n.textContent = Math.round(a + (b - a) * e) + \"%\";\n    });\n    if (k < 1) requestAnimationFrame(step);\n  };\n  requestAnimationFrame(step);\n}\n\n/* =========================================================\n   TELAS\n   ========================================================= */\nconst app = document.getElementById(\"app\");\nconst LETTERS = [\"A\",\"B\",\"C\",\"D\",\"E\"];\nlet session = null;\nlet view = \"home\";\n\n/* pequenas “lâminas” desenhadas em SVG para cada assunto */\nfunction tissueSVG(kind){\n  const nuclei = (pts, r) => pts.map(p => `<circle cx=\"${p[0]}\" cy=\"${p[1]}\" r=\"${r}\" fill=\"var(--hema)\" opacity=\".85\"/>`).join(\"\");\n  if (kind === 0){ // adaptação: células grandes e pequenas lado a lado\n    return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n      <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n      <g fill=\"none\" stroke=\"var(--eosin)\" stroke-width=\"1.4\" opacity=\".75\">\n        <rect x=\"18\" y=\"26\" width=\"20\" height=\"20\" rx=\"4\"/><rect x=\"18\" y=\"50\" width=\"20\" height=\"20\" rx=\"4\"/>\n        <rect x=\"44\" y=\"18\" width=\"34\" height=\"34\" rx=\"6\"/><rect x=\"44\" y=\"56\" width=\"34\" height=\"26\" rx=\"6\"/>\n        <rect x=\"84\" y=\"30\" width=\"16\" height=\"16\" rx=\"3\"/><rect x=\"84\" y=\"50\" width=\"16\" height=\"16\" rx=\"3\"/><rect x=\"104\" y=\"40\" width=\"14\" height=\"14\" rx=\"3\"/>\n      </g>\n      ${nuclei([[28,36],[28,60],[61,35],[61,69],[92,38],[92,58],[111,47]],3.4)}\n    </svg>`;\n  }\n  if (kind === 1){ // aguda: vaso com neutrófilos saindo\n    return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n      <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n      <path d=\"M8 44 Q67 30 127 44 L127 58 Q67 44 8 58 Z\" fill=\"none\" stroke=\"var(--eosin)\" stroke-width=\"1.6\" opacity=\".8\"/>\n      <g fill=\"var(--hema)\" opacity=\".9\">\n        <circle cx=\"30\" cy=\"48\" r=\"2.2\"/><circle cx=\"34\" cy=\"50\" r=\"2.2\"/><circle cx=\"32\" cy=\"53\" r=\"2.2\"/>\n        <circle cx=\"62\" cy=\"62\" r=\"2.2\"/><circle cx=\"66\" cy=\"64\" r=\"2.2\"/><circle cx=\"64\" cy=\"67\" r=\"2.2\"/>\n        <circle cx=\"86\" cy=\"72\" r=\"2.2\"/><circle cx=\"90\" cy=\"74\" r=\"2.2\"/><circle cx=\"88\" cy=\"77\" r=\"2.2\"/>\n        <circle cx=\"50\" cy=\"22\" r=\"2.2\"/><circle cx=\"54\" cy=\"24\" r=\"2.2\"/><circle cx=\"52\" cy=\"27\" r=\"2.2\"/>\n        <circle cx=\"100\" cy=\"26\" r=\"2.2\"/><circle cx=\"104\" cy=\"28\" r=\"2.2\"/><circle cx=\"102\" cy=\"31\" r=\"2.2\"/>\n      </g>\n    </svg>`;\n  }\n  if (kind === 3){ // provas antigas: folha de prova corrigida\n    return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n      <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n      <rect x=\"40\" y=\"14\" width=\"56\" height=\"72\" rx=\"4\" fill=\"var(--card)\" stroke=\"var(--hema)\" stroke-width=\"1.4\"/>\n      <g stroke=\"var(--hema)\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\".55\">\n        <line x1=\"48\" y1=\"28\" x2=\"84\" y2=\"28\"/><line x1=\"48\" y1=\"40\" x2=\"80\" y2=\"40\"/><line x1=\"48\" y1=\"52\" x2=\"86\" y2=\"52\"/><line x1=\"48\" y1=\"64\" x2=\"76\" y2=\"64\"/>\n      </g>\n      <g fill=\"var(--hema)\"><circle cx=\"53\" cy=\"34\" r=\"2.6\"/><circle cx=\"53\" cy=\"46\" r=\"2.6\"/><circle cx=\"53\" cy=\"58\" r=\"2.6\"/></g>\n      <path d=\"M84 70 l6 7 l12 -16\" fill=\"none\" stroke=\"var(--eosin)\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n    </svg>`;\n  }\n  // crônica: granuloma\n  return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n    <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n    <circle cx=\"67\" cy=\"50\" r=\"30\" fill=\"var(--eosin)\" opacity=\".28\"/>\n    <circle cx=\"67\" cy=\"50\" r=\"12\" fill=\"var(--card)\" opacity=\".85\"/>\n    <g fill=\"var(--hema)\" opacity=\".55\">\n      <ellipse cx=\"52\" cy=\"40\" rx=\"3.6\" ry=\"2\" transform=\"rotate(-30 52 40)\"/><ellipse cx=\"82\" cy=\"40\" rx=\"3.6\" ry=\"2\" transform=\"rotate(30 82 40)\"/>\n      <ellipse cx=\"50\" cy=\"60\" rx=\"3.6\" ry=\"2\" transform=\"rotate(30 50 60)\"/><ellipse cx=\"84\" cy=\"60\" rx=\"3.6\" ry=\"2\" transform=\"rotate(-30 84 60)\"/>\n      <ellipse cx=\"67\" cy=\"30\" rx=\"3.6\" ry=\"2\"/><ellipse cx=\"67\" cy=\"71\" rx=\"3.6\" ry=\"2\"/>\n    </g>\n    <g fill=\"var(--hema)\" opacity=\".95\">\n      ${[[25,50],[30,30],[30,70],[45,18],[45,82],[67,13],[67,87],[89,18],[89,82],[104,30],[104,70],[109,50],[20,40],[20,60],[114,40],[114,60]].map(p=>`<circle cx=\"${p[0]}\" cy=\"${p[1]}\" r=\"2.6\"/>`).join(\"\")}\n    </g>\n  </svg>`;\n}\n\nfunction statBlock(st){\n  return `<div class=\"stats\">\n    <div class=\"stat new\"><b>${st.novas}</b><span>novas</span></div>\n    <div class=\"stat due\"><b>${st.revisar}</b><span>para revisar</span></div>\n    <div class=\"stat ok\"><b>${st.emdia}</b><span>em dia</span></div>\n    ${st.acc != null ? `<div class=\"stat acc\"><b>${st.acc}%</b><span>de acerto</span></div>` : \"\"}\n  </div>`;\n}\n\nfunction renderHome(){\n  if (typeof updatePending !== \"undefined\" && updatePending){ location.reload(); return; }\n  view = \"home\"; session = null;\n  app.classList.remove(\"in-room\", \"chat-open\");\n  const slides = Object.keys(TOPICS).map(k => {\n    const t = TOPICS[k], st = statsOf(k);\n    return `<button class=\"slide\" data-topic=\"${k}\" aria-label=\"Estudar ${t.name}\">\n      <div class=\"label\">\n        <div><h2>${t.name}</h2><div class=\"total\">${st.total} questões${t.sub ? `, ${t.sub}` : \"\"}</div></div>\n        ${statBlock(st)}\n      </div>\n      <div class=\"glass\">${tissueSVG(t.tissue)}<span class=\"go\">Estudar</span></div>\n      ${progHTML(progressOf(k))}\n    </button>`;\n  }).join(\"\");\n  const all = statsOf(\"all\");\n  app.innerHTML = `\n    <header class=\"intro\">\n      <h1>Patologia Geral N1</h1>\n      <p>As ${QUESTIONS.length} questões das listas do professor, separadas por assunto, com correção comentada e revisão espaçada. Cada comentário é baseado no Robbins &amp; Cotran (8ª edição) e indica capítulo, seção e página onde a resposta está.</p>\n    </header>\n    <div class=\"how\">\n      <strong>Como funciona:</strong> responda, veja o comentário e diga se foi difícil, médio ou fácil. Quanto mais fácil, mais tempo a questão demora para voltar. Se preferir, você mesmo escolhe quando ela volta. Se errar, ela volta ainda nesta sessão. A barra de cada assunto mostra quanto você já aprendeu: uma questão fica dominada depois de 3 acertos seguidos em revisões. Seu progresso fica salvo neste navegador.\n    </div>\n    <div class=\"ritmo\">\n      <span>Ritmo da revisão</span>\n      <div class=\"seg\" role=\"group\" aria-label=\"Ritmo da revisão\">\n        <button data-r=\"prova\" class=\"${ritmo === \"prova\" ? \"on\" : \"\"}\">Véspera de prova<small>volta em minutos e horas</small></button>\n        <button data-r=\"longo\" class=\"${ritmo === \"longo\" ? \"on\" : \"\"}\">Longo prazo<small>volta em dias</small></button>\n      </div>\n    </div>\n    <div id=\"acctSlot\"></div>\n    <div id=\"groupSlot\">${groupEntryHTML()}</div>\n    <button class=\"evo-entry\" id=\"evoBtn\"><span class=\"evo-ic\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></span><span><h2>Minha evolução</h2><p>${evoLineHTML()}</p></span></button>\n    ${robbinsMapHTML()}\n    <div class=\"slides\">\n      ${slides}\n      <button class=\"slide all\" data-topic=\"all\" aria-label=\"Estudar todos os assuntos misturados\">\n        <div class=\"label\">\n          <div><h2>Todos os assuntos misturados</h2><div class=\"total\">${all.total} questões</div></div>\n          ${statBlock(all)}\n        </div>\n        ${progHTML(progressOf(\"all\"))}\n      </button>\n    </div>\n    <div class=\"backup-row\">\n      <button class=\"ghost\" id=\"bkSave\">Salvar backup do progresso</button>\n      <button class=\"ghost\" id=\"bkLoad\">Restaurar backup</button>\n    </div>\n    <div class=\"footer\">\n      <span>Progresso salvo só neste aparelho e navegador. Faça backup de vez em quando.</span>\n      <span class=\"fbtns\"><button class=\"linkbtn\" id=\"donoBtn\">Área do dono</button><button class=\"linkbtn\" id=\"reset\">Zerar meu progresso</button></span>\n    </div>`;\n  app.querySelectorAll(\".slide\").forEach(b => b.addEventListener(\"click\", () => startSession(b.dataset.topic, false)));\n  document.getElementById(\"bkSave\").addEventListener(\"click\", renderBackupSave);\n  document.getElementById(\"bkLoad\").addEventListener(\"click\", renderBackupLoad);\n  document.getElementById(\"reset\").addEventListener(\"click\", () => {\n    if (confirm(\"Apagar todo o seu progresso? Todas as questões voltam a ser novas.\")){ state = {}; save(); renderHome(); }\n  });\n  refreshGroupEntry();\n  if (typeof refreshAcct === \"function\") refreshAcct();\n  const donoBtn = document.getElementById(\"donoBtn\");\n  if (donoBtn){ if (roomStatus === \"ok\") donoBtn.onclick = renderDono; else donoBtn.remove(); }\n  document.getElementById(\"evoBtn\").onclick = renderEvolution;\n  app.querySelectorAll(\".seg button[data-r]\").forEach(b => b.onclick = () => { setRitmo(b.dataset.r); app.querySelectorAll(\".seg button\").forEach(x => x.classList.toggle(\"on\", x === b)); });\n  animateBars();\n  window.scrollTo(0, 0);\n}\n\nfunction topicName(topic){ return topic === \"all\" ? \"Todos os assuntos\" : topic === \"custom\" ? \"Treino das que você mais erra\" : TOPICS[topic].name; }\n\nfunction startSession(topic, ahead){\n  const now = Date.now();\n  const cards = cardsOf(topic);\n  let queue;\n  if (ahead){\n    queue = cards.slice().sort((a, b) => (state[a[0]] ? state[a[0]].d : 0) - (state[b[0]] ? state[b[0]].d : 0));\n  } else {\n    const due = cards.filter(q => state[q[0]] && state[q[0]].d <= now).sort((a, b) => state[a[0]].d - state[b[0]].d);\n    const fresh = shuffle(cards.filter(q => !state[q[0]]));\n    queue = due.concat(fresh);\n  }\n  if (!queue.length){ renderEmpty(topic); return; }\n  session = { topic, queue, total: queue.length, done: 0, right: 0, wrong: 0, answered: false, firstTry: {}, startPct: progressOf(topic).pct, later: [], times: [] };\n  renderCard();\n}\n\nfunction renderEmpty(topic){\n  view = \"empty\";\n  const st = statsOf(topic);\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>${topicName(topic)}</h3></div></div>\n    <div class=\"done\">\n      <h2>Nada para revisar agora</h2>\n      <p>Você está em dia com ${topicName(topic).toLowerCase()}.</p>\n      <p>Próxima revisão ${isFinite(st.next) ? fmtUntil(st.next) : \"quando quiser\"}.</p>\n      <div class=\"row\">\n        <button class=\"ghost\" id=\"back2\">Voltar aos assuntos</button>\n        <button class=\"primary\" id=\"ahead\">Revisar mesmo assim</button>\n      </div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"back2\").onclick = renderHome;\n  document.getElementById(\"ahead\").onclick = () => startSession(topic, true);\n}\n\n/* embaralha as alternativas a cada aparição; \"todas/nenhuma das alternativas\" fica no fim */\nconst lastOrder = {};\nconst PINNED = /todas as alternativas|nenhuma das alternativas|todas as anteriores|nenhuma das anteriores/i;\nfunction optionOrder(q){\n  const idx = q[4].map((_, i) => i);\n  const pinned = idx.filter(i => PINNED.test(q[4][i]));\n  const free = idx.filter(i => !PINNED.test(q[4][i]));\n  const prev = (lastOrder[q[0]] || idx).join(\",\");\n  let order;\n  for (let t = 0; t < 8; t++){\n    order = shuffle(free).concat(pinned);\n    if (order.join(\",\") !== prev && free.length > 1) break;\n  }\n  lastOrder[q[0]] = order;\n  return order;\n}\n\nfunction renderCard(){\n  view = \"card\";\n  const q = session.queue[0];\n  if (DISC[q[0]]) return renderDiscCard();\n  session.disc = false;\n  session.answered = false;\n  session.order = optionOrder(q);\n  const pct = Math.round(session.done / (session.done + session.queue.length + session.later.length) * 100);\n  const s = state[q[0]];\n  const tag = !s ? \"Nova\" : (s.r === 0 ? \"Reaprendendo\" : \"Revisão\");\n  session.qStart = Date.now(); session.qTime = null;\n  const rest = session.queue.length, later = session.later.length;\n  app.innerHTML = `\n    <div class=\"topbar\">\n      <button class=\"back\" id=\"back\">Voltar</button>\n      <div class=\"t\"><h3>${topicName(session.topic)}</h3><div>${rest} ${rest === 1 ? \"questão restante\" : \"questões restantes\"}${later ? `, ${later} ${later === 1 ? \"agendada\" : \"agendadas\"} para voltar` : \"\"}</div></div>\n      <span class=\"timer\" id=\"qtimer\" title=\"Tempo nesta questão\">0:00</span>\n    </div>\n    <div class=\"bar\"><i style=\"width:${pct}%\"></i></div>\n    <div class=\"acc\" id=\"acc\">${accHTML()}</div>\n    <article class=\"qcard\">\n      <div class=\"src\"><span>${q[2]}</span><span class=\"tag\">${tag}</span></div>\n      <p class=\"qtext\">${q[3]}</p>\n      <div class=\"opts\" role=\"group\" aria-label=\"Alternativas\">\n        ${session.order.map((oi, pos) => `<button class=\"opt\" data-i=\"${oi}\"><span class=\"l\">${LETTERS[pos]}</span><span>${q[4][oi]}</span></button>`).join(\"\")}\n      </div>\n      <div class=\"fb\" id=\"fb\" aria-live=\"polite\"></div>\n    </article>\n    <div class=\"keys\">Atalhos: <kbd>A</kbd> a <kbd>D</kbd> para responder</div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  app.querySelectorAll(\".opt\").forEach(b => b.addEventListener(\"click\", () => answer(+b.dataset.i)));\n  window.scrollTo(0, 0);\n}\n\nfunction accHTML(){\n  const n = session.right + session.wrong;\n  const sp = n ? Math.round(session.right / n * 100) : null;\n  const tp = topicAcc(session.topic).pct;\n  const cls = v => v == null ? \"\" : v >= 70 ? \" good\" : v >= 50 ? \" mid\" : \" low\";\n  return `<div class=\"accbox${cls(sp)}\"><b>${sp == null ? \"–\" : sp + \"%\"}</b><span>acerto nesta sessão${n ? ` (${session.right} de ${n})` : \"\"}</span></div>\n    <div class=\"accbox${cls(tp)}\"><b>${tp == null ? \"–\" : tp + \"%\"}</b><span>seu acerto geral neste assunto</span></div>`;\n}\n\nfunction answer(i){\n  if (!session || session.answered) return;\n  const q = session.queue[0];\n  session.qTime = Date.now() - session.qStart;\n  session.times.push(session.qTime);\n  answerCore(i);\n  track(q[0], i === q[5]);\n  tick();\n  const el = document.getElementById(\"acc\");\n  if (el) el.innerHTML = accHTML();\n}\n\nfunction answerCore(i){\n  if (session.answered) return;\n  session.answered = true;\n  const q = session.queue[0];\n  const correct = i === q[5];\n  if (!(q[0] in session.firstTry)) session.firstTry[q[0]] = correct;\n  app.querySelectorAll(\".opt\").forEach(b => {\n    const k = +b.dataset.i;\n    b.disabled = true;\n    if (k === q[5]) b.classList.add(\"right\");\n    else if (k === i) b.classList.add(\"wrong\");\n    else b.classList.add(\"dim\");\n  });\n  addReasons(q, i);\n  const fb = document.getElementById(\"fb\");\n  const keys = document.querySelector(\".keys\");\n  if (correct){\n    session.right++;\n    const s = Object.assign(blank(), state[q[0]] || {});\n    const streak = state[q[0]] ? state[q[0]].r + 1 : 1;\n    fb.innerHTML = `\n      <div class=\"verdict ok\">Acertou!</div>\n      ${streak >= 2 ? cheerHTML(streak) : \"\"}\n      ${explainHTML(q)}\n      <div class=\"rate\">\n        <p>Como foi responder essa?</p>\n        <div class=\"rbtns\">\n          <button class=\"rbtn hard\" data-g=\"hard\">Difícil<small>volta em ${intervalLabel(s, \"hard\")}</small></button>\n          <button class=\"rbtn good\" data-g=\"good\">Médio<small>volta em ${intervalLabel(s, \"good\")}</small></button>\n          <button class=\"rbtn easy\" data-g=\"easy\">Fácil<small>volta em ${intervalLabel(s, \"easy\")}</small></button>\n        </div>\n        ${customBlock()}\n      </div>`;\n    fb.querySelectorAll(\".rbtn\").forEach(b => b.addEventListener(\"click\", () => rate(b.dataset.g)));\n    bindCustom();\n    if (streak >= 2) burst(streak);\n    keys.innerHTML = `Atalhos: <kbd>1</kbd> difícil, <kbd>2</kbd> médio, <kbd>3</kbd> fácil`;\n  } else {\n    session.wrong++;\n    fb.innerHTML = `\n      <div class=\"verdict no\">Errou. A correta é a ${LETTERS[session.order.indexOf(q[5])]}.</div>\n      ${explainHTML(q)}\n      <button class=\"primary\" id=\"cont\">Continuar (ela volta daqui a pouco)</button>\n      ${customBlock()}`;\n    document.getElementById(\"cont\").addEventListener(\"click\", () => rate(\"again\"));\n    bindCustom();\n    keys.innerHTML = `Atalho: <kbd>Enter</kbd> para continuar`;\n  }\n}\n\nfunction pick(arr){ return arr[Math.floor(Math.random() * arr.length)]; }\n\nfunction cheerHTML(n){\n  let big, lvl;\n  if (n === 2){ big = pick([\"Acertou de novo!\", \"Segunda vez seguida!\", \"De novo! Está fixando.\"]); lvl = 2; }\n  else if (n === 3){ big = pick([\"Três seguidas! Essa já é sua.\", \"Terceira vez! Muito bom.\", \"Três de três!\"]); lvl = 3; }\n  else { big = n + \" acertos seguidos! \" + pick([\"Questão dominada.\", \"Na prova essa não escapa.\", \"Você está voando.\"]); lvl = 4; }\n  const sub = pick([\"A revisão espaçada está funcionando.\", \"Continue assim.\", \"É assim que o conteúdo fica na memória.\", \"Seu eu da prova agradece.\"]);\n  const dots = Array.from({ length: Math.min(n, 6) }, (_, i) => `<i style=\"animation-delay:${(0.08 * i + 0.15).toFixed(2)}s\"></i>`).join(\"\");\n  return `<div class=\"cheer lvl${lvl}\" role=\"status\">\n    <div class=\"dots\" aria-hidden=\"true\">${dots}</div>\n    <div><div class=\"big\">${big}</div><div class=\"sub\">${sub}</div></div>\n  </div>`;\n}\n\nfunction burst(n){\n  if (window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return;\n  const anchor = document.querySelector(\".cheer\") || document.querySelector(\".verdict\");\n  if (!anchor) return;\n  const r = anchor.getBoundingClientRect();\n  const x = r.left + Math.min(60, r.width / 2), y = r.top + r.height / 2;\n  const count = n === 2 ? 26 : n === 3 ? 42 : 60;\n  const reach = n === 2 ? 150 : n === 3 ? 210 : 270;\n  const colors = [\"var(--eosin)\", \"var(--eosin-soft)\", \"var(--hema)\", \"var(--hema-soft)\", \"#F2B6CC\"];\n  const box = document.createElement(\"div\");\n  box.className = \"burst\";\n  for (let i = 0; i < count; i++){\n    const a = Math.random() * Math.PI * 2;\n    const d = reach * (0.45 + Math.random() * 0.55);\n    const size = 6 + Math.random() * (n >= 3 ? 12 : 9);\n    const b = document.createElement(\"span\");\n    b.className = \"bit\" + (size > 11 ? \" cell\" : \"\");\n    b.style.cssText = `--x:${x}px;--y:${y}px;--s:${size}px;--c:${pick(colors)};` +\n      `--dx:${Math.cos(a) * d}px;--dy:${Math.sin(a) * d + 40}px;--r:${Math.round(Math.random() * 360)}deg;` +\n      `--t:${0.9 + Math.random() * 0.6}s;animation-delay:${Math.random() * 0.12}s`;\n    box.appendChild(b);\n  }\n  document.body.appendChild(box);\n  setTimeout(() => box.remove(), 1900);\n}\n\nfunction explainHTML(q, order){\n  order = order || session.order;\n  const L = LETTERS[order.indexOf(q[5])];\n  const ex = EXTRA[q[0]];\n  return `<div class=\"expl\"><div class=\"eh\">Por que a ${L} está certa</div>${q[6]}</div>\n      ${ex && ex[1] ? `<div class=\"tip\"><div class=\"th\">Macete</div>${ex[1]}</div>` : \"\"}\n      ${refHTML(q[0])}`;\n}\n\nfunction addReasons(q, chosen){\n  const ex = EXTRA[q[0]];\n  if (!ex) return;\n  app.querySelectorAll(\".opt\").forEach(b => {\n    const k = +b.dataset.i;\n    if (k === q[5] || !ex[0][k]) return;\n    const d = document.createElement(\"span\");\n    d.className = \"why\";\n    d.innerHTML = (k === chosen ? \"<b>Você marcou.</b> \" : \"\") + ex[0][k];\n    b.lastElementChild.appendChild(d);\n  });\n}\n\nfunction customBlock(){\n  const prova = ritmo === \"prova\";\n  const opts = prova\n    ? [[0,\"Ainda nesta sessão\"],[15,\"15 min\"],[30,\"30 min\"],[60,\"1 h\"],[120,\"2 h\"],[240,\"4 h\"],[480,\"8 h\"]]\n    : [[0,\"Ainda nesta sessão\"],[1,\"1 dia\"],[3,\"3 dias\"],[7,\"1 semana\"],[14,\"2 semanas\"],[30,\"1 mês\"]];\n  return `<details class=\"custom\">\n    <summary>Prefiro escolher quando ela volta</summary>\n    <div class=\"chips\">${opts.map(o => `<button class=\"chip\" data-d=\"${o[0]}\">${o[1]}</button>`).join(\"\")}</div>\n    <div class=\"own\">\n      <label for=\"ownDays\">Ou digite:</label>\n      <input id=\"ownDays\" type=\"number\" min=\"1\" max=\"${prova ? 1440 : 365}\" inputmode=\"numeric\" placeholder=\"${prova ? 45 : 10}\">\n      <span>${prova ? \"minutos\" : \"dias\"}</span>\n      <button class=\"chip\" id=\"ownGo\">Confirmar</button>\n      <span class=\"err\" id=\"ownErr\" hidden>Digite um número de 1 a ${prova ? 1440 : 365}.</span>\n    </div>\n  </details>`;\n}\n\nfunction bindCustom(){\n  const unit = ritmo === \"prova\" ? \"min\" : \"dias\";\n  app.querySelectorAll(\".chip[data-d]\").forEach(b => b.addEventListener(\"click\", () => rate(\"custom\", +b.dataset.d, unit)));\n  const go = () => {\n    const n = parseInt(document.getElementById(\"ownDays\").value, 10);\n    const max = unit === \"min\" ? 1440 : 365;\n    if (!(n >= 1 && n <= max)){ document.getElementById(\"ownErr\").hidden = false; return; }\n    rate(\"custom\", n, unit);\n  };\n  document.getElementById(\"ownGo\").addEventListener(\"click\", go);\n  document.getElementById(\"ownDays\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\"){ e.preventDefault(); go(); } });\n}\n\nfunction rate(grade, customDays, unit){\n  const q = session.queue.shift();\n  schedule(q[0], grade, customDays, unit);\n  const again = grade === \"again\" || (grade === \"custom\" && customDays === 0);\n  if (again){\n    const pos = Math.min(3, session.queue.length);\n    session.queue.splice(pos, 0, q);\n  } else {\n    session.done++;\n    const due = state[q[0]].d;\n    if (due - Date.now() <= 12 * 60 * MIN) session.later.push({ q, due });   // volta ainda hoje, nesta sessão\n  }\n  nextCard();\n}\n\n/* próxima questão: primeiro as agendadas que já venceram, depois as da fila */\nfunction nextCard(){\n  const now = Date.now();\n  session.later.sort((a, b) => a.due - b.due);\n  const ready = [];\n  while (session.later.length && session.later[0].due <= now) ready.push(session.later.shift().q);\n  if (ready.length) session.queue = ready.concat(session.queue);\n  if (session.queue.length) renderCard();\n  else if (session.later.length) renderWaiting();\n  else renderEnd();\n}\n\nfunction renderWaiting(){\n  view = \"wait\";\n  const n = session.later.length;\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button>\n      <div class=\"t\"><h3>${topicName(session.topic)}</h3><div>${n} ${n === 1 ? \"questão agendada\" : \"questões agendadas\"} para voltar</div></div></div>\n    <div class=\"done\">\n      <h2>Pausa para a memória</h2>\n      <p>Você passou por todas as questões por agora. A próxima volta em</p>\n      <div class=\"bigclock\" id=\"waitclock\">--:--</div>\n      <p>Pode deixar esta tela aberta: a questão aparece sozinha na hora. Se sair, ela fica em \"para revisar\" no assunto.</p>\n      <div class=\"row\">\n        <button class=\"ghost\" id=\"endnow\">Encerrar sessão</button>\n        <button class=\"primary\" id=\"nowbtn\">Revisar agora</button>\n      </div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"endnow\").onclick = renderEnd;\n  document.getElementById(\"nowbtn\").onclick = () => { session.queue.push(session.later.shift().q); renderCard(); };\n  tick();\n}\n\nfunction fmtClock(ms){\n  const t = Math.max(0, Math.floor(ms / 1000));\n  const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), x = t % 60;\n  return h ? `${h}:${String(m).padStart(2, \"0\")}:${String(x).padStart(2, \"0\")}` : `${m}:${String(x).padStart(2, \"0\")}`;\n}\nfunction tick(){\n  if (view === \"card\" && session){\n    const el = document.getElementById(\"qtimer\");\n    if (el){ el.textContent = fmtClock(session.qTime != null ? session.qTime : Date.now() - session.qStart); el.classList.toggle(\"stopped\", session.qTime != null); }\n  } else if (view === \"wait\" && session){\n    if (!session.later.length){ nextCard(); return; }\n    const left = session.later[0].due - Date.now();\n    if (left <= 0){ nextCard(); return; }\n    const el = document.getElementById(\"waitclock\"); if (el) el.textContent = fmtClock(left + 999);\n  } else if (view === \"g-room\" && typeof groupTick === \"function\"){\n    groupTick();\n  }\n}\nsetInterval(tick, 500);\n\nfunction renderEnd(){\n  view = \"end\";\n  const ids = Object.keys(session.firstTry);\n  const first = ids.filter(id => session.firstTry[id]).length;\n  const st = statsOf(session.topic);\n  app.innerHTML = `\n    <div class=\"done\">\n      <h2>Sessão concluída</h2>\n      <p>${topicName(session.topic)}</p>\n      <div class=\"score\">\n        <div class=\"a\"><b>${first}</b><span>certas de primeira</span></div>\n        <div class=\"e\"><b>${ids.length - first}</b><span>erradas de primeira</span></div>\n        ${session.times && session.times.length ? `<div class=\"t\"><b>${fmtClock(session.times.reduce((a, b) => a + b, 0) / session.times.length)}</b><span>tempo médio por questão</span></div>` : \"\"}\n      </div>\n      ${progHTML(progressOf(session.topic), session.startPct)}\n      <p>Próxima revisão ${isFinite(st.next) ? fmtUntil(st.next) : \"quando quiser\"}.</p>\n      <div class=\"row\">\n        <button class=\"primary\" id=\"home\">Voltar aos assuntos</button>\n      </div>\n    </div>`;\n  document.getElementById(\"home\").onclick = renderHome;\n  animateBars();\n  window.scrollTo(0, 0);\n}\n\n/* =========================================================\n   DISCURSIVAS: resposta modelo + lista do que precisa ter\n   ========================================================= */\nconst DISC = {\n  d01: {\n    modelo: `<p><b>a)</b> Necrose gordurosa (necrose enzimática do tecido adiposo), típica da pancreatite aguda.</p>\n      <p><b>b) Mecanismo:</b> as enzimas pancreáticas ativadas extravasam. As lipases quebram os triglicerídeos dos adipócitos e liberam ácidos graxos, que se combinam com o cálcio e formam sabões de cálcio: é a <b>saponificação</b>.</p>\n      <p><b>Macroscopia:</b> focos branco-amarelados, opacos, com aspecto de giz (“pingos de vela”), no pâncreas e na gordura ao redor (peripancreática e mesentério).</p>\n      <p><b>Microscopia:</b> adipócitos necróticos com contornos celulares apagados, “sombreados” (sem núcleo); depósitos de cálcio basofílicos (roxo-azulados na H&amp;E); reação inflamatória ao redor (neutrófilos e macrófagos).</p>`,\n    erro: \"Hipertrofia e hiperplasia não entram nessa resposta. São adaptações celulares, não alterações da necrose. Na microscopia, descreva o que se vê no tecido necrosado.\",\n    check: [\n      \"Disse que é necrose gordurosa (enzimática)\",\n      \"Explicou que as lipases liberam ácidos graxos dos triglicerídeos\",\n      \"Citou a saponificação (ácidos graxos + cálcio)\",\n      \"Macro: áreas branco-amareladas, opacas, com aspecto de giz\",\n      \"Micro: contornos sombreados dos adipócitos necróticos\",\n      \"Micro: depósitos de cálcio basofílicos\",\n      \"Micro: reação inflamatória ao redor\"\n    ]\n  },\n  d02: {\n    modelo: `<p><b>a)</b> Necrose de coagulação (coagulativa), a necrose típica da isquemia em órgãos sólidos como o coração.</p>\n      <p><b>b) Mecanismo:</b> a isquemia desnatura as proteínas estruturais e também as enzimas, então a célula morre mas a digestão é lenta, e a arquitetura do tecido fica preservada por alguns dias.</p>\n      <p><b>Macroscopia:</b> área pálida (ou amarelada), firme e bem delimitada; depois de alguns dias pode surgir um halo avermelhado (hiperêmico) na borda.</p>\n      <p><b>Microscopia:</b> contornos das células e arquitetura do tecido preservados (“células fantasmas”); citoplasma mais eosinofílico (rosa intenso); alterações do núcleo: picnose, cariorrexe e cariólise; infiltrado de neutrófilos nas bordas nos primeiros dias, depois macrófagos.</p>`,\n    erro: \"Não confunda com a liquefativa: no coração a forma das células se mantém. Liquefativa é a do cérebro e dos abscessos.\",\n    check: [\n      \"Disse que é necrose de coagulação (coagulativa)\",\n      \"Explicou que as proteínas e enzimas se desnaturam\",\n      \"Macro: área pálida, firme e bem delimitada\",\n      \"Micro: arquitetura e contornos celulares preservados\",\n      \"Micro: citoplasma eosinofílico\",\n      \"Micro: picnose, cariorrexe e cariólise\",\n      \"Micro: neutrófilos nas bordas (inflamação)\"\n    ]\n  },\n  h07: {\n    modelo: `<p><b>a)</b> A inflamação é uma resposta protetora dos tecidos vascularizados: traz do sangue para o local lesado as células de defesa (leucócitos) e as proteínas plasmáticas (anticorpos, complemento), para eliminar a causa da lesão (micróbios, toxinas) e remover o tecido morto. Ela também prepara e inicia o reparo. Quando exagerada ou prolongada, pode causar dano.</p>\n      <p><b>b) Aguda:</b> início rápido (minutos a horas), curta duração (horas a poucos dias), edema e exsudato, predomínio de neutrófilos e sinais cardinais evidentes.</p>\n      <p><b>Crônica:</b> início insidioso, longa duração (semanas a anos), infiltrado de células mononucleares (linfócitos, plasmócitos e macrófagos), destruição tecidual e tentativa de reparo ao mesmo tempo (angiogênese e fibrose). Pode formar granulomas.</p>`,\n    erro: \"Não basta dizer “eliminar o agressor”: diga que a inflamação traz células e proteínas do sangue para o tecido e que ela prepara o reparo. Na diferença, cite o tempo E o tipo de célula.\",\n    check: [\"a) Resposta de defesa (protetora)\",\"a) Leva células e proteínas do sangue até o tecido lesado\",\"a) Elimina a causa, remove tecido morto e prepara o reparo\",\"b) Aguda: início rápido e curta duração\",\"b) Aguda: exsudato/edema e neutrófilos\",\"b) Crônica: longa duração e células mononucleares\",\"b) Crônica: destruição tecidual com reparo (angiogênese e fibrose)\"]\n  },\n  h08: {\n    modelo: `<p><b>a)</b> A matriz extracelular (colágeno, elastina, proteoglicanos, glicoproteínas como fibronectina e laminina, e a membrana basal) é o arcabouço do tecido: dá sustentação e ancoragem às células, guia a migração e a proliferação, guarda e apresenta fatores de crescimento e envia sinais às células (por meio das integrinas). Se a MEC está preservada, o tecido pode regenerar; se é destruída, o reparo acontece por cicatriz (deposição de colágeno).</p>\n      <p><b>b) Distúrbios do reparo:</b></p>\n      <p>1. <b>Formação deficiente da cicatriz:</b> deiscência da ferida e ulceração (ex.: infecção, diabetes, desnutrição, deficiência de vitamina C, que prejudica a síntese de colágeno).</p>\n      <p>2. <b>Formação excessiva:</b> cicatriz hipertrófica (colágeno em excesso, dentro dos limites da ferida) e queloide (ultrapassa os limites da ferida original).</p>\n      <p>3. <b>Granulação exuberante</b> (tecido de granulação em excesso, que impede a reepitelização) e <b>contratura</b> (contração exagerada, ex.: queimaduras, que deforma e limita o movimento).</p>`,\n    erro: \"Fibroblastos são células, não componentes da matriz. Na cicatriz hipertrófica o excesso é de colágeno dentro dos limites da ferida; no queloide ele passa dos limites.\",\n    check: [\"a) MEC como arcabouço: sustentação e ancoragem\",\"a) Guia a migração e a proliferação das células\",\"a) Guarda fatores de crescimento e sinaliza para as células\",\"a) MEC íntegra permite regeneração; destruída leva à cicatriz\",\"b) Cicatriz hipertrófica e queloide (com a diferença)\",\"b) Formação deficiente: deiscência/ulceração (ex.: vitamina C, diabetes)\",\"b) Granulação exuberante ou contratura\"]\n  },\n  n01: {\n    modelo: `<p><b>a) Via intrínseca (mitocondrial):</b> dano ao DNA, falta de fatores de sobrevivência ou estresse ativam sensores da família BH3-only (BIM, BID, PUMA, NOXA), que inibem as antiapoptóticas BCL-2 e BCL-XL e liberam BAX e BAK. BAX e BAK aumentam a permeabilidade da membrana mitocondrial, que libera o citocromo c. O citocromo c se liga à APAF-1, forma o apoptossomo e ativa a caspase-9 (iniciadora).</p>\n      <p><b>Via extrínseca (receptores de morte):</b> ligantes como FasL e TNF se ligam a receptores de morte (Fas/CD95, receptor de TNF). O receptor recruta a proteína adaptadora FADD pelo domínio de morte, e a FADD ativa a caspase-8 (iniciadora). A proteína FLIP bloqueia essa via. As duas vias convergem nas caspases executoras.</p>\n      <p><b>b)</b> BAX e BAK (os efetores) e as proteínas BH3-only (BIM, BID, BAD, PUMA, NOXA). O p53 também induz a apoptose após dano ao DNA.</p>\n      <p><b>c)</b> Executoras: caspases 3 e 6 (e também a 7). Iniciadoras: 8 (extrínseca) e 9 (intrínseca).</p>`,\n    erro: \"Na via extrínseca, quem se liga é o ligante (FasL) ao receptor (Fas); a FADD é uma proteína adaptadora. Não confunda iniciadoras (8 e 9) com executoras (3 e 6).\",\n    check: [\"Intrínseca: estresse ativa BH3-only e inibe BCL-2/BCL-XL\",\"Intrínseca: BAX e BAK aumentam a permeabilidade mitocondrial\",\"Intrínseca: citocromo c + APAF-1 (apoptossomo) ativam a caspase-9\",\"Extrínseca: FasL/TNF se ligam a receptores de morte\",\"Extrínseca: FADD ativa a caspase-8\",\"b) BAX e BAK (e BH3-only)\",\"c) Caspases executoras 3 e 6\"]\n  },\n  k07: {\n    modelo: `<p><b>a) Via extrínseca:</b> ligantes (FasL, expresso por linfócitos T, e TNF) se ligam aos receptores de morte (Fas/CD95, receptor de TNF). Os receptores se agrupam e, pelo domínio de morte citoplasmático, recrutam a proteína adaptadora FADD. A FADD recruta a pró-caspase-8, que se ativa em caspase-8 (iniciadora) e ativa as caspases executoras (3 e 6), que desmontam a célula. A FLIP bloqueia essa via.</p>\n      <p><b>b) Via intrínseca (mitocondrial):</b> não depende de receptor de morte, e sim do equilíbrio da família BCL-2. Com sinais de sobrevivência, BCL-2 e BCL-XL seguram BAX e BAK. Com dano ao DNA, falta de fatores de crescimento ou estresse, as proteínas BH3-only (BIM, BID, PUMA) inibem BCL-2/BCL-XL e ativam BAX/BAK, que abrem a membrana da mitocôndria. Sai o citocromo c, que se une à APAF-1 (apoptossomo) e ativa a caspase-9, e depois as executoras.</p>\n      <p><b>Ligação com o caso:</b> nos centros germinativos, os linfócitos B que não são selecionados morrem por apoptose (principalmente pela via intrínseca, por falta de sinal de sobrevivência). Os corpos apoptóticos são fagocitados pelos macrófagos, que viram os macrófagos de corpos tingíveis.</p>`,\n    erro: \"A via intrínseca não tem receptor de morte: ela depende da mitocôndria e do equilíbrio entre BCL-2/BCL-XL e BAX/BAK.\",\n    check: [\"Extrínseca: ligante (FasL/TNF) se liga ao receptor de morte\",\"Extrínseca: o domínio de morte recruta a FADD\",\"Extrínseca: ativação da caspase-8\",\"Intrínseca: estresse ou falta de sinal de sobrevivência; BH3-only inibem BCL-2/BCL-XL\",\"Intrínseca: BAX/BAK e saída do citocromo c\",\"Intrínseca: citocromo c + APAF-1 ativam a caspase-9\",\"As duas vias terminam nas caspases executoras e os corpos apoptóticos são fagocitados\"]\n  },\n  k08: {\n    modelo: `<p><b>a)</b> Inflamação crônica granulomatosa: granulomas (tubérculos) formados por macrófagos ativados com aspecto epitelioide, células gigantes multinucleadas do tipo Langhans (núcleos em ferradura na periferia), halo de linfócitos (e plasmócitos) e fibroblastos na periferia. No centro, necrose caseosa: material amorfo, eosinofílico e granular, sem contornos celulares. Os bacilos (BAAR) aparecem na coloração de Ziehl-Neelsen. Lesões antigas podem ter fibrose e calcificação.</p>\n      <p><b>b) Granuloma:</b> padrão de inflamação crônica; agregado compacto de macrófagos epitelioides (com células gigantes e linfócitos) que tenta isolar um agente difícil de eliminar; pode ter necrose central.</p>\n      <p><b>Tecido de granulação:</b> tecido de reparo (cicatrização), com vasos novos (angiogênese), fibroblastos proliferando, matriz frouxa e células inflamatórias; é vermelho e granuloso e evolui para cicatriz. Os nomes parecem, mas um é defesa (inflamação) e o outro é reparo.</p>`,\n    erro: \"Não confunda os nomes: tecido de granulação não tem nada a ver com granuloma. Um é reparo (vasos + fibroblastos), o outro é defesa (macrófagos epitelioides).\",\n    check: [\"a) Granulomas com macrófagos epitelioides\",\"a) Células gigantes multinucleadas (tipo Langhans)\",\"a) Halo de linfócitos\",\"a) Centro de necrose caseosa\",\"a) BAAR na coloração de Ziehl-Neelsen\",\"b) Granuloma: inflamação crônica, agregado de macrófagos que isola o agente\",\"b) Tecido de granulação: reparo, com vasos novos + fibroblastos + matriz frouxa\"]\n  },\n  s01: {\n    modelo: `<p><b>a)</b> Granuloma é um padrão de inflamação crônica: agregado microscópico de macrófagos ativados que se transformam em células epitelioides, muitas vezes com células gigantes multinucleadas (tipo Langhans ou tipo corpo estranho), cercado por linfócitos, plasmócitos e fibroblastos. Na tuberculose costuma ter necrose caseosa central. Função: conter e isolar um agente difícil de eliminar (micobactéria, fungo, corpo estranho), impedindo que se espalhe. Tipos: imune (depende de linfócitos T Th1 e IFN-γ, ex.: tuberculose) e de corpo estranho (material inerte, sem resposta T específica).</p>\n      <p><b>b) Ativação clássica (M1):</b> por produtos microbianos (LPS, via receptores Toll-like) e IFN-γ (de linfócitos Th1 e NK). Função microbicida e pró-inflamatória: produz espécies reativas de oxigênio, óxido nítrico, enzimas lisossômicas e citocinas (IL-1, IL-12, TNF).</p>\n      <p><b>Ativação alternativa (M2):</b> por IL-4 e IL-13. Função anti-inflamatória e de reparo: produz fatores de crescimento (TGF-β, PDGF) e IL-10, estimula angiogênese, fibroblastos e síntese de colágeno (fibrose).</p>`,\n    erro: \"O granuloma contém o agente, mas também destrói tecido, então não é só “benéfico”. Na letra b, cite o ativador de cada via (IFN-γ para M1, IL-4/IL-13 para M2) e a função.\",\n    check: [\"a) Agregado de macrófagos ativados/epitelioides (inflamação crônica)\",\"a) Células gigantes multinucleadas e halo de linfócitos\",\"a) Função: isolar e conter um agente difícil de eliminar\",\"a) Tipos: imune (ex.: tuberculose) e de corpo estranho\",\"b) M1 (clássica): ativada por IFN-γ e produtos microbianos\",\"b) M1: microbicida e pró-inflamatória (ERO, NO, citocinas)\",\"b) M2 (alternativa): IL-4/IL-13; anti-inflamatória e reparo\"]\n  },\n  s02: {\n    modelo: `<p><b>a)</b> Três mediadores bastam. Exemplos:</p>\n      <p><b>Histamina</b> (mastócitos): vasodilatação e aumento da permeabilidade das vênulas, na fase imediata.</p>\n      <p><b>Prostaglandinas</b> (via da COX): vasodilatação, dor e febre (PGE2).</p>\n      <p><b>Leucotrienos</b> (via da lipoxigenase): LTB4 atrai neutrófilos; C4, D4 e E4 aumentam a permeabilidade e causam broncoconstrição.</p>\n      <p><b>TNF e IL-1:</b> ativam o endotélio (moléculas de adesão), causam febre e a resposta de fase aguda.</p>\n      <p>Outros aceitos: quimiocinas (IL-8, quimiotaxia), bradicinina (permeabilidade e dor), complemento (C3a/C5a anafilatoxinas, C5a quimiotático, C3b opsonina), óxido nítrico (vasodilatação e morte de micróbios).</p>\n      <p><b>b) Fases do reparo:</b></p>\n      <p>1. <b>Hemostasia:</b> coágulo de fibrina, que serve de arcabouço provisório.</p>\n      <p>2. <b>Inflamação:</b> neutrófilos nas primeiras 24 a 48 h; depois macrófagos, que limpam e liberam fatores de crescimento.</p>\n      <p>3. <b>Proliferação</b> (a partir de 3 a 5 dias): tecido de granulação (angiogênese + fibroblastos + matriz) e reepitelização.</p>\n      <p>4. <b>Deposição de colágeno</b> e formação da cicatriz (fibroblastos estimulados por TGF-β).</p>\n      <p>5. <b>Remodelação</b> (semanas a meses): troca de colágeno III por I, contração da ferida (miofibroblastos) e ganho de resistência (cerca de 70 a 80% da pele normal em 3 meses).</p>`,\n    erro: \"Integrina e receptores Toll-like não são mediadores químicos: integrina é molécula de adesão do leucócito e TLR é o receptor que reconhece micróbios.\",\n    check: [\"a) Três mediadores com a origem ou via\",\"a) Função de cada um (vasodilatação, permeabilidade, quimiotaxia, febre, dor)\",\"b) Hemostasia: coágulo de fibrina\",\"b) Inflamação: neutrófilos e depois macrófagos\",\"b) Proliferação: tecido de granulação e reepitelização\",\"b) Deposição de colágeno e cicatriz\",\"b) Remodelação: colágeno III por I, contração e ganho de resistência\"]\n  },\n  u01: {\n    modelo: `<p><b>a) Aguda:</b> início rápido e curta duração; predomínio de neutrófilos; edema e exsudato evidentes; sinais cardinais intensos; lesão geralmente leve e autolimitada, que pode resolver sem sequela.</p>\n      <p><b>Crônica:</b> início lento e longa duração (semanas a anos); predomínio de linfócitos, plasmócitos e macrófagos; destruição tecidual progressiva com reparo ao mesmo tempo (angiogênese e fibrose); sinais locais discretos; pode formar granulomas (como na tuberculose do caso).</p>\n      <p><b>b) Apoptose:</b> morte programada, que pode ser fisiológica; a célula encolhe, a cromatina condensa e o núcleo se fragmenta; a membrana fica íntegra e formam-se corpos apoptóticos, fagocitados sem inflamação; depende de caspases; atinge células isoladas.</p>\n      <p><b>Necrose:</b> sempre patológica (isquemia, toxinas, infecção); a célula incha, a membrana se rompe, o conteúdo vaza e há inflamação; atinge grupos de células.</p>`,\n    erro: \"Na apoptose a célula é desmontada de forma organizada em corpos apoptóticos e fagocitada: não vaza conteúdo e não inflama. A resposta precisa comparar os dois lados (apoptose × necrose) em cada diferença.\",\n    check: [\"a) Tempo: aguda rápida e curta; crônica lenta e longa\",\"a) Células: neutrófilos × linfócitos, plasmócitos e macrófagos\",\"a) Aguda com exsudato; crônica com destruição + fibrose/angiogênese\",\"b) Tamanho: apoptose encolhe; necrose incha\",\"b) Membrana íntegra (corpos apoptóticos) × membrana rompida\",\"b) Sem inflamação × com inflamação\",\"b) Apoptose pode ser fisiológica; necrose é sempre patológica\"]\n  },\n  u02: {\n    modelo: `<p><b>a)</b> Inflamação crônica granulomatosa do tipo corpo estranho: granulomas com macrófagos epitelioides e células gigantes multinucleadas do tipo corpo estranho (núcleos espalhados), algumas englobando fibras da gaze (material refringente à luz polarizada); infiltrado de linfócitos e plasmócitos; fibrose, formando a pseudocápsula de tecido conjuntivo com fibroblastos e colágeno, e vasos neoformados. Pode haver neutrófilos se houver infecção junto. Não há necrose caseosa.</p>\n      <p><b>b) Granuloma:</b> padrão de inflamação crônica; agregado de macrófagos epitelioides (com células gigantes e linfócitos) que tenta isolar o agente.</p>\n      <p><b>Tecido de granulação:</b> tecido de reparo, com vasos novos, fibroblastos e matriz frouxa; é vermelho e granuloso e evolui para cicatriz. Um é defesa (inflamação); o outro é reparo.</p>`,\n    erro: \"Metaplasia, necrose e apoptose não descrevem essa lesão: gaze esquecida é o clássico granuloma de corpo estranho, sem resposta imune específica.\",\n    check: [\"a) Inflamação crônica granulomatosa do tipo corpo estranho\",\"a) Macrófagos epitelioides e células gigantes tipo corpo estranho\",\"a) Fibras da gaze (material refringente) nas células gigantes\",\"a) Linfócitos e plasmócitos; fibrose (pseudocápsula)\",\"b) Granuloma: agregado de macrófagos que isola o agente\",\"b) Tecido de granulação: vasos novos + fibroblastos + matriz frouxa\",\"b) Um é defesa (inflamação), o outro é reparo\"]\n  }\n\n};\nconst discDrafts = {};\n\nfunction renderDiscCard(){\n  const q = session.queue[0], D = DISC[q[0]];\n  session.disc = true; session.answered = false; session.order = [];\n  session.qStart = Date.now(); session.qTime = null;\n  const pct = Math.round(session.done / (session.done + session.queue.length + session.later.length) * 100);\n  const rest = session.queue.length, later = session.later.length;\n  const s = state[q[0]];\n  app.innerHTML = `\n    <div class=\"topbar\">\n      <button class=\"back\" id=\"back\">Voltar</button>\n      <div class=\"t\"><h3>${topicName(session.topic)}</h3><div>${rest} ${rest === 1 ? \"questão restante\" : \"questões restantes\"}${later ? `, ${later} ${later === 1 ? \"agendada\" : \"agendadas\"} para voltar` : \"\"}</div></div>\n      <span class=\"timer\" id=\"qtimer\" title=\"Tempo nesta questão\">0:00</span>\n    </div>\n    <div class=\"bar\"><i style=\"width:${pct}%\"></i></div>\n    <div class=\"acc\" id=\"acc\">${accHTML()}</div>\n    <article class=\"qcard disc\">\n      <div class=\"src\"><span>${q[2]}</span><span class=\"tag\">Discursiva${s ? \" · revisão\" : \"\"}</span></div>\n      <div class=\"qtext\">${q[3]}</div>\n      <label class=\"disc-l\" for=\"discTxt\">Sua resposta (escreva como escreveria na prova)</label>\n      <textarea id=\"discTxt\" rows=\"9\" placeholder=\"a) ...&#10;b) Macroscopia: ...&#10;Microscopia: ...\">${esc(discDrafts[q[0]] || \"\")}</textarea>\n      <button class=\"primary\" id=\"showModel\">Ver resposta modelo</button>\n      <div class=\"fb\" id=\"fb\" aria-live=\"polite\"></div>\n    </article>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  const ta = document.getElementById(\"discTxt\");\n  ta.addEventListener(\"input\", () => { discDrafts[q[0]] = ta.value; });\n  document.getElementById(\"showModel\").onclick = () => {\n    session.qTime = Date.now() - session.qStart; session.times.push(session.qTime); tick();\n    document.getElementById(\"showModel\").remove();\n    const fb = document.getElementById(\"fb\");\n    fb.innerHTML = `\n      <div class=\"expl\"><div class=\"eh\">Resposta modelo</div>${D.modelo}</div>\n      ${D.erro ? `<div class=\"tip warnbox\"><div class=\"th\">Atenção: erro comum</div>${D.erro}</div>` : \"\"}\n      <div class=\"checkl\"><div class=\"eh\">Marque o que a sua resposta tem</div>\n        ${D.check.map((c, i) => `<label><input type=\"checkbox\" data-c=\"${i}\"><span>${c}</span></label>`).join(\"\")}\n        <div class=\"ckscore\" id=\"ckscore\">Você marcou 0 de ${D.check.length}.</div>\n      </div>\n      ${refHTML(q[0])}\n      <div class=\"rate\"><p>Como foi a sua resposta?</p>\n        <div class=\"rbtns four\">\n          <button class=\"rbtn again\" data-g=\"again\">Errei<small>volta nesta sessão</small></button>\n          <button class=\"rbtn hard\" data-g=\"hard\">Difícil<small>volta em ${intervalLabel(s, \"hard\")}</small></button>\n          <button class=\"rbtn good\" data-g=\"good\">Médio<small>volta em ${intervalLabel(s, \"good\")}</small></button>\n          <button class=\"rbtn easy\" data-g=\"easy\">Fácil<small>volta em ${intervalLabel(s, \"easy\")}</small></button>\n        </div></div>`;\n    const upd = () => {\n      const n = fb.querySelectorAll(\".checkl input:checked\").length, tot = D.check.length;\n      const sug = n >= tot - 1 ? \"easy\" : n >= Math.ceil(tot * 0.6) ? \"good\" : n >= Math.ceil(tot * 0.3) ? \"hard\" : \"again\";\n      const nomes = { easy: \"Fácil\", good: \"Médio\", hard: \"Difícil\", again: \"Errei\" };\n      document.getElementById(\"ckscore\").innerHTML = `Você marcou <b>${n} de ${tot}</b>. Sugestão: <b>${nomes[sug]}</b>.`;\n      fb.querySelectorAll(\".rbtn\").forEach(b => b.classList.toggle(\"sug\", b.dataset.g === sug));\n    };\n    fb.querySelectorAll(\".checkl input\").forEach(c => c.addEventListener(\"change\", upd));\n    fb.querySelectorAll(\".rbtn\").forEach(b => b.onclick = () => {\n      const ok = b.dataset.g !== \"again\";\n      if (ok) session.right++; else session.wrong++;\n      if (!(q[0] in session.firstTry)) session.firstTry[q[0]] = ok;\n      track(q[0], ok);\n      rate(b.dataset.g);\n    });\n    fb.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n  };\n  window.scrollTo(0, 0);\n}\n\n/* =========================================================\n   MINHA EVOLUÇÃO\n   ========================================================= */\nlet acctInfo = () => \"\";   // a parte da conta preenche isso quando existir\n\nfunction totals(){\n  let a = 0, k = 0, dom = 0;\n  Object.keys(state).forEach(id => { const s = state[id]; a += s.a || 0; k += s.k || 0; if (s.r >= 3) dom++; });\n  const days = Object.keys(hist).filter(d => hist[d] && hist[d][0] > 0).sort();\n  let streak = 0;\n  const cur = new Date();\n  if (!(hist[dayKey(cur.getTime())] || [0])[0]) cur.setDate(cur.getDate() - 1);\n  while ((hist[dayKey(cur.getTime())] || [0])[0] > 0){ streak++; cur.setDate(cur.getDate() - 1); }\n  return { a, k, pct: a ? Math.round(k / a * 100) : null, dom, days: days.length, streak };\n}\n\nfunction evoLineHTML(){\n  const t = totals();\n  if (!t.a) return \"Responda algumas questões para acompanhar seu acerto e sua evolução.\";\n  return `${t.pct}% de acerto em ${t.a} ${t.a === 1 ? \"resposta\" : \"respostas\"}${t.streak > 1 ? `, ${t.streak} dias seguidos` : \"\"}.`;\n}\n\nfunction chartSVG(){\n  const N = 14, W = 340, H = 150, top = 22, bottom = 22, left = 6, gap = 4;\n  const bw = (W - left * 2 - gap * (N - 1)) / N;\n  const days = [];\n  for (let i = N - 1; i >= 0; i--){ const d = new Date(); d.setDate(d.getDate() - i); days.push(d); }\n  const vals = days.map(d => hist[dayKey(d.getTime())] || [0, 0]);\n  const max = Math.max(5, ...vals.map(v => v[0]));\n  const bars = vals.map((v, i) => {\n    const x = left + i * (bw + gap);\n    const h = v[0] ? Math.max(4, (H - top - bottom) * v[0] / max) : 0;\n    const y = H - bottom - h;\n    const pct = v[0] ? Math.round(v[1] / v[0] * 100) : null;\n    const color = pct == null ? \"var(--line)\" : pct >= 70 ? \"var(--ok)\" : pct >= 50 ? \"var(--hema)\" : \"var(--eosin)\";\n    const label = days[i].getDate() + \"/\" + (days[i].getMonth() + 1);\n    return `${v[0] ? `<rect x=\"${x.toFixed(1)}\" y=\"${y.toFixed(1)}\" width=\"${bw.toFixed(1)}\" height=\"${h.toFixed(1)}\" rx=\"3\" fill=\"${color}\"><title>${label}: ${v[0]} respostas, ${pct}% de acerto</title></rect>\n      <text x=\"${(x + bw / 2).toFixed(1)}\" y=\"${(y - 5).toFixed(1)}\" text-anchor=\"middle\" class=\"cv\">${pct}%</text>` :\n      `<rect x=\"${x.toFixed(1)}\" y=\"${H - bottom - 2}\" width=\"${bw.toFixed(1)}\" height=\"2\" rx=\"1\" fill=\"var(--line)\"/>`}\n      ${i % 2 === 1 || i === N - 1 ? `<text x=\"${(x + bw / 2).toFixed(1)}\" y=\"${H - 6}\" text-anchor=\"middle\" class=\"cd\">${i === N - 1 ? \"hoje\" : label}</text>` : \"\"}`;\n  }).join(\"\");\n  return `<svg class=\"chart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Respostas e acerto nos últimos 14 dias\">${bars}</svg>`;\n}\n\nfunction worstIds(){\n  return Object.keys(state).filter(id => VALID_IDS.has(id) && (state[id].a || 0) - (state[id].k || 0) >= 1)\n    .sort((x, y) => {\n      const ex = state[x].a - (state[x].k || 0), ey = state[y].a - (state[y].k || 0);\n      if (ey !== ex) return ey - ex;\n      return (state[x].k || 0) / state[x].a - (state[y].k || 0) / state[y].a;\n    }).slice(0, 8);\n}\n\nfunction renderEvolution(){\n  view = \"evo\";\n  const t = totals();\n  const info = acctInfo();\n  if (!t.a){\n    app.innerHTML = `<div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Minha evolução</h3></div></div>\n      <div class=\"panel\"><h2>Ainda não há dados</h2><p>Responda algumas questões e volte aqui para ver seu acerto, sua sequência de dias e as questões que você mais erra.</p>${info}</div>`;\n    document.getElementById(\"back\").onclick = renderHome;\n    return;\n  }\n  const topics = Object.keys(TOPICS).map(k => {\n    const acc = topicAcc(k);\n    return `<div class=\"evo-topic\"><div class=\"evo-th\"><b>${TOPICS[k].name}</b><span>${acc.pct == null ? \"sem respostas\" : `${acc.pct}% de acerto (${acc.k} de ${acc.a})`}</span></div>${progHTML(progressOf(k))}</div>`;\n  }).join(\"\");\n  const worst = worstIds();\n  const worstHTML = worst.length ? `<div class=\"panel evo-sec\">\n      <h2>Questões que você mais erra</h2>\n      <ul class=\"worst\">${worst.map(id => {\n        const q = QUESTIONS.find(x => x[0] === id), s = state[id];\n        const txt = q[3].length > 90 ? q[3].slice(0, 88) + \"…\" : q[3];\n        return `<li><span class=\"wq\">${txt}</span><span class=\"wn\">errou ${s.a - (s.k || 0)} de ${s.a}</span></li>`;\n      }).join(\"\")}</ul>\n      <button class=\"primary\" id=\"trainWorst\">Treinar só essas questões</button>\n    </div>` : \"\";\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Minha evolução</h3></div></div>\n    ${info}\n    <div class=\"kpis\">\n      <div class=\"kpi\"><b>${t.pct}%</b><span>de acerto geral</span></div>\n      <div class=\"kpi\"><b>${t.a}</b><span>${t.a === 1 ? \"resposta\" : \"respostas\"}</span></div>\n      <div class=\"kpi\"><b>${t.dom}</b><span>${t.dom === 1 ? \"questão dominada\" : \"questões dominadas\"}</span></div>\n      <div class=\"kpi\"><b>${t.streak}</b><span>${t.streak === 1 ? \"dia seguido\" : \"dias seguidos\"}</span></div>\n    </div>\n    <div class=\"panel evo-sec\">\n      <h2>Últimos 14 dias</h2>\n      <p class=\"evo-sub\">Altura: quantas questões você respondeu. Número: seu acerto no dia. Verde é 70% ou mais.</p>\n      ${chartSVG()}\n      <p class=\"evo-sub\">Você estudou em ${t.days} ${t.days === 1 ? \"dia\" : \"dias\"} no total.</p>\n    </div>\n    <div class=\"panel evo-sec\"><h2>Por assunto</h2>${topics}</div>\n    ${worstHTML}`;\n  document.getElementById(\"back\").onclick = renderHome;\n  const tw = document.getElementById(\"trainWorst\");\n  if (tw) tw.onclick = () => { customIds = new Set(worst); startSession(\"custom\", true); };\n  animateBars();\n  window.scrollTo(0, 0);\n}\n\n/* =========================================================\n   BACKUP DO PROGRESSO\n   ========================================================= */\nconst BK_PREFIX = \"PATON2-\";\nlet lastDecodedHist = null;\nconst VALID_IDS = new Set(QUESTIONS.map(q => q[0]));\n\nfunction encodeBackup(){\n  const rows = Object.keys(state).map(id => {\n    const s = state[id];\n    return [id, s.r, Math.round(s.e * 100), s.i, Math.round(s.d / MIN), s.l, s.n, s.a || 0, s.k || 0, Math.round((s.t || 0) / MIN)];\n  });\n  return BK_PREFIX + btoa(JSON.stringify({ r: rows, h: hist }));\n}\n\nfunction decodeBackup(code){\n  const clean = (code || \"\").replace(/\\s+/g, \"\");\n  lastDecodedHist = null;\n  let rows;\n  if (clean.startsWith(\"PATON1-\")) rows = JSON.parse(atob(clean.slice(7)));\n  else if (clean.startsWith(\"PATON2-\")){\n    const obj = JSON.parse(atob(clean.slice(7)));\n    rows = obj && obj.r;\n    if (obj && obj.h && typeof obj.h === \"object\") lastDecodedHist = obj.h;\n  } else throw new Error(\"formato\");\n  if (!Array.isArray(rows)) throw new Error(\"formato\");\n  const out = {};\n  rows.forEach(r => {\n    if (!Array.isArray(r) || !VALID_IDS.has(r[0])) return;\n    out[r[0]] = { r: +r[1] || 0, e: (+r[2] || 250) / 100, i: +r[3] || 0, d: (+r[4] || 0) * MIN, l: +r[5] || 0, n: +r[6] || 0,\n                  a: +r[7] || 0, k: +r[8] || 0, t: (+r[9] || 0) * MIN };\n  });\n  return out;\n}\n\nfunction renderBackupSave(){\n  view = \"backup\";\n  const n = Object.keys(state).length;\n  if (!n){\n    app.innerHTML = `\n      <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Backup do progresso</h3></div></div>\n      <div class=\"panel\">\n        <h2>Ainda não há progresso</h2>\n        <p>Responda algumas questões e depois volte aqui para salvar o backup.</p>\n      </div>`;\n    document.getElementById(\"back\").onclick = renderHome;\n    return;\n  }\n  const code = encodeBackup();\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Backup do progresso</h3></div></div>\n    <div class=\"panel\">\n      <h2>Seu código de backup</h2>\n      <p>Ele guarda o progresso de ${n} ${n === 1 ? \"questão\" : \"questões\"}. Copie e guarde em um lugar seguro, como o app de notas ou uma mensagem para você mesmo no WhatsApp. Para recuperar, use “Restaurar backup” em qualquer navegador ou celular.</p>\n      <textarea id=\"code\" readonly aria-label=\"Código de backup\">${code}</textarea>\n      <div class=\"row\">\n        <button class=\"primary\" id=\"copy\">Copiar código</button>\n        <button class=\"ghost\" id=\"back2\">Voltar aos assuntos</button>\n      </div>\n      <div id=\"msg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"back2\").onclick = renderHome;\n  const ta = document.getElementById(\"code\");\n  const ok = () => { document.getElementById(\"msg\").innerHTML = `<div class=\"msg ok\">Código copiado. Agora cole em um lugar seguro.</div>`; };\n  const manual = () => {\n    ta.focus(); ta.setSelectionRange(0, ta.value.length);\n    let copied = false;\n    try { copied = document.execCommand(\"copy\"); } catch(e){}\n    if (copied) ok();\n    else document.getElementById(\"msg\").innerHTML = `<div class=\"msg bad\">Não deu para copiar automaticamente. O código já está selecionado: segure em cima dele e toque em Copiar.</div>`;\n  };\n  document.getElementById(\"copy\").onclick = () => {\n    if (navigator.clipboard && navigator.clipboard.writeText){\n      navigator.clipboard.writeText(code).then(ok, manual);\n    } else manual();\n  };\n}\n\nfunction renderBackupLoad(){\n  view = \"backup\";\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Restaurar backup</h3></div></div>\n    <div class=\"panel\">\n      <h2>Restaurar um backup</h2>\n      <p>Cole abaixo o código que começa com PATON. O progresso deste navegador será substituído pelo do backup.</p>\n      <textarea id=\"code\" aria-label=\"Cole aqui o código de backup\" placeholder=\"Cole o código aqui\"></textarea>\n      <div class=\"row\">\n        <button class=\"primary\" id=\"restore\">Restaurar progresso</button>\n        <button class=\"ghost\" id=\"back2\">Voltar aos assuntos</button>\n      </div>\n      <div id=\"msg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"back2\").onclick = renderHome;\n  document.getElementById(\"restore\").onclick = () => {\n    const msg = document.getElementById(\"msg\");\n    let data;\n    try { data = decodeBackup(document.getElementById(\"code\").value); }\n    catch(e){ msg.innerHTML = `<div class=\"msg bad\">Esse código não é válido. Confira se copiou ele inteiro, começando por PATON.</div>`; return; }\n    const n = Object.keys(data).length;\n    if (!n){ msg.innerHTML = `<div class=\"msg bad\">Esse código não tem nenhuma questão salva.</div>`; return; }\n    if (Object.keys(state).length && !confirm(`Substituir o progresso deste navegador pelo backup (${n} questões)?`)) return;\n    state = data; if (lastDecodedHist) hist = lastDecodedHist; save();\n    msg.innerHTML = `<div class=\"msg ok\">Progresso restaurado: ${n} ${n === 1 ? \"questão\" : \"questões\"}.</div>`;\n  };\n}\n\n/* =========================================================\n   MODO EM GRUPO (Cloudflare)\n   A sala fica guardada no servidor: continua aberta mesmo que\n   todos fechem a página, e só acaba quando o dono encerra.\n   ========================================================= */\nconst roomStatus = /^https?:$/.test(location.protocol) ? \"ok\" : \"off\";\nlet group = null;\nconst NAME_KEY = \"patologia-n1-nome\";\nconst SALA_KEY = \"patologia-n1-sala\";\nconst DONO_KEY = \"patologia-n1-donos\";\n\nfunction esc(s){ return String(s == null ? \"\" : s).replace(/[&<>\"']/g, c => ({ \"&\":\"&amp;\", \"<\":\"&lt;\", \">\":\"&gt;\", '\"':\"&quot;\", \"'\":\"&#39;\" }[c])); }\nfunction loadJSON(k, d){ try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch(e){ return d; } }\nfunction saveJSON(k, v){ try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, JSON.stringify(v)); } catch(e){} }\nfunction getNameSaved(){ try { return localStorage.getItem(NAME_KEY) || \"\"; } catch(e){ return \"\"; } }\nfunction getName(){ return getNameSaved() || (typeof conta !== \"undefined\" && conta ? conta.user : \"\"); }\nfunction setName(n){ try { localStorage.setItem(NAME_KEY, n); } catch(e){} }\nfunction ownerKeys(){ return loadJSON(DONO_KEY, {}) || {}; }\nfunction setOwnerKey(code, key){ const o = ownerKeys(); if (key) o[code] = key; else delete o[code]; saveJSON(DONO_KEY, o); }\nfunction newCode(){ const A = \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\"; let c = \"\"; for (let i = 0; i < 4; i++) c += A[Math.floor(Math.random() * A.length)]; return c; }\nfunction newKey(){ return Array.from(crypto.getRandomValues(new Uint8Array(16)), b => b.toString(16).padStart(2, \"0\")).join(\"\"); }\nfunction cleanCode(s){ return String(s || \"\").toUpperCase().replace(/[^A-Z0-9]/g, \"\").slice(0, 4); }\nfunction validOrder(order, q){\n  if (!Array.isArray(order) || order.length !== q[4].length) return null;\n  const s = new Set(order);\n  return s.size === order.length && order.every(i => Number.isInteger(i) && i >= 0 && i < q[4].length) ? order : null;\n}\nfunction isOwner(){ return !!(group && group.key); }\nfunction saveSala(){ if (group) saveJSON(SALA_KEY, { code: group.code, name: group.name, ans: group.ans || null }); }\n\n/* ---------- Conexão com a sala ---------- */\nfunction gSend(obj){ if (group && group.ws && group.ws.readyState === 1) group.ws.send(JSON.stringify(obj)); }\nfunction gClose(){\n  if (!group) return;\n  const s = group.ws; group.ws = null; clearInterval(group.pingT);\n  if (s){ try { s.close(1000, \"saiu\"); } catch(e){} }\n}\nfunction rerender(chatBottom){ if (view !== \"g-room\") return; renderGroup(); renderChat(chatBottom); renderVoice(); syncVoice(); }\n\nfunction gConnect(){\n  const g = group; if (!g) return;\n  const proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n  const sock = new WebSocket(proto + \"//\" + location.host + \"/ws/\" + g.code);\n  g.ws = sock; g.online = false;\n  sock.onopen = () => {\n    if (group !== g || g.ws !== sock) return;\n    g.retry = 0; g.online = true;\n    gSend({ t: \"presence\", p: myPresence() });\n    gSend({ t: \"ident\", k: myIdentKey() });\n    if (g.key) gSend({ t: \"claim\", key: g.key });\n    clearInterval(g.pingT);\n    g.pingT = setInterval(() => { try { sock.send(\"ping\"); } catch(e){} }, 30000);\n    rerender(false);\n  };\n  sock.onmessage = e => {\n    if (group !== g || e.data === \"pong\") return;\n    let m; try { m = JSON.parse(e.data); } catch(err){ return; }\n    if (m.t === \"hello\"){\n      g.myPeer = m.peer; g.peers = m.peers || []; g.chat = (m.chat || []).slice(-50); g.seen = g.chat.length;\n      if (typeof m.now === \"number\") g.skew = m.now - Date.now();\n      if (voice.on){ Array.from(voice.pcs.keys()).forEach(closePeer); }\n      if (g.creating){\n        if (m.state){ recreate(); return; }          // código já usado: sorteia outro\n        g.state = null;\n        gSend(Object.assign({ t: \"create\", key: g.key }, g.creating));\n      } else if (!m.state){\n        g.notFound = true; g.state = null; forgetRoom(g.code);\n      } else {\n        g.state = m.state;\n      }\n      rerender(true);\n    } else if (m.t === \"peers\"){\n      g.peers = m.peers || []; rerender(false);\n    } else if (m.t === \"state\"){\n      if (typeof m.now === \"number\") g.skew = m.now - Date.now();\n      if (m.state === null){ g.ended = true; forgetRoom(g.code); leaveVoice(); }\n      else { g.state = m.state; g.creating = null; g.notFound = false; }\n      rerender(false);\n    } else if (m.t === \"chat\" && m.msg){\n      g.chat = g.chat.concat([m.msg]).slice(-50);\n      if (view === \"g-room\") renderChat(false);\n    } else if (m.t === \"sig\" && typeof m.from === \"string\"){\n      onSignal(m.from, m.data);\n    } else if (m.t === \"err\" && m.e === \"existe\" && g.creating){\n      recreate();\n    }\n  };\n  sock.onclose = () => {\n    if (group !== g || g.ws !== sock) return;\n    g.online = false; clearInterval(g.pingT);\n    if (!g.ended && !g.notFound){\n      const d = Math.min(8000, 500 * Math.pow(2, g.retry++));\n      setTimeout(() => { if (group === g && g.ws === sock) gConnect(); }, d);\n    }\n    if (view === \"g-room\") renderGroup();\n  };\n}\n\n/* ---------- Criar, entrar, sair ---------- */\nfunction createRoom(topic, name){\n  const pool = shuffle(roomCards(topic).map(q => q[0]));\n  const q = QUESTIONS.find(x => x[0] === pool[0]);\n  const code = newCode(), key = newKey();\n  setOwnerKey(code, key);\n  group = { code, name, key, retry: 0, peers: [], chat: [], state: undefined, ans: null,\n            creating: { topic, name, pool, idx: 0, qid: q[0], order: optionOrder(q) } };\n  saveSala();\n  view = \"g-room\"; renderGroup(); gConnect();\n}\nfunction recreate(){\n  const g = group; if (!g || !g.creating) return;\n  gClose(); setOwnerKey(g.code, null); group = null;\n  createRoom(g.creating.topic, g.name);\n}\nfunction joinRoom(code, name, ans){\n  group = { code, name, key: ownerKeys()[code] || null, retry: 0, peers: [], chat: [], state: undefined, ans: ans || null };\n  saveSala();\n  view = \"g-room\"; renderGroup(); gConnect();\n}\nfunction leaveRoom(){ leaveVoice(); gClose(); group = null; saveJSON(SALA_KEY, null); renderHome(); }\nfunction forgetRoom(code){ setOwnerKey(code, null); saveJSON(SALA_KEY, null); }\n\n/* ---------- Ações do dono ---------- */\nconst IDENT_KEY = \"patologia-n1-id\";\nfunction myIdentKey(){\n  let k = null;\n  try { k = localStorage.getItem(IDENT_KEY); } catch(e){}\n  if (!k){ k = newKey(); try { localStorage.setItem(IDENT_KEY, k); } catch(e){} }\n  return k;\n}\nfunction myPid(){ const me = (group && group.peers || []).find(p => p.peer === group.myPeer); return me ? me.pid : null; }\nfunction helperList(st){ return (st && st.helpers) || []; }\nfunction isHelperPid(st, pid){ return !!pid && (st.everyone === true || helperList(st).some(h => h[0] === pid)); }\n/* pode revelar e passar questões: o dono ou quem o dono liberou */\nfunction canControl(){ return isOwner() || (!!(group && group.state) && isHelperPid(group.state, myPid())); }\nfunction ownerCtl(a, extra){ gSend(Object.assign({ t: \"ctl\", key: group.key || null, a }, extra || {})); }\nfunction hostReveal(){ ownerCtl(\"reveal\"); }\nfunction hostBack(){ if (group && group.state) ownerCtl(\"back\", { cur: group.state.qid }); }\n/* ---------- Assuntos da sala (um ou vários, sem desfazer a sala) ---------- */\nfunction topicList(t){ if (!t || t === \"all\") return [\"all\"]; const l = String(t).split(\",\").filter(k => TOPICS[k]); return l.length ? l : [\"all\"]; }\nfunction roomTopicName(t){ const l = topicList(t); return l[0] === \"all\" ? \"Todos os assuntos\" : l.map(k => TOPICS[k].name).join(\" + \"); }\nfunction roomCards(t){ const l = topicList(t); return QUESTIONS.filter(q => !DISC[q[0]] && (l[0] === \"all\" || l.includes(q[1]))); }\nfunction inRoomTopics(id, t){ const l = topicList(t); if (l[0] === \"all\") return true; const q = QUESTIONS.find(x => x[0] === id); return !!q && l.includes(q[1]); }\n\nfunction hostSetTopic(sel, now){\n  const topic = !sel.length || sel.includes(\"all\") ? \"all\" : Object.keys(TOPICS).filter(k => sel.includes(k)).join(\",\");\n  const st = group.state, due = st.due || {};\n  const pool = shuffle(roomCards(topic).map(q => q[0]));\n  const payload = { topic, pool, idx: -1 };\n  if (now || !inRoomTopics(st.qid, topic)){\n    const t0 = serverNow();\n    const ready = Object.keys(due).filter(id => id !== st.qid && due[id][0] <= t0 && inRoomTopics(id, topic)).sort((a, b) => due[a][0] - due[b][0]);\n    let qid = null, idx = -1;\n    if (ready.length) qid = ready[0];\n    else {\n      let j = 0;\n      while (j < pool.length && (due[pool[j]] || pool[j] === st.qid)) j++;\n      if (j < pool.length){ qid = pool[j]; idx = j; }\n    }\n    if (!qid) qid = pool.find(id => id !== st.qid) || pool[0];\n    const q = QUESTIONS.find(x => x[0] === qid);\n    if (q) Object.assign(payload, { qid, order: optionOrder(q), idx });\n  }\n  ownerCtl(\"topic\", payload);\n  group.topicOpen = false;\n}\n\nfunction permPanelHTML(st){\n  const g = group;\n  const helpers = helperList(st);\n  const online = (g.peers || []).filter(p => p.presence && p.presence.name && !p.owner && p.pid);\n  const rows = online.map(p => [p.pid, p.presence.name, true]);\n  helpers.forEach(h => { if (!rows.some(r => r[0] === h[0])) rows.push([h[0], h[1], false]); });\n  const everyone = st.everyone === true;\n  return `<div class=\"topicpanel permpanel\">\n    <p>Quem você liberar pode <b>revelar a resposta</b> e <b>escolher quando a questão volta</b>. Mudar assunto, dar permissão e encerrar a sala continuam só com você.</p>\n    <label class=\"permall\"><input type=\"checkbox\" id=\"permAll\" ${everyone ? \"checked\" : \"\"}><span>Todos da sala podem revelar</span></label>\n    ${rows.length ? `<div class=\"tchecks\">${rows.map(r => `<label class=\"${everyone ? \"dim\" : \"\"}\"><input type=\"checkbox\" data-pid=\"${r[0]}\" data-name=\"${esc(r[1])}\" ${helpers.some(h => h[0] === r[0]) ? \"checked\" : \"\"} ${everyone ? \"disabled\" : \"\"}><span>${esc(r[1] || \"Alguém\")}${r[2] ? \"\" : \" (fora da sala)\"}</span></label>`).join(\"\")}</div>`\n      : `<div class=\"gstatus\" style=\"text-align:left\">Ainda não entrou ninguém além de você.</div>`}\n  </div>`;\n}\nfunction sendPerm(){\n  const boxes = Array.from(app.querySelectorAll(\".permpanel .tchecks input\"));\n  const helpers = boxes.filter(b => b.checked).map(b => [b.dataset.pid, b.dataset.name || \"\"]);\n  const everyone = !!(document.getElementById(\"permAll\") || {}).checked;\n  ownerCtl(\"perm\", { helpers, everyone });\n}\n\nfunction topicBarHTML(st, amOwner){\n  const g = group;\n  const btn = amOwner ? `<span class=\"tbtns\"><button class=\"vbtn\" id=\"permBtn\">${g.permOpen ? \"Fechar\" : \"Quem pode revelar\"}</button><button class=\"vbtn\" id=\"topicBtn\">${g.topicOpen ? \"Fechar\" : \"Mudar assunto\"}</button></span>` : \"\";\n  let panel = \"\";\n  if (amOwner && g.topicOpen){\n    const cur = g.topicSel || topicList(st.topic);\n    const all = cur.includes(\"all\");\n    panel = `<div class=\"topicpanel\">\n      <p>Escolha um ou mais assuntos. A sala continua: as pessoas, a conversa e a agenda de revisão ficam como estão.</p>\n      <div class=\"tchecks\">\n        ${Object.keys(TOPICS).map(k => `<label><input type=\"checkbox\" data-t=\"${k}\" ${all || cur.includes(k) ? \"checked\" : \"\"}><span>${TOPICS[k].name}</span></label>`).join(\"\")}\n      </div>\n      <div class=\"row\" style=\"justify-content:flex-start;margin-top:10px\">\n        <button class=\"primary\" id=\"topicNow\" style=\"width:auto;margin:0\">Ir agora para o novo assunto</button>\n        <button class=\"ghost\" id=\"topicNext\">Trocar a partir da próxima questão</button>\n      </div>\n      <div class=\"gstatus\" id=\"topicMsg\"></div>\n    </div>`;\n  }\n  return `<div class=\"topicbar\"><span>Assunto: <b>${esc(roomTopicName(st.topic))}</b></span>${btn}</div>${panel}${amOwner && g.permOpen ? permPanelHTML(st) : \"\"}`;\n}\n\nfunction bindTopicBar(st){\n  const g = group;\n  const b = document.getElementById(\"topicBtn\");\n  if (b) b.onclick = () => { g.topicOpen = !g.topicOpen; g.permOpen = false; g.topicSel = topicList(st.topic).includes(\"all\") ? Object.keys(TOPICS) : topicList(st.topic); renderGroup(); };\n  const pb = document.getElementById(\"permBtn\");\n  if (pb) pb.onclick = () => { g.permOpen = !g.permOpen; g.topicOpen = false; renderGroup(); };\n  const pa = document.getElementById(\"permAll\"); if (pa) pa.onchange = sendPerm;\n  app.querySelectorAll(\".permpanel .tchecks input\").forEach(c => c.onchange = sendPerm);\n  const boxes = app.querySelectorAll(\".tchecks input[data-t]\");\n  boxes.forEach(c => c.onchange = () => { g.topicSel = Array.from(boxes).filter(x => x.checked).map(x => x.dataset.t); });\n  const go = now => {\n    const sel = (g.topicSel || []).filter(k => TOPICS[k]);\n    if (!sel.length){ document.getElementById(\"topicMsg\").textContent = \"Marque pelo menos um assunto.\"; return; }\n    hostSetTopic(sel.length === Object.keys(TOPICS).length ? [\"all\"] : sel, now);\n  };\n  const n = document.getElementById(\"topicNow\"); if (n) n.onclick = () => go(true);\n  const x = document.getElementById(\"topicNext\"); if (x) x.onclick = () => go(false);\n}\n\n/* Revisão da sala (véspera de prova): Errei 5 min, Difícil 15 min (não cresce),\n   Médio 30 min → 1 h → 2 h, Fácil 1 h → 2 h → 4 h */\nconst serverNow = () => Date.now() + ((group && group.skew) || 0);\nfunction roomDue(){ return (group && group.state && group.state.due) || {}; }\nfunction grpMins(grade, r){ return provaMins({ r: r || 0 }, grade); }\n\nfunction hostRate(grade){\n  const st = group.state;\n  const now = serverNow();\n  const due = Object.assign({}, st.due || {});\n  const prevR = due[st.qid] ? due[st.qid][1] : 0;\n  const newR = grade === \"again\" ? 0 : grade === \"hard\" ? prevR : prevR + 1;\n  due[st.qid] = [now + grpMins(grade, prevR) * MIN, newR];\n\n  let pool = Array.isArray(st.pool) && st.pool.length ? st.pool : shuffle(roomCards(st.topic).map(q => q[0]));\n  let idx = st.idx || 0, qid = null;\n  const ready = Object.keys(due).filter(id => id !== st.qid && due[id][0] <= now && inRoomTopics(id, st.topic)).sort((a, b) => due[a][0] - due[b][0]);\n  if (ready.length) qid = ready[0];                       // 1º: revisões que já venceram\n  else {\n    let j = idx + 1;\n    while (j < pool.length && due[pool[j]]) j++;\n    if (j < pool.length){ qid = pool[j]; idx = j; }       // 2º: questões novas\n  }\n  if (!qid){                                              // 3º: tudo visto, pega a revisão mais próxima\n    const fut = Object.keys(due).filter(id => id !== st.qid && inRoomTopics(id, st.topic)).sort((a, b) => due[a][0] - due[b][0]);\n    if (!fut.length){ const pl = pool.filter(id => id !== st.qid); if (pl.length) fut.push(pl[Math.floor(Math.random() * pl.length)]); }\n    qid = fut[0] || st.qid;\n  }\n  const q = QUESTIONS.find(x => x[0] === qid);\n  if (!q) return;\n  ownerCtl(\"next\", { idx, qid, order: optionOrder(q), pool: st.pool && st.pool.length ? null : pool, due, cur: st.qid });\n}\n\nfunction roomQueueInfo(st){\n  const now = serverNow(), due = st.due || {};\n  let agora = 0, depois = 0, prox = Infinity;\n  Object.keys(due).forEach(id => { if (id === st.qid || !inRoomTopics(id, st.topic)) return; if (due[id][0] <= now) agora++; else { depois++; prox = Math.min(prox, due[id][0]); } });\n  const pool = st.pool || [];\n  let novas = 0;\n  for (let i = (st.idx || 0) + 1; i < pool.length; i++) if (!due[pool[i]]) novas++;\n  return { agora, depois, novas, prox };\n}\n\nfunction groupTick(){\n  if (!group || !group.state) return;\n  const st = group.state;\n  const el = document.getElementById(\"gtimer\");\n  if (el && st.qStart){\n    const end = st.phase === \"rev\" && st.revAt ? st.revAt : serverNow();\n    el.textContent = fmtClock(end - st.qStart);\n    el.classList.toggle(\"stopped\", st.phase === \"rev\");\n  }\n  const qi = document.getElementById(\"gqueue\");\n  if (qi) qi.innerHTML = queueHTML(st);\n}\nfunction queueHTML(st){\n  const i = roomQueueInfo(st);\n  return `<span><b>${i.agora}</b> para revisar agora</span><span><b>${i.depois}</b> ${i.depois === 1 ? \"volta\" : \"voltam\"} depois${isFinite(i.prox) ? ` (próxima em ${fmtClock(i.prox - serverNow() + 999)})` : \"\"}</span><span><b>${i.novas}</b> ${i.novas === 1 ? \"nova\" : \"novas\"}</span>`;\n}\nfunction hostEnd(){\n  if (confirm(\"Encerrar a sala para todo mundo? A conversa também será apagada.\")) ownerCtl(\"end\");\n}\nfunction pickAnswer(qid, i){\n  group.ans = { q: qid, c: i };\n  group.ansHist = group.ansHist || {};\n  group.ansHist[qid] = i;\n  saveSala();\n  sendPresence();\n  renderGroup();\n}\n\n/* ---------- Entrada na tela inicial ---------- */\nfunction groupEntryHTML(){\n  const off = roomStatus === \"off\";\n  const sub = off ? \"Funciona pelo link do site. No arquivo baixado, use o estudo individual abaixo.\"\n                  : \"Crie uma sala ou entre com o código. A sala continua aberta até o dono encerrar.\";\n  return `<button class=\"group-entry\" id=\"groupBtn\" ${off ? \"disabled\" : \"\"}>\n    <span class=\"gi\" aria-hidden=\"true\"><i></i><i></i><i></i></span>\n    <span><h2>Estudar em grupo</h2><p>${sub}</p></span>\n  </button>`;\n}\nfunction refreshGroupEntry(){\n  const el = document.getElementById(\"groupSlot\");\n  if (!el) return;\n  el.innerHTML = groupEntryHTML();\n  const b = document.getElementById(\"groupBtn\");\n  if (b && !b.disabled) b.onclick = renderLobby;\n}\n\n/* ---------- Lobby ---------- */\nfunction renderLobby(){\n  view = \"g-lobby\";\n  app.classList.remove(\"in-room\", \"chat-open\");\n  const mine = Object.keys(ownerKeys());\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Estudar em grupo</h3></div></div>\n    <div class=\"panel\">\n      <h2>Estudo em grupo</h2>\n      <p>Quem cria a sala é o dono: escolhe o assunto, revela as respostas e passa as questões. Os outros entram com o código. A sala continua aberta mesmo que alguém feche a página, até o dono encerrar. O modo em grupo não mexe no seu progresso individual.</p>\n      <div class=\"field\"><label for=\"gname\">Seu nome na sala</label><input id=\"gname\" maxlength=\"24\" placeholder=\"Ex.: Marco\" value=\"${esc(getName())}\"></div>\n      <div class=\"field\"><label for=\"gcode\">Entrar numa sala</label>\n        <div class=\"row\" style=\"justify-content:flex-start;margin:0\"><input id=\"gcode\" class=\"code\" maxlength=\"4\" placeholder=\"CÓDIGO\" autocomplete=\"off\"><button class=\"primary\" id=\"join\" style=\"width:auto;margin:0\">Entrar</button></div>\n      </div>\n      ${mine.length ? `<div class=\"field\" style=\"margin:4px 0 0\"><label>Salas que você criou</label><div class=\"rooms\">${mine.map(c => `<div class=\"roomrow\"><span><b>${esc(c)}</b> você é o dono</span><button class=\"ghost\" data-c=\"${esc(c)}\" style=\"padding:6px 12px\">Voltar</button></div>`).join(\"\")}</div></div>` : \"\"}\n      <div class=\"sep\"></div>\n      <div class=\"field\" style=\"margin-bottom:0\"><label>Ou crie uma sala e escolha o assunto</label>\n        <div class=\"topic-pick\">\n          ${Object.keys(TOPICS).map(k => `<button data-t=\"${k}\">${TOPICS[k].name}</button>`).join(\"\")}\n          <button data-t=\"all\">Todos os assuntos</button>\n        </div>\n      </div>\n      <div id=\"gmsg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  const needName = () => {\n    const n = document.getElementById(\"gname\").value.trim().slice(0, 24);\n    if (!n){ document.getElementById(\"gmsg\").innerHTML = `<div class=\"msg bad\">Coloque seu nome para a turma saber quem é quem.</div>`; document.getElementById(\"gname\").focus(); return null; }\n    setName(n); return n;\n  };\n  document.getElementById(\"join\").onclick = () => {\n    const n = needName(); if (!n) return;\n    const c = cleanCode(document.getElementById(\"gcode\").value);\n    if (c.length !== 4){ document.getElementById(\"gmsg\").innerHTML = `<div class=\"msg bad\">O código tem 4 letras ou números.</div>`; return; }\n    joinRoom(c, n);\n  };\n  document.getElementById(\"gcode\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\") document.getElementById(\"join\").click(); });\n  app.querySelectorAll(\".rooms button[data-c]\").forEach(b => b.onclick = () => { const n = needName(); if (n) joinRoom(b.dataset.c, n); });\n  app.querySelectorAll(\".topic-pick button\").forEach(b => b.onclick = () => { const n = needName(); if (n) createRoom(b.dataset.t, n); });\n}\n\n/* ---------- Painel da sala: conversa + voz ---------- */\nconst isWide = () => window.matchMedia(\"(min-width: 760px)\").matches;\n\nfunction gTarget(){\n  let main = document.getElementById(\"gmain\");\n  if (main) return main;\n  app.classList.add(\"in-room\");\n  app.innerHTML = `<div class=\"room-grid\"><div id=\"gmain\"></div>\n    <aside class=\"side\" id=\"chatBox\" aria-label=\"Conversa e voz da sala\" hidden>\n      <div class=\"chat-h\">\n        <button class=\"chat-toggle\" id=\"chatToggle\" aria-expanded=\"false\"><span>Conversa</span><span class=\"badge\" id=\"chatBadge\" hidden></span><span class=\"prev\" id=\"chatPrev\"></span></button>\n        <div class=\"voice-ctl\" id=\"voiceCtl\"></div>\n      </div>\n      <div class=\"voice-list\" id=\"voiceList\"></div>\n      <div class=\"chat-log\" id=\"chatLog\"></div>\n      <div class=\"chat-in\">\n        <input id=\"chatText\" maxlength=\"300\" placeholder=\"Escreva para a sala...\" autocomplete=\"off\" enterkeyhint=\"send\">\n        <button class=\"primary\" id=\"chatSend\">Enviar</button>\n      </div>\n    </aside></div>`;\n  const send = () => {\n    const inp = document.getElementById(\"chatText\");\n    const t = inp.value.trim();\n    if (!t) return;\n    gSend({ t: \"chat\", text: t.slice(0, 300) });\n    inp.value = \"\"; inp.focus();\n  };\n  document.getElementById(\"chatSend\").onclick = send;\n  document.getElementById(\"chatText\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\"){ e.preventDefault(); send(); } });\n  document.getElementById(\"chatToggle\").onclick = () => {\n    if (isWide()) return;\n    const box = document.getElementById(\"chatBox\");\n    const open = !box.classList.contains(\"open\");\n    box.classList.toggle(\"open\", open);\n    app.classList.toggle(\"chat-open\", open);\n    document.getElementById(\"chatToggle\").setAttribute(\"aria-expanded\", String(open));\n    renderChat(true);\n  };\n  renderVoice();\n  return document.getElementById(\"gmain\");\n}\n\nconst CHAT_COLORS = [\"#6A4BC4\", \"#C93C74\", \"#1C7E60\", \"#B8641A\", \"#2A6FB0\", \"#8A3FA0\"];\nfunction chatColor(key){ let h = 0; for (const ch of String(key)) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return CHAT_COLORS[h % CHAT_COLORS.length]; }\nfunction hhmm(ts){ const d = new Date(ts); return String(d.getHours()).padStart(2, \"0\") + \":\" + String(d.getMinutes()).padStart(2, \"0\"); }\n\nfunction renderChat(forceBottom){\n  const box = document.getElementById(\"chatBox\"), log = document.getElementById(\"chatLog\");\n  if (!box || !log || !group) return;\n  box.hidden = !(group.state && !group.ended && !group.notFound);\n  const list = group.chat || [];\n  const open = isWide() || box.classList.contains(\"open\");\n  if (group.seen == null) group.seen = list.length;\n  if (open) group.seen = list.length;\n  const unread = Math.max(0, list.length - group.seen);\n  const badge = document.getElementById(\"chatBadge\"), prev = document.getElementById(\"chatPrev\");\n  badge.hidden = !unread; badge.textContent = unread;\n  const last = list[list.length - 1];\n  prev.textContent = last ? `${last.name}: ${last.text}` : \"\";\n  const nearBottom = log.scrollHeight - log.scrollTop - log.clientHeight < 60;\n  if (!list.length){ log.innerHTML = `<div class=\"chat-empty\">Ninguém falou nada ainda. Manda um oi!</div>`; return; }\n  log.innerHTML = list.map(m => {\n    const mine = m.peer === group.myPeer || (m.name === group.name && !group.peers.some(p => p.peer === m.peer && p.peer !== group.myPeer));\n    return `<div class=\"msg-row${mine ? \" mine\" : \"\"}\"><div class=\"bubble\">\n      ${mine ? \"\" : `<b style=\"color:${chatColor(m.name)}\">${esc(m.name)}</b>`}\n      <span class=\"txt\">${esc(m.text)}</span><time>${hhmm(m.ts)}</time></div></div>`;\n  }).join(\"\");\n  if (forceBottom || nearBottom) log.scrollTop = log.scrollHeight;\n}\n\n/* ---------- Voz (direto entre os aparelhos; o servidor só apresenta um ao outro) ---------- */\nconst VOICE_MAX = 6;\nlet VOICE_LEVEL = 0.02;   // volume a partir do qual o nome acende como \"falando\"\nconst ICE = [{ urls: [\"stun:stun.cloudflare.com:3478\", \"stun:stun.l.google.com:19302\"] }];\nconst voice = { on: false, muted: false, stream: null, pcs: new Map(), audios: new Map(), pend: new Map(), meters: new Map(), ctx: null, timer: null, err: \"\", needTap: false };\n\nfunction myPresence(){ return { name: group.name, ans: group.ans || null, voice: voice.on, muted: voice.muted }; }\nfunction sendPresence(){ if (group) gSend({ t: \"presence\", p: myPresence() }); }\n\nasync function joinVoice(){\n  if (voice.on || !group) return;\n  const others = (group.peers || []).filter(p => p.presence && p.presence.voice && p.peer !== group.myPeer).length;\n  if (others >= VOICE_MAX){ voice.err = `A voz está cheia (máximo de ${VOICE_MAX} pessoas).`; renderVoice(); return; }\n  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia || !window.RTCPeerConnection){\n    voice.err = \"Este navegador não permite usar o microfone aqui. Tente pelo Chrome ou Safari.\"; renderVoice(); return;\n  }\n  try {\n    voice.stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true }, video: false });\n  } catch(e){\n    voice.err = \"Não foi possível usar o microfone. Toque no cadeado ao lado do endereço do site e permita o microfone.\";\n    renderVoice(); return;\n  }\n  voice.on = true; voice.muted = false; voice.err = \"\"; voice.needTap = false;\n  try { voice.ctx = new (window.AudioContext || window.webkitAudioContext)(); if (voice.ctx.resume) voice.ctx.resume(); } catch(e){ voice.ctx = null; }\n  addMeter(\"me\", voice.stream);\n  voice.timer = setInterval(updateMeters, 200);\n  sendPresence(); syncVoice(); renderVoice();\n}\n\nfunction leaveVoice(){\n  if (!voice.on && !voice.stream) return;\n  voice.on = false; voice.muted = false;\n  Array.from(voice.pcs.keys()).forEach(closePeer);\n  if (voice.stream){ voice.stream.getTracks().forEach(t => t.stop()); voice.stream = null; }\n  clearInterval(voice.timer); voice.meters.clear();\n  if (voice.ctx){ try { voice.ctx.close(); } catch(e){} voice.ctx = null; }\n  sendPresence(); renderVoice();\n}\n\nfunction toggleMute(){\n  if (!voice.stream) return;\n  voice.muted = !voice.muted;\n  voice.stream.getAudioTracks().forEach(t => t.enabled = !voice.muted);\n  sendPresence(); renderVoice();\n}\n\nfunction closePeer(id){\n  const pc = voice.pcs.get(id);\n  if (pc){ try { pc.close(); } catch(e){} voice.pcs.delete(id); }\n  const a = voice.audios.get(id);\n  if (a){ a.srcObject = null; a.remove(); voice.audios.delete(id); }\n  voice.pend.delete(id); voice.meters.delete(id);\n}\n\nfunction makePeer(id){\n  const pc = new RTCPeerConnection({ iceServers: ICE });\n  voice.pcs.set(id, pc);\n  voice.stream.getTracks().forEach(t => pc.addTrack(t, voice.stream));\n  pc.onicecandidate = e => { if (e.candidate) gSend({ t: \"sig\", to: id, data: { type: \"cand\", c: e.candidate.toJSON ? e.candidate.toJSON() : e.candidate } }); };\n  pc.ontrack = e => {\n    let a = voice.audios.get(id);\n    if (!a){ a = document.createElement(\"audio\"); a.autoplay = true; a.setAttribute(\"playsinline\", \"\"); a.className = \"rtc-audio\"; document.body.appendChild(a); voice.audios.set(id, a); }\n    const st = e.streams && e.streams[0] ? e.streams[0] : new MediaStream([e.track]);\n    if (a.srcObject !== st){ a.srcObject = st; addMeter(id, st); }\n    const pr = a.play(); if (pr && pr.catch) pr.catch(() => { voice.needTap = true; renderVoice(); });\n  };\n  pc.onconnectionstatechange = () => {\n    if (pc.connectionState === \"failed\" && voice.pcs.get(id) === pc){ closePeer(id); setTimeout(syncVoice, 1500); }\n    renderVoice();\n  };\n  return pc;\n}\n\nasync function callPeer(id){\n  const pc = makePeer(id);\n  try {\n    await pc.setLocalDescription(await pc.createOffer());\n    gSend({ t: \"sig\", to: id, data: { type: \"offer\", sdp: pc.localDescription.sdp } });\n  } catch(e){ closePeer(id); }\n}\n\nasync function flushCands(id){\n  const pc = voice.pcs.get(id), list = voice.pend.get(id) || [];\n  voice.pend.delete(id);\n  for (const c of list){ try { await pc.addIceCandidate(c); } catch(e){} }\n}\n\nasync function onSignal(from, d){\n  if (!voice.on || !d || typeof d !== \"object\") return;\n  let pc = voice.pcs.get(from);\n  try {\n    if (d.type === \"offer\" && typeof d.sdp === \"string\"){\n      if (pc && pc.signalingState !== \"stable\"){ closePeer(from); pc = null; }\n      if (!pc) pc = makePeer(from);\n      await pc.setRemoteDescription({ type: \"offer\", sdp: d.sdp });\n      await pc.setLocalDescription(await pc.createAnswer());\n      gSend({ t: \"sig\", to: from, data: { type: \"answer\", sdp: pc.localDescription.sdp } });\n      flushCands(from);\n    } else if (d.type === \"answer\" && pc && typeof d.sdp === \"string\"){\n      await pc.setRemoteDescription({ type: \"answer\", sdp: d.sdp });\n      flushCands(from);\n    } else if (d.type === \"cand\" && d.c){\n      if (pc && pc.remoteDescription) await pc.addIceCandidate(d.c);\n      else { const l = voice.pend.get(from) || []; l.push(d.c); voice.pend.set(from, l); }\n    }\n  } catch(e){}\n}\n\n/* quem tem o código menor liga para quem tem o maior; assim ninguém liga duas vezes */\nfunction syncVoice(){\n  if (!voice.on || !group || !group.myPeer) return;\n  const me = group.myPeer;\n  const want = new Set((group.peers || []).filter(p => p.peer !== me && p.presence && p.presence.voice).map(p => p.peer));\n  Array.from(voice.pcs.keys()).forEach(id => { if (!want.has(id)) closePeer(id); });\n  want.forEach(id => { if (!voice.pcs.has(id) && me < id) callPeer(id); });\n}\n\nfunction addMeter(id, stream){\n  if (!voice.ctx) return;\n  try {\n    const src = voice.ctx.createMediaStreamSource(stream);\n    const an = voice.ctx.createAnalyser(); an.fftSize = 512;\n    src.connect(an);\n    voice.meters.set(id, { an, buf: new Uint8Array(an.fftSize) });\n  } catch(e){}\n}\nfunction updateMeters(){\n  voice.meters.forEach((m, id) => {\n    m.an.getByteTimeDomainData(m.buf);\n    let s = 0; for (let i = 0; i < m.buf.length; i++){ const x = (m.buf[i] - 128) / 128; s += x * x; }\n    const talking = Math.sqrt(s / m.buf.length) > VOICE_LEVEL && !(id === \"me\" && voice.muted);\n    document.querySelectorAll(`[data-vpeer=\"${id}\"]`).forEach(el => el.classList.toggle(\"talking\", talking));\n  });\n}\n\nfunction renderVoice(){\n  const ctl = document.getElementById(\"voiceCtl\"), vl = document.getElementById(\"voiceList\");\n  if (!ctl || !vl || !group) return;\n  ctl.innerHTML = voice.on\n    ? `<button class=\"vbtn mute${voice.muted ? \" on\" : \"\"}\" id=\"vMute\">${voice.muted ? \"Mudo\" : \"Mic ligado\"}</button><button class=\"vbtn leave\" id=\"vLeave\">Sair da voz</button>`\n    : `<button class=\"vbtn join\" id=\"vJoin\">Entrar na voz</button>`;\n  const inVoice = (group.peers || []).filter(p => p.presence && p.presence.voice);\n  const chips = inVoice.map(p => {\n    const me = p.peer === group.myPeer;\n    const pc = voice.pcs.get(p.peer);\n    const wait = voice.on && !me && (!pc || (pc.connectionState !== \"connected\" && pc.connectionState !== \"completed\"));\n    return `<span class=\"vchip${p.presence.muted ? \" muted\" : \"\"}${wait ? \" wait\" : \"\"}\" data-vpeer=\"${me ? \"me\" : p.peer}\"><span class=\"mic\"></span>${esc(p.presence.name)}${me ? \" (você)\" : \"\"}${p.presence.muted ? \" · mudo\" : wait ? \" · conectando\" : \"\"}</span>`;\n  }).join(\"\");\n  vl.innerHTML = (chips ? `<span>Na voz:</span>${chips}` : \"\")\n    + (voice.needTap ? `<button class=\"vbtn join\" id=\"vTap\">Toque para ouvir</button>` : \"\")\n    + (voice.err ? `<span class=\"verr\">${esc(voice.err)}</span>` : \"\");\n  const j = document.getElementById(\"vJoin\"); if (j) j.onclick = joinVoice;\n  const m = document.getElementById(\"vMute\"); if (m) m.onclick = toggleMute;\n  const l = document.getElementById(\"vLeave\"); if (l) l.onclick = leaveVoice;\n  const t = document.getElementById(\"vTap\"); if (t) t.onclick = () => { voice.needTap = false; voice.audios.forEach(a => { const p = a.play(); if (p && p.catch) p.catch(() => {}); }); renderVoice(); };\n}\n\n/* ---------- Tela da sala ---------- */\nfunction renderGroup(){\n  if (!group){ renderHome(); return; }\n  const g = group;\n  const T = gTarget();\n  const people = (g.peers || []).filter(p => p.presence && p.presence.name);\n  const line = g.online ? `${people.length} ${people.length === 1 ? \"pessoa\" : \"pessoas\"} na sala agora` : \"Reconectando...\";\n  const top = `<div class=\"topbar\"><button class=\"back\" id=\"back\">Sair da sala</button>\n      <div class=\"t\"><h3>Estudo em grupo</h3><div>${line}</div></div></div>\n    <div class=\"gbar\"><span>Código da sala:</span><span class=\"gcode\">${g.code}</span>${isOwner() ? `<span class=\"owner-tag\">você é o dono</span>` : \"\"}${g.state ? `<span class=\"timer\" id=\"gtimer\" title=\"Tempo nesta questão\">0:00</span>` : \"\"}</div>\n    ${g.state ? `<div class=\"qinfo\" id=\"gqueue\">${queueHTML(g.state)}</div>${topicBarHTML(g.state, isOwner())}` : \"\"}`;\n  const panel = (h, p, btn) => top + `<div class=\"panel\"><h2>${h}</h2><p>${p}</p>${btn || \"\"}</div>`;\n\n  if (g.ended){\n    T.innerHTML = panel(\"Sala encerrada\", \"O dono encerrou esta sala. Para estudar de novo, crie ou entre em outra sala.\", `<button class=\"primary\" id=\"done\">Voltar ao início</button>`);\n    const f = () => { forgetRoom(g.code); leaveRoom(); };\n    document.getElementById(\"back\").onclick = f; document.getElementById(\"done\").onclick = f;\n    renderChat(false); return;\n  }\n  if (g.notFound){\n    T.innerHTML = panel(\"Sala não encontrada\", \"Confira o código com quem criou a sala. Salas sem nenhum uso por 24 horas são apagadas automaticamente.\", `<button class=\"primary\" id=\"done\">Voltar</button>`);\n    const f = () => { forgetRoom(g.code); gClose(); group = null; renderLobby(); };\n    document.getElementById(\"back\").onclick = f; document.getElementById(\"done\").onclick = f;\n    renderChat(false); return;\n  }\n  if (!g.state){\n    T.innerHTML = panel(g.creating ? \"Criando a sala...\" : \"Entrando na sala...\", \"Só um instante.\");\n    document.getElementById(\"back\").onclick = leaveRoom;\n    renderChat(false); return;\n  }\n\n  const st = g.state;\n  const q = QUESTIONS.find(x => x[0] === st.qid);\n  if (!q){ T.innerHTML = panel(\"Carregando questão...\", \"\"); document.getElementById(\"back\").onclick = leaveRoom; return; }\n  const order = validOrder(st.order, q) || q[4].map((_, i) => i);\n  const revealed = st.phase === \"rev\";\n  const amOwner = isOwner();\n  const canCtl = canControl();\n  const ownerOnline = people.some(p => p.owner);\n  const ctlOnline = people.some(p => p.owner || isHelperPid(st, p.pid));\n  if (g.ans && g.ans.q !== q[0]) g.ans = null;\n  const mine = g.ans ? g.ans.c : (revealed && g.ansHist && Number.isInteger(g.ansHist[q[0]]) ? g.ansHist[q[0]] : null);\n\n  const answers = {};\n  people.forEach(p => { const a = p.presence.ans; if (a && a.q === q[0] && Number.isInteger(a.c)) answers[p.peer] = a.c; });\n  if (mine != null && g.myPeer) answers[g.myPeer] = mine;\n  const answeredCount = people.filter(p => p.peer in answers).length;\n\n  const chips = people.map(p => {\n    const done = p.peer in answers;\n    const me = p.peer === g.myPeer;\n    const helper = !p.owner && isHelperPid(st, p.pid);\n    return `<span class=\"person${done ? \" done\" : \"\"}${p.owner ? \" lead\" : \"\"}${helper ? \" helper\" : \"\"}\" data-vpeer=\"${me ? \"me\" : p.peer}\"><span class=\"dot\"></span>${esc(p.presence.name)}${me ? \" (você)\" : \"\"}${p.owner ? \" · dono\" : \"\"}${helper ? \" · pode revelar\" : \"\"}${p.presence.voice ? \" · na voz\" : \"\"}</span>`;\n  }).join(\"\");\n\n  const opts = order.map((oi, pos) => {\n    let cls = \"\";\n    if (revealed) cls = oi === q[5] ? \" right\" : (oi === mine ? \" wrong\" : \" dim\");\n    else if (oi === mine) cls = \" picked\";\n    let who = \"\";\n    if (revealed){\n      const names = people.filter(p => answers[p.peer] === oi).map(p => esc(p.presence.name) + (p.peer === g.myPeer ? \" (você)\" : \"\"));\n      if (names.length) who = `<span class=\"chose\">Marcaram: ${names.join(\", \")}</span>`;\n    }\n    return `<button class=\"opt${cls}\" data-i=\"${oi}\" ${revealed ? \"disabled\" : \"\"}><span class=\"l\">${LETTERS[pos]}</span><span>${q[4][oi]}${who}</span></button>`;\n  }).join(\"\");\n\n  const qTopic = TOPICS[q[1]] ? TOPICS[q[1]].name : \"\";\n  const t = qTopic;\n  const dq = (st.due || {})[st.qid];\n  const kind = !dq ? \"Nova\" : dq[0] > (st.qStart || 0) + 1000 ? \"Revisão antecipada\" : \"Revisão\";\n  let fb = \"\";\n  if (revealed){\n    const verdict = mine == null ? `<div class=\"verdict\">Você não respondeu esta.</div>`\n      : mine === q[5] ? `<div class=\"verdict ok\">Você acertou!</div>` : `<div class=\"verdict no\">Você errou. A correta é a ${LETTERS[order.indexOf(q[5])]}.</div>`;\n    fb = `<div class=\"fb\">${verdict}${explainHTML(q, order)}</div>`;\n  }\n  let status = \"\";\n  if (!revealed){\n    const wait = canCtl ? \"\" : ctlOnline ? \". Aguardando revelarem a resposta.\" : \". O dono está fora agora; a sala continua e a resposta é revelada quando ele (ou alguém liberado) voltar.\";\n    status = `<div class=\"gstatus\">${answeredCount} de ${people.length} ${people.length === 1 ? \"respondeu\" : \"responderam\"}${wait}</div>`;\n  } else if (!canCtl){\n    status = `<div class=\"gstatus\">${ctlOnline ? \"Quem controla a sala escolhe quando essa questão volta.\" : \"O dono está fora agora. A próxima questão aparece quando ele (ou alguém liberado) voltar.\"}</div>`;\n  }\n  const r0 = dq ? dq[1] : 0;\n  const rateBtns = `<div class=\"rate g-rate\"><p>Quando essa questão volta para a sala?</p>\n      <div class=\"rbtns four\">\n        <button class=\"rbtn again\" data-g=\"again\">Errei<small>volta em ${fmtMins(grpMins(\"again\", r0))}</small></button>\n        <button class=\"rbtn hard\" data-g=\"hard\">Difícil<small>volta em ${fmtMins(grpMins(\"hard\", r0))}</small></button>\n        <button class=\"rbtn good\" data-g=\"good\">Médio<small>volta em ${fmtMins(grpMins(\"good\", r0))}</small></button>\n        <button class=\"rbtn easy\" data-g=\"easy\">Fácil<small>volta em ${fmtMins(grpMins(\"easy\", r0))}</small></button>\n      </div></div>`;\n  const hostCtl = canCtl ? `${revealed ? rateBtns : \"\"}<div class=\"hostbar\">\n      <button class=\"ghost\" id=\"prevQ\" ${st.histLen ? \"\" : \"disabled\"} title=\"${st.histLen ? \"Voltar para a questão anterior\" : \"Ainda não há questão anterior\"}\">← Questão anterior</button>\n      ${revealed ? \"\" : `<button class=\"primary\" id=\"reveal\">Revelar resposta</button>`}\n      ${amOwner ? `<button class=\"ghost\" id=\"end\">Encerrar sala</button>` : \"\"}</div>\n      <div class=\"gstatus\">${amOwner ? \"Se você sair, a sala continua aberta. Para voltar como dono, entre de novo neste aparelho.\" : \"O dono liberou você para revelar a resposta e passar as questões.\"}</div>` : \"\";\n\n  T.innerHTML = top + `<div class=\"people\">${chips}</div>\n    <article class=\"qcard\">\n      <div class=\"src\"><span>${q[2]}</span><span class=\"tag\">${kind} · ${esc(t)}</span></div>\n      <p class=\"qtext\">${q[3]}</p>\n      <div class=\"opts\" role=\"group\" aria-label=\"Alternativas\">${opts}</div>\n      ${status}${fb}${hostCtl}\n    </article>`;\n\n  document.getElementById(\"back\").onclick = leaveRoom;\n  if (!revealed) T.querySelectorAll(\".opt\").forEach(b => b.onclick = () => pickAnswer(q[0], +b.dataset.i));\n  if (revealed){ const saved = session; session = { order }; addReasons(q, mine); session = saved; }\n  const r = document.getElementById(\"reveal\"); if (r) r.onclick = hostReveal;\n  const pv = document.getElementById(\"prevQ\"); if (pv) pv.onclick = hostBack;\n  T.querySelectorAll(\".g-rate .rbtn\").forEach(b => b.onclick = () => hostRate(b.dataset.g));\n  const e = document.getElementById(\"end\"); if (e) e.onclick = hostEnd;\n  bindTopicBar(st);\n  groupTick();\n  renderChat(false);\n}\n\n/* =========================================================\n   CONTA (login simples: usuário + senha)\n   O progresso fica no aparelho e é sincronizado com a conta.\n   ========================================================= */\nconst CONTA_KEY = \"patologia-n1-conta\";\nlet conta = roomStatus === \"ok\" ? loadJSON(CONTA_KEY, null) : null;   // { user, token }\nlet syncT = null, syncing = false, dirty = false;\n\nasync function api(path, method, body){\n  const headers = { \"content-type\": \"application/json\" };\n  if (conta){ headers[\"x-user\"] = conta.user; headers[\"authorization\"] = \"Bearer \" + conta.token; }\n  const txt = body ? JSON.stringify(body) : undefined;\n  const r = await fetch(path, { method, headers, body: txt, keepalive: !!(txt && txt.length < 60000) });\n  let data = null; try { data = await r.json(); } catch(e){}\n  return { status: r.status, data };\n}\n\n/* junta o progresso da conta com o deste aparelho sem perder nada */\nfunction mergeProgress(remote){\n  if (!remote) return;\n  const rs = remote.srs || {};\n  Object.keys(rs).forEach(id => {\n    if (!VALID_IDS.has(id) || !rs[id] || typeof rs[id] !== \"object\") return;\n    const a = state[id], b = rs[id];\n    if (!a || (b.t || 0) > (a.t || 0) || ((b.t || 0) === (a.t || 0) && (b.n || 0) > (a.n || 0))) state[id] = b;\n  });\n  const rh = remote.hist || {};\n  Object.keys(rh).forEach(d => {\n    const y = rh[d]; if (!Array.isArray(y) || !/^\\d{4}-\\d{2}-\\d{2}$/.test(d)) return;\n    const x = hist[d] || [0, 0];\n    hist[d] = [Math.max(x[0], y[0] | 0), Math.max(x[1], y[1] | 0)];\n  });\n}\n\nfunction schedulePush(){ if (!conta) return; dirty = true; clearTimeout(syncT); syncT = setTimeout(push, 1500); }\nasync function push(){\n  if (!conta || syncing) return;\n  syncing = true; dirty = false;\n  try {\n    const r = await api(\"/api/progresso\", \"PUT\", { prog: { srs: state, hist } });\n    if (r.status === 401) sessionExpired();\n    else if (r.status !== 200) dirty = true;\n  } catch(e){ dirty = true; }\n  syncing = false;\n  if (dirty && conta){ clearTimeout(syncT); syncT = setTimeout(push, 10000); }\n}\nasync function pull(){\n  try {\n    const r = await api(\"/api/progresso\", \"GET\");\n    if (r.status === 401){ sessionExpired(); return false; }\n    if (r.status !== 200) return false;\n    mergeProgress(r.data && r.data.prog);\n    save();\n    return true;\n  } catch(e){ return false; }\n}\nonProgressSaved = schedulePush;\ndocument.addEventListener(\"visibilitychange\", () => {\n  if (document.visibilityState === \"hidden\" && conta && dirty) push();\n  if (document.visibilityState === \"visible\" && conta && !dirty) pull().then(ok => { if (ok && view === \"home\") renderHome(); });\n});\nwindow.addEventListener(\"online\", () => { if (conta && dirty) push(); });\n\nfunction sessionExpired(){\n  conta = null; saveJSON(CONTA_KEY, null);\n  if (view === \"home\") renderHome();\n}\n\nacctInfo = () => conta\n  ? `<div class=\"acct in\"><span>Conta <b>${esc(conta.user)}</b>. Seu progresso fica salvo nela e aparece em qualquer aparelho.</span></div>`\n  : (roomStatus === \"ok\" ? `<div class=\"acct\"><span>Crie uma conta para guardar sua evolução e usar em qualquer aparelho.</span><button class=\"ghost\" id=\"loginBtn2\">Entrar ou criar conta</button></div>` : \"\");\n\nfunction refreshAcct(){\n  const el = document.getElementById(\"acctSlot\");\n  if (!el || roomStatus !== \"ok\") return;\n  el.innerHTML = conta\n    ? `<div class=\"acct in\"><span>Olá, <b>${esc(conta.user)}</b>! Progresso salvo na sua conta.</span><button class=\"linkbtn\" id=\"logout\">Sair da conta</button></div>`\n    : `<div class=\"acct\"><span>Crie uma conta para salvar seu progresso e usar em qualquer aparelho.</span><button class=\"primary\" id=\"loginBtn\">Entrar ou criar conta</button></div>`;\n  const lb = document.getElementById(\"loginBtn\"); if (lb) lb.onclick = () => renderLogin(\"entrar\");\n  const lo = document.getElementById(\"logout\"); if (lo) lo.onclick = logout;\n}\ndocument.addEventListener(\"click\", e => { if (e.target && e.target.id === \"loginBtn2\") renderLogin(\"entrar\"); });\n\nasync function logout(){\n  if (!confirm(\"Sair da conta? Seu progresso continua salvo nela. Este aparelho fica vazio até você entrar de novo.\")) return;\n  clearTimeout(syncT);\n  if (dirty) await push();\n  try { await api(\"/api/sair\", \"POST\", {}); } catch(e){}\n  conta = null; saveJSON(CONTA_KEY, null);\n  state = {}; hist = {}; save();\n  online.admin = false; renderAdminPanel();\n  if (online.ws){ try { online.ws.close(); } catch(e){} }\n  renderHome();\n}\n\nfunction renderLogin(mode){\n  view = \"login\";\n  const criar = mode === \"criar\";\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>${criar ? \"Criar conta\" : \"Entrar\"}</h3></div></div>\n    <div class=\"panel\">\n      <div class=\"tabs\"><button class=\"${criar ? \"\" : \"on\"}\" id=\"tabIn\">Entrar</button><button class=\"${criar ? \"on\" : \"\"}\" id=\"tabNew\">Criar conta</button></div>\n      <h2>${criar ? \"Criar sua conta\" : \"Entrar na sua conta\"}</h2>\n      <p>${criar ? \"Só usuário e senha. O progresso que você já tem neste aparelho vai junto para a conta.\" : \"Seu progresso volta do ponto em que parou, em qualquer aparelho.\"}</p>\n      <div class=\"field\"><label for=\"lu\">Usuário</label><input id=\"lu\" autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"20\" placeholder=\"ex.: marco.med\" value=\"${esc(getName().toLowerCase().replace(/[^a-z0-9._]/g, \"\"))}\"></div>\n      <div class=\"field\"><label for=\"lp\">Senha</label><input id=\"lp\" type=\"password\" autocomplete=\"${criar ? \"new-password\" : \"current-password\"}\" maxlength=\"64\" placeholder=\"mínimo 4 caracteres\"></div>\n      ${criar ? `<div class=\"field\"><label for=\"lp2\">Repita a senha</label><input id=\"lp2\" type=\"password\" autocomplete=\"new-password\" maxlength=\"64\"></div>\n      <div class=\"warn\">Anote sua senha. Como a conta não usa e-mail, não tem como recuperar uma senha esquecida.</div>` : \"\"}\n      <div class=\"row\" style=\"justify-content:flex-start\"><button class=\"primary\" id=\"go\" style=\"width:auto;margin:0\">${criar ? \"Criar conta\" : \"Entrar\"}</button></div>\n      <div id=\"lmsg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"tabIn\").onclick = () => renderLogin(\"entrar\");\n  document.getElementById(\"tabNew\").onclick = () => renderLogin(\"criar\");\n  const msg = t => document.getElementById(\"lmsg\").innerHTML = t ? `<div class=\"msg bad\">${t}</div>` : \"\";\n  const go = async () => {\n    const user = document.getElementById(\"lu\").value.trim().toLowerCase();\n    const senha = document.getElementById(\"lp\").value;\n    if (!/^[a-z0-9._]{3,20}$/.test(user)) return msg(\"O usuário precisa ter de 3 a 20 caracteres: letras sem acento, números, ponto ou _.\");\n    if (senha.length < 4) return msg(\"A senha precisa ter pelo menos 4 caracteres.\");\n    if (criar && senha !== document.getElementById(\"lp2\").value) return msg(\"As duas senhas não são iguais.\");\n    const btn = document.getElementById(\"go\"); btn.disabled = true; btn.textContent = \"Aguarde...\";\n    let r;\n    try { r = await api(criar ? \"/api/criar\" : \"/api/entrar\", \"POST\", { user, senha }); }\n    catch(e){ btn.disabled = false; btn.textContent = criar ? \"Criar conta\" : \"Entrar\"; return msg(\"Sem conexão. Confira sua internet.\"); }\n    if (r.status !== 200 || !r.data || !r.data.token){\n      btn.disabled = false; btn.textContent = criar ? \"Criar conta\" : \"Entrar\";\n      return msg((r.data && r.data.erro) || \"Não deu certo. Tente de novo.\");\n    }\n    conta = { user, token: r.data.token };\n    saveJSON(CONTA_KEY, conta);\n    if (!getNameSaved()) setName(user);\n    await pull();          // traz o que já está na conta e junta com o deste aparelho\n    await push();          // guarda a junção na conta\n    renderHome();\n    checkAdmin();\n  };\n  document.getElementById(\"go\").onclick = go;\n  app.querySelectorAll(\".panel input\").forEach(i => i.addEventListener(\"keydown\", e => { if (e.key === \"Enter\") go(); }));\n  document.getElementById(\"lu\").focus();\n}\n\n/* ao abrir o site já logado: busca a versão mais nova do progresso */\nif (conta) pull().then(ok => { if (ok && view === \"home\") renderHome(); push(); });\n\n/* =========================================================\n   QUEM ESTÁ ONLINE (painel lateral só do dono do site)\n   Todo aparelho avisa discretamente onde está no site;\n   só a conta registrada como dono recebe a lista.\n   ========================================================= */\nconst online = { ws: null, peer: null, retry: 0, lastSent: \"\", admin: false, list: [], skew: 0, pingT: null };\n\n/* ---------- Versão nova publicada: atualiza sozinho quando é seguro ---------- */\nconst SITE_VERSION = \"92d38f1e24\";\nlet updatePending = false;\nfunction showUpdate(){\n  if (updatePending) return;\n  updatePending = true;\n  if ([\"home\", \"evo\", \"end\", \"empty\"].includes(view)){ location.reload(); return; }   // telas sem nada a perder\n  if (document.getElementById(\"updBar\")) return;\n  const el = document.createElement(\"div\");\n  el.id = \"updBar\"; el.className = \"updbar\"; el.setAttribute(\"role\", \"status\");\n  el.innerHTML = `<span>O site foi atualizado.</span><button id=\"updGo\">Atualizar agora</button>`;\n  document.body.appendChild(el);\n  document.getElementById(\"updGo\").onclick = () => location.reload();\n}\nconst PAINEL_KEY = \"patologia-n1-painel\";\n\nfunction devType(){\n  const ua = navigator.userAgent || \"\";\n  const menor = Math.min(screen.width || 9999, screen.height || 9999);\n  if (/iPad|Tablet/i.test(ua) || (/Android/i.test(ua) && !/Mobile/i.test(ua))) return \"tablet\";\n  if (/Mobi|iPhone|Android/i.test(ua) || menor < 600) return \"celular\";\n  return \"computador\";\n}\nfunction whereNow(){\n  let w = \"No site\";\n  try {\n    if (view === \"home\") w = \"Tela inicial\";\n    else if ((view === \"card\" || view === \"wait\") && session) w = \"Estudando sozinho: \" + topicName(session.topic);\n    else if (view === \"end\") w = \"Terminou uma sessão\";\n    else if (view === \"evo\") w = \"Vendo a própria evolução\";\n    else if (view === \"g-lobby\") w = \"Escolhendo sala de grupo\";\n    else if (view === \"g-room\" && group) w = \"Estudo em grupo, sala \" + group.code + (group.state ? \" (\" + roomTopicName(group.state.topic) + \")\" : \"\");\n    else if (view === \"login\") w = \"Entrando na conta\";\n    else if (view === \"backup\") w = \"Backup do progresso\";\n    else if (view === \"empty\") w = \"Revisões em dia\";\n    else if (view === \"dono\") w = \"Área do dono\";\n  } catch(e){}\n  if (document.visibilityState === \"hidden\") w += \" (site em segundo plano)\";\n  return w;\n}\nfunction myOnlineInfo(){\n  return { name: (conta && conta.user) || getNameSaved() || \"Visitante\", user: conta ? conta.user : null, where: whereNow(), dev: devType() };\n}\nfunction onlineSend(force){\n  if (!online.ws || online.ws.readyState !== 1) return;\n  const info = myOnlineInfo(), k = JSON.stringify(info);\n  if (!force && k === online.lastSent) return;\n  online.lastSent = k;\n  online.ws.send(JSON.stringify({ t: \"here\", info }));\n}\nfunction onlineAdminHello(){\n  if (online.admin && conta && online.ws && online.ws.readyState === 1) online.ws.send(JSON.stringify({ t: \"admin\", user: conta.user, token: conta.token }));\n}\nfunction onlineConnect(){\n  if (roomStatus !== \"ok\") return;\n  const proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n  const s = new WebSocket(proto + \"//\" + location.host + \"/ws-online\");\n  online.ws = s;\n  s.onopen = () => {\n    online.retry = 0; onlineSend(true); onlineAdminHello();\n    clearInterval(online.pingT);\n    online.pingT = setInterval(() => { try { s.send(\"ping\"); } catch(e){} }, 30000);\n  };\n  s.onmessage = e => {\n    if (e.data === \"pong\") return;\n    let m; try { m = JSON.parse(e.data); } catch(err){ return; }\n    if (m.t === \"hi\"){ online.peer = m.peer; if (m.v && m.v !== SITE_VERSION) showUpdate(); }\n    else if (m.t === \"online\"){ online.list = m.list || []; if (typeof m.now === \"number\") online.skew = m.now - Date.now(); renderAdminPanel(); }\n    else if (m.t === \"notadmin\"){ online.admin = false; renderAdminPanel(); }\n  };\n  s.onclose = () => {\n    if (online.ws !== s) return;\n    clearInterval(online.pingT);\n    setTimeout(onlineConnect, Math.min(15000, 1000 * Math.pow(2, online.retry++)));\n  };\n}\nsetInterval(() => onlineSend(false), 3000);\ndocument.addEventListener(\"visibilitychange\", () => onlineSend(false));\n\nasync function checkAdmin(){\n  if (!conta){ online.admin = false; renderAdminPanel(); return; }\n  try {\n    const r = await api(\"/api/eu\", \"GET\");\n    online.admin = r.status === 200 && !!(r.data && r.data.admin);\n  } catch(e){}\n  onlineAdminHello();\n  renderAdminPanel();\n}\n\nfunction fmtAgo(ms){\n  const m = Math.floor(Math.max(0, ms) / 60000);\n  if (m < 1) return \"menos de 1 min\";\n  if (m < 60) return m + \" min\";\n  const h = Math.floor(m / 60);\n  return h + \" h\" + (m % 60 ? \" \" + (m % 60) + \" min\" : \"\");\n}\nfunction renderAdminPanel(){\n  let el = document.getElementById(\"adminPanel\");\n  if (!online.admin){\n    if (el) el.remove();\n    document.body.classList.remove(\"admin-open\");\n    return;\n  }\n  if (!el){ el = document.createElement(\"aside\"); el.id = \"adminPanel\"; el.className = \"admin\"; el.setAttribute(\"aria-label\", \"Quem está online no site\"); document.body.appendChild(el); }\n  const open = loadJSON(PAINEL_KEY, true) !== false;\n  el.classList.toggle(\"open\", open);\n  document.body.classList.toggle(\"admin-open\", open);\n  const now = Date.now() + online.skew;\n  const list = online.list.slice().sort((a, b) => (a.desde || 0) - (b.desde || 0));\n  const semConta = list.filter(x => !x.info.user).length;\n  el.innerHTML = `\n    <div class=\"admin-body\">\n      <div class=\"admin-h\"><div class=\"admin-top\"><b>Online no site agora</b><button class=\"vbtn\" id=\"adminHide\">Esconder</button></div><small>${list.length} ${list.length === 1 ? \"pessoa\" : \"pessoas\"}${semConta ? `, ${semConta} sem conta` : \"\"}. Só você vê este painel.</small></div>\n      <ul class=\"admin-list\">${list.length ? list.map(x => `\n        <li>\n          <div class=\"an\"><span class=\"adot\"></span><b>${esc(x.info.name)}</b>${x.peer === online.peer ? \" <em>(você)</em>\" : \"\"}</div>\n          <div class=\"aw\">${esc(x.info.where || \"No site\")}</div>\n          <div class=\"am\">${x.info.user ? \"conta \" + esc(x.info.user) : \"sem conta\"}${x.info.dev ? \", \" + esc(x.info.dev) : \"\"}, há ${fmtAgo(now - (x.desde || now))}</div>\n        </li>`).join(\"\") : `<li class=\"aempty\">Ninguém online agora.</li>`}</ul>\n    </div>\n    <button class=\"admin-tab\" id=\"adminTab\" aria-expanded=\"${open}\" title=\"${open ? \"Esconder painel\" : \"Mostrar quem está online\"}\"><span class=\"adot\"></span>${list.length}<span class=\"atxt\"> online</span></button>`;\n  document.getElementById(\"adminTab\").onclick = () => { saveJSON(PAINEL_KEY, true); renderAdminPanel(); };\n  document.getElementById(\"adminHide\").onclick = () => { saveJSON(PAINEL_KEY, false); renderAdminPanel(); };\n}\nsetInterval(() => { if (online.admin) renderAdminPanel(); }, 30000);\n\n/* ---------- Área do dono: registrar a conta como dona do site ---------- */\nfunction renderDono(){\n  view = \"dono\";\n  app.classList.remove(\"in-room\", \"chat-open\");\n  const top = `<div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Área do dono</h3></div></div>`;\n  if (!conta){\n    app.innerHTML = top + `<div class=\"panel\"><h2>Entre na sua conta primeiro</h2><p>O painel do dono fica preso à sua conta do site. Entre (ou crie a conta) e volte aqui.</p><button class=\"primary\" id=\"goLogin\">Entrar ou criar conta</button></div>`;\n    document.getElementById(\"back\").onclick = renderHome;\n    document.getElementById(\"goLogin\").onclick = () => renderLogin(\"entrar\");\n    return;\n  }\n  if (online.admin){\n    app.innerHTML = top + `<div class=\"panel\"><h2>Você é o dono do site</h2><p>A conta <b>${esc(conta.user)}</b> está registrada como dona. O painel de quem está online aparece na esquerda em qualquer aparelho em que você entrar com essa conta.</p><button class=\"primary\" id=\"back2\">Voltar ao início</button></div>`;\n    document.getElementById(\"back\").onclick = renderHome;\n    document.getElementById(\"back2\").onclick = renderHome;\n    return;\n  }\n  app.innerHTML = top + `<div class=\"panel\">\n      <h2>Registrar como dono</h2>\n      <p>Digite o código secreto do dono. Isso é feito uma vez só, e fica valendo para a conta <b>${esc(conta.user)}</b> em qualquer aparelho.</p>\n      <div class=\"field\"><label for=\"dcode\">Código do dono</label><input id=\"dcode\" autocomplete=\"off\" autocapitalize=\"characters\" spellcheck=\"false\" placeholder=\"DONO-XXXX-XXXX\" maxlength=\"20\"></div>\n      <div class=\"row\" style=\"justify-content:flex-start\"><button class=\"primary\" id=\"dgo\" style=\"width:auto;margin:0\">Confirmar</button></div>\n      <div id=\"dmsg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  const go = async () => {\n    const codigo = document.getElementById(\"dcode\").value.trim();\n    if (!codigo) return;\n    const btn = document.getElementById(\"dgo\"); btn.disabled = true;\n    let r; try { r = await api(\"/api/dono\", \"POST\", { codigo }); } catch(e){ r = { status: 0 }; }\n    btn.disabled = false;\n    if (r.status === 200){ await checkAdmin(); renderDono(); return; }\n    document.getElementById(\"dmsg\").innerHTML = `<div class=\"msg bad\">${esc((r.data && r.data.erro) || \"Não deu certo. Tente de novo.\")}</div>`;\n  };\n  document.getElementById(\"dgo\").onclick = go;\n  document.getElementById(\"dcode\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\") go(); });\n}\n\nonlineConnect();\ncheckAdmin();\n\n/* atalhos de teclado */\ndocument.addEventListener(\"keydown\", e => {\n  if (e.altKey || e.ctrlKey || e.metaKey) return;\n  const tg = e.target && e.target.tagName;\n  if (tg === \"INPUT\" || tg === \"TEXTAREA\") return;\n  if (view !== \"card\" || !session || session.disc) return;\n  const k = e.key.toLowerCase();\n  if (!session.answered){\n    const idx = [\"a\",\"b\",\"c\",\"d\",\"e\"].indexOf(k);\n    if (idx > -1 && idx < session.order.length){ e.preventDefault(); answer(session.order[idx]); }\n    return;\n  }\n  const cont = document.getElementById(\"cont\");\n  if (cont){ if (k === \"enter\" || k === \" \"){ e.preventDefault(); rate(\"again\"); } return; }\n  if (k === \"1\"){ e.preventDefault(); rate(\"hard\"); }\n  else if (k === \"2\" || k === \"enter\"){ e.preventDefault(); rate(\"good\"); }\n  else if (k === \"3\"){ e.preventDefault(); rate(\"easy\"); }\n});\n\nrenderHome();\n(function voltarParaSala(){\n  const sv = loadJSON(SALA_KEY, null);\n  if (sv && sv.code && roomStatus === \"ok\") joinRoom(cleanCode(sv.code), sv.name || getName() || \"Alguém\", sv.ans);\n})();\n</script>\n</body>\n</html>\n";
